PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      salt TEXT NOT NULL,
      is_admin INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE sessions (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL REFERENCES users(id),
      expires_at TEXT NOT NULL
    );
CREATE TABLE tracks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      slug TEXT UNIQUE NOT NULL,
      name TEXT NOT NULL,
      description TEXT,
      language TEXT,
      color TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      is_deleted INTEGER DEFAULT 0,
      is_archived INTEGER DEFAULT 0
    );
CREATE TABLE courses (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      slug TEXT NOT NULL,
      name TEXT NOT NULL,
      track_id INTEGER REFERENCES tracks(id),
      difficulty TEXT DEFAULT 'Unknown',
      order_in_track INTEGER,
      status TEXT DEFAULT 'Not Started',
      notes TEXT,
      reviewed TEXT DEFAULT 'No',
      has_pdf INTEGER DEFAULT 0,
      has_glossary INTEGER DEFAULT 0,
      is_deleted INTEGER DEFAULT 0,
      is_archived INTEGER DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now'))
    , notes_taken INTEGER DEFAULT 0);
CREATE TABLE track_courses (
      track_id INTEGER NOT NULL REFERENCES tracks(id),
      course_id INTEGER NOT NULL REFERENCES courses(id),
      order_in_track INTEGER,
      PRIMARY KEY (track_id, course_id)
    );
CREATE TABLE concepts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      course_id INTEGER REFERENCES courses(id),
      name TEXT NOT NULL,
      definition TEXT,
      code_snippet TEXT,
      source_page INTEGER,
      category TEXT,
      difficulty INTEGER DEFAULT 1,
      created_at TEXT DEFAULT (datetime('now'))
    );
CREATE TABLE flashcards (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      concept_id INTEGER REFERENCES concepts(id),
      course_id INTEGER REFERENCES courses(id),
      front TEXT NOT NULL,
      back TEXT NOT NULL,
      next_review_date TEXT DEFAULT (date('now')),
      interval_days INTEGER DEFAULT 1,
      ease_factor REAL DEFAULT 2.5,
      repetitions INTEGER DEFAULT 0
    );
CREATE TABLE quiz_questions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      course_id INTEGER REFERENCES courses(id),
      concept_id INTEGER REFERENCES concepts(id),
      question_text TEXT NOT NULL,
      option_a TEXT,
      option_b TEXT,
      option_c TEXT,
      option_d TEXT,
      correct_option TEXT,
      explanation TEXT,
      question_type TEXT,
      difficulty INTEGER DEFAULT 1
    );
CREATE TABLE deleted_questions (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id),
      course_slug TEXT NOT NULL,
      exercise_type TEXT NOT NULL,
      question_id TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      UNIQUE(user_id, exercise_type, question_id)
    );
CREATE TABLE user_tracks (
      user_id INTEGER NOT NULL REFERENCES users(id),
      track_id INTEGER NOT NULL REFERENCES tracks(id),
      is_deleted INTEGER DEFAULT 0,
      is_archived INTEGER DEFAULT 0,
      PRIMARY KEY (user_id, track_id)
    );
CREATE TABLE user_courses (
      user_id INTEGER NOT NULL REFERENCES users(id),
      course_id INTEGER NOT NULL REFERENCES courses(id),
      status TEXT DEFAULT 'Not Started',
      difficulty TEXT DEFAULT 'Unknown',
      notes TEXT,
      reviewed TEXT DEFAULT 'No',
      is_deleted INTEGER DEFAULT 0,
      is_archived INTEGER DEFAULT 0, notes_taken INTEGER DEFAULT 0,
      PRIMARY KEY (user_id, course_id)
    );
CREATE TABLE user_flashcard_progress (
      user_id INTEGER NOT NULL REFERENCES users(id),
      flashcard_id INTEGER NOT NULL REFERENCES flashcards(id),
      interval_days INTEGER DEFAULT 1,
      ease_factor REAL DEFAULT 2.5,
      repetitions INTEGER DEFAULT 0,
      next_review_date TEXT DEFAULT (date('now')),
      PRIMARY KEY (user_id, flashcard_id)
    );
CREATE TABLE user_stats (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER UNIQUE REFERENCES users(id),
      total_xp INTEGER DEFAULT 0,
      level TEXT DEFAULT 'Beginner',
      current_streak INTEGER DEFAULT 0,
      longest_streak INTEGER DEFAULT 0,
      last_active_date TEXT,
      badges_json TEXT DEFAULT '[]'
    );
CREATE TABLE mastery_scores (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER REFERENCES users(id),
      course_id INTEGER REFERENCES courses(id),
      flashcard_score REAL DEFAULT 0,
      quiz_score REAL DEFAULT 0,
      code_score REAL DEFAULT 0,
      dataset_score REAL DEFAULT 0,
      matching_score REAL DEFAULT 0,
      boss_score REAL DEFAULT 0,
      incorrect_score REAL DEFAULT 0,
      overall_mastery REAL DEFAULT 0,
      updated_at TEXT DEFAULT (datetime('now')),
      UNIQUE(user_id, course_id)
    );
CREATE TABLE exercise_attempts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER REFERENCES users(id),
      course_id INTEGER REFERENCES courses(id),
      concept_id TEXT DEFAULT NULL,
      exercise_type TEXT NOT NULL,
      question_id TEXT,
      was_correct INTEGER,
      score REAL DEFAULT 0,
      attempted_at TEXT DEFAULT (datetime('now'))
    , time_taken_secs INTEGER DEFAULT NULL);
CREATE TABLE spaced_repetition_queue (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id),
      flashcard_id INTEGER NOT NULL REFERENCES flashcards(id),
      due_date TEXT,
      priority INTEGER DEFAULT 1,
      UNIQUE(user_id, flashcard_id)
    );
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
PRAGMA writable_schema=OFF;
COMMIT;
