INSERT INTO concepts VALUES(998,72,'print() function','Displays text or values to the console','print',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(999,72,'Arithmetic Operators','Exponentiation: 2 raised to the power of 3','**',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1000,72,'Variable','A named reference to a stored value','weight',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1001,72,'Assignment operator (=)','Operator that stores a value in a variable','=',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1002,72,'type() function','Returns the type of an object','type',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1003,72,'Type Conversion','Converts to integer, truncating decimal','int',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1004,72,'List','Creates a list of heights','[1.73,1.68,1.71]',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1005,72,'List of Lists','A nested list of lists','[[1.73],[1.68]]',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1006,72,'type(list)','The type() function confirms that the variable is a list. This is useful when debugging.','list',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1007,72,'Subsetting','Element at index 6 (seventh position)','6',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1008,72,'Negative Indexing','Last element of the list','-1',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1009,72,'Slicing','Elements at indices 3 and 4 (slice)','1',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1010,72,'List Element Modification','Replaces the element at index 7','7',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1011,72,'List Concatenation (+)','Returns a new concatenated list','+',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1012,72,'del statement','Removes element at index 2, shifting later items','del',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1013,72,'List Copying','Creates an independent copy of a list','list',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1014,72,'Reference vs Copy','Creates a reference, not a copy','x',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1015,72,'Function','Returns the largest value in the list','max',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1016,72,'max() function','max() works on any iterable of comparable items. Passing an empty iterable raises a ValueError.','fam',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1017,72,'round() function','Rounds to one decimal: 1.7','1',6,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1018,72,'help() function','Displays documentation for round','help',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1019,72,'Method','Calls a method on an object','capitalize',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1020,72,'list.index() method','Returns index of first ''mom'' (4)','''mom''',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1021,72,'list.count() method','Returns number of times 1.73 appears','count',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1022,72,'list.append() method','Modifies fam, but result is None','append',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1023,72,'str.capitalize() method','Returns ''Liz'', original unchanged','capitalize',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1024,72,'str.replace() method','Returns ''Lisa''','replace',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1025,72,'list.remove() method','Deletes first ''emma'', returns None','remove',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1026,72,'list.reverse() method','Reverses the list in place, returns None','reverse',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1027,72,'Import Statement','Imports whole module; use numpy.array()','import',8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1028,72,'Aliasing','Imports with alias; use np.array()','mean',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1029,72,'Selective Import','Imports only array, can use array() directly','from',8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1030,72,'Package','Collection of modules for a specific purpose','import',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1031,72,'np.array() function','Creates a 1D numeric array from a list','height',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1032,72,'Vectorization','Vectorized BMI calculation','**',9,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1033,72,'NumPy Homogeneous Type','All elements become strings (coercion)','dtype',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1034,72,'List vs Array Addition','List concatenates; array adds element‑wise','+',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1035,72,'Boolean Indexing (Masking)','Boolean indexing: returns elements over 23','>',9,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1036,72,'NumPy Array','NumPy arrays are homogeneous; all elements become the same type. This allows fast vectorized operations.','array',9,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1037,72,'2D NumPy Array','Creates a 2D array with two rows','[1.73,1.68,1.71]',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1038,72,'Array Shape','Returns (rows, columns) as tuple','shape',10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1039,72,'2D Array Subsetting','Element at row 0, column 2','0',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1040,72,'Slicing 2D Arrays','All rows, columns 1 and 2','1',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1041,72,'np.median()','Median of heights (robust to outliers)','median',11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1042,72,'np.mean()','Arithmetic average of array elements','mean',11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1043,72,'np.sum()','Total sum of all elements','sum',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1044,72,'np.sort()','Returns a sorted copy; original unchanged','sort',11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1045,72,'np.random.normal()','Generates 5000 samples from N(1.75, 0.20²)','1.75',11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1046,72,'np.round()','np.round() returns a new array with the specified decimals. Unlike built‑in round(), it can handle arrays directly.','round',11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1047,72,'np.column_stack()','Stacks 1D arrays as columns into 2D','height',11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1048,72,'Correlation (np.corrcoef)','Returns correlation matrix (2x2)','weight',11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1049,72,'Python','Python is known for its readability and extensive standard library. It''s interpreted, dynamically typed, and supports multiple programming paradigms.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1050,72,'Python Shell','Interactive command-line for one‑line commands',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1051,72,'Python Script','A .py file executed all at once',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1052,72,'Data Type','Python is dynamically typed — you don''t declare types, but every object has a type. Use type() to check.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1053,72,'Integer (int)','Whole number without decimal point',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1054,72,'Float','Number containing a decimal point',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1055,72,'String (str)','Text enclosed in quotes',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1056,72,'Boolean (bool)','Data type with values True or False',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1057,72,'BMI Calculation','BMI formula is weight divided by height squared. Using ^ for exponentiation would be a mistake — ^ is bitwise XOR.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1058,72,'Module','A single .py file with functions/variables',NULL,8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1059,72,'NumPy','NumPy''s core object is the ndarray. It enables vectorized operations and is almost always imported as np.',NULL,9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1060,72,'Outlier','Outliers can arise from measurement errors or genuine variability. Use the median for a more robust central value.',NULL,11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1061,72,'Conversion Factors','NumPy''s vectorization makes unit conversion a single line. Ensure the factor is correct to avoid scaling errors.',NULL,11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1062,73,'Matplotlib pyplot import','Standard alias for pyplot, provides MATLAB-like interface','import matplotlib.pyplot as plt',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1063,73,'plt.plot()','Line plot connecting consecutive data points','plt.plot',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1064,73,'plt.scatter()','Scatter plot with markers, no connecting lines','plt.scatter',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1065,73,'plt.show()','Displays the current figure; must be called after plotting','plt.show',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1066,73,'plt.hist()','Creates a histogram with 3 equal-width bins','bins',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1067,73,'plt.xlabel()','Adds a label to the x-axis','plt.xlabel',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1068,73,'plt.ylabel()','Adds a label to the y-axis','plt.ylabel',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1069,73,'plt.title()','Adds a title above the plot','plt.title',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1070,73,'plt.yticks()','Customizes y-axis tick positions and labels','[''0'',''2B'',''4B'',''6B'',''8B'',''10B'']',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1071,73,'Dictionary','Unordered collection of key-value pairs with unique immutable keys','''afghanistan''',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1072,73,'Key-Value Pair','Key-value pair in a dictionary','''algeria'': 39.21',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1073,73,'Dictionary access with []','Returns the value associated with key ''albania''','''albania''',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1074,73,'Adding key-value pair to dictionary','If the key does not exist, `dict[new_key] = value` adds it. If the key already exists, it updates the value.','''sealand''',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1075,73,'Updating dictionary value','Updating uses exactly the same syntax as adding. Python checks whether the key exists; if yes, it updates; if no, it adds.','''albania''',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1076,73,'del statement for dictionaries','`del` is used to delete dictionary entries. Unlike accessing with `[]`, there is no default value; the key must exist, otherwise a `KeyError` is raised.','del',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1077,73,'in operator for dictionaries','The `in` operator for dictionaries always tests membership in the keys. To check for a value, you would need `1 in d.values()`.','in',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1078,73,'pd.read_csv()','Reads CSV into DataFrame, using first column as row index','index_col',6,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1079,73,'DataFrame column selection with []','This is a subtle but important distinction. Many pandas operations behave differently depending on whether you have a Series or a DataFrame.','''country''',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1080,73,'DataFrame row slicing','When using integer slices on a DataFrame, the behavior is the same as list slicing: `[start:end]` includes `start` but excludes `end`.','1:4',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1081,73,'loc[] method','`loc` is purely label‑based. With integer labels, `loc[1:4]` includes both endpoints, which is different from standard Python slicing. This is a common source of confusion.','[''RU'',''IN'',''CH'']',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1082,73,'iloc[] method','`iloc` stands for ''integer location''. It only accepts integer indices, slices of integers, or boolean arrays. Passing strings or labels will raise an error.','[1,2,3]',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1083,73,'Comparison operators','<, <=, >, >=, ==, != return booleans','!=',8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1084,73,'Boolean operators (and, or, not)','Logical operators that combine boolean values','and',9,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1085,73,'np.logical_and()','Element-wise AND on arrays; returns boolean array','logical_and',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1086,73,'np.logical_or()','Element-wise OR on arrays; returns True if any input True per element','logical_or',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1087,73,'np.logical_not()','Element-wise NOT: flips True to False, False to True','logical_not',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1088,73,'if statement','Conditional execution: runs block if condition True','if',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1089,73,'else clause','Executes if preceding if condition is False','else',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1090,73,'elif clause','Short for ''else if''; checks condition only if previous if/elif were False','elif',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1091,73,'Modulo operator (%)','The modulo operator is commonly used for parity checks, cycling through values, and more. It is essential in many algorithms.','%',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1092,73,'Filtering DataFrame with boolean Series','Filtering with a boolean Series is a powerful way to subset rows. The Series must have the same index as the DataFrame.','>',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1093,73,'while loop','Repeats block as long as condition is True; must update condition','while',12,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1094,73,'for loop','Iterates over each item in a sequence (list, string, etc.)','for',13,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1095,73,'enumerate()','Returns index-value pairs when iterating','enumerate',13,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1096,73,'Loop over string','Strings are iterable; `for ch in word:` iterates over each character in the string.','for',13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1097,73,'dict.items() method','Iterates over dictionary key-value pairs','items',14,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1098,73,'np.nditer()','`np.nditer()` provides a efficient way to iterate over all elements of a multi‑dimensional array, regardless of the number of dimensions. The order is the standard C order.','nditer',14,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1099,73,'DataFrame iterrows() method','`iterrows()` is slow for large DataFrames because it creates a Series for each row. Additionally, modifying the DataFrame during iteration is error-prone. The best practice is to use vectorized operations: `brics[''new_col''] = brics[''area''] * 2`.','iterrows',15,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1100,73,'DataFrame apply() method','For string operations on a Series, the vectorized `.str` accessor is the most efficient and readable. `brics[''country''].str.upper()` applies `upper()` to every element in C speed. `apply` or list comprehensions are slower because they use Python iteration.','apply',15,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1101,73,'np.random.rand()','Returns 3x2 array of uniform random numbers between 0 and 1','rand',16,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1102,73,'np.random.seed()','Initializes generator for reproducible random sequences','seed',16,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1103,73,'np.random.randint()','Returns 0 or 1 randomly (coin toss) because high is exclusive','randint',16,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1104,73,'Random walk simulation','The code runs a random walk with 10 steps. Using `np.random.seed(123)` ensures reproducibility. From the course example, the resulting `tails` list ends with 3, so `tails[-1]` equals 3.','+',17,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1105,73,'Distribution of random walk endpoints','The random walk endpoint is the sum of 10 independent Bernoulli trials with p=0.5. This sum follows a binomial distribution with parameters n=10 and p=0.5. The histogram of many such endpoints will approximate this binomial distribution.','hist',18,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1106,73,'Histogram','Divides data into bins and counts frequencies per bin',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1107,73,'Immutable keys','Lists are mutable (unhashable); keys must be immutable',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1108,73,'pandas DataFrame','2D labeled structure with columns of potentially different types',NULL,6,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1109,73,'pandas Series','Returns a pandas Series (1D labeled array)',NULL,6,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1110,74,'.head()','Returns the first 5 rows (by default) of a DataFrame for quick inspection.','head',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1111,74,'.info()','Prints column names, data types, non‑null counts and memory usage; returns None.','info',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1112,74,'.shape','Attribute (no parentheses) returning a tuple (number of rows, number of columns).','shape',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1113,74,'.describe()','Computes count, mean, std, min, quartiles, max for numeric columns (by default).','describe',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1114,74,'.columns','Use `df.columns` to get the Index of column names.','columns',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1115,74,'.index','Attribute that returns the row labels of a DataFrame as an Index object.','index',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1116,74,'subsetting columns','For a DataFrame, use `dogs[[''weight_kg'']]` to get a single-column DataFrame.','''weight_kg''',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1117,74,'adding a new column','Column assignment via `df[''new_column''] = expression` adds the column directly to the DataFrame `df`; it modifies the original object in place.','/',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1118,74,'.value_counts()','Returns a Series of counts of unique values; set `normalize=True` for proportions.','normalize=True',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1119,74,'.to_numpy()','The returned array loses column labels and index.','to_numpy',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1120,74,'.sort_values()','Sorts a DataFrame by the values of one or more columns; returns a new DataFrame unless assigned.','ascending=False',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1121,74,'Boolean indexing','Filtering rows with a Boolean Series (mask), e.g., `df[df[''col''] > 10]`.','dogs[''height_cm''] > 50',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1122,74,'.isin()','`.isin()` returns a Boolean Series; passing a list is required.','dogs[''color''].isin([''Black'', ''Brown''])',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1123,74,'chaining operations','Method chaining enables concise data manipulation.','dogs[''bmi''] < 100',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1124,74,'.agg()','Applies the custom function `pct30` to the ''weight_kg'' column for a single summary value.','agg',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1125,74,'.cumsum()','For [24,24,17], the output is 24, 48, 65.','cumsum',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1126,74,'.drop_duplicates()','Removes duplicate rows based on all or specified columns; returns a new DataFrame by default.','subset=''color''',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1127,74,'.groupby()','Splits data into groups based on a column; must be followed by an aggregation to produce a DataFrame.','mean',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1128,74,'.set_index()','Moves one or more columns into the row index; returns a new DataFrame unless inplace=True.','''name''',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1129,74,'.reset_index()','Resets the index to default integers; use `drop=True` to discard the old index completely.','drop=True',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1130,74,'.loc[]','Label‑based indexer; slice endpoints are inclusive. Use with index values, not integer positions.','[''Bella'', ''Stella'']',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1131,74,'.iloc[]','Position‑based indexer; slice endpoints are exclusive. Uses integer indices starting at 0.','2:5, 1:4',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1132,74,'.dropna()','Removes rows (or columns) with missing values; `how=''all''` drops only if all values are NaN.','''all''',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1133,74,'.fillna()','Replaces NaN with a given value (e.g., 0) or uses a method like ''ffill'' for forward fill.','0',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1134,74,'.quantile()','`quantile(0.3)` returns the value below which 30% of the data falls.','0.3',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1135,74,'apply()','Vectorized operations like `** 2` are executed in optimized C code, avoiding Python loop overhead. `apply()` wraps a Python function call per element, which is significantly slower for large datasets.','lambda x: x**2',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1136,74,'multi‑level index (hierarchical index)','To subset inner levels, use tuples with `slice(None)` for outer levels.','[''color'', ''name'']',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1137,74,'slicing by dates','The index must be sorted for slicing to work reliably.','''2014-08-25'':''2016-09-16''',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1138,74,'margins in pivot_table','Margins are computed with whatever `aggfunc` you specified.','margins=True',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1139,74,'fill_value in pivot_table','The margins are computed from the aggregated data before filling NaN; `fill_value` is purely cosmetic.','fill_value=0',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1140,74,'pandas','Python package for data manipulation and visualization, providing DataFrame and Series.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1141,74,'DataFrame','A two‑dimensional labeled data structure, like a spreadsheet, holding rows and columns.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1142,74,'Series','A one‑dimensional labeled array that holds data for a single variable.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1143,74,'rectangular data','Data stored in rows (observations) and columns (variables) where all columns have equal length.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1144,74,'mask','A Boolean Series used to select rows; must align by index with the DataFrame.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1145,74,'.pivot_table()','Creates a spreadsheet‑style table aggregating data; default `aggfunc` is mean, not sum.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1146,74,'.mean()','Returns the arithmetic average of a Series; on a DataFrame it averages each numeric column.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1147,74,'slicing','Extracting a subset of rows/columns using index ranges; `.loc` slice is inclusive, `.iloc` exclusive.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1148,74,'.median()','Returns the middle value (50th percentile) of a Series.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1149,74,'dogs[''height_cm''].hist()','Creates a histogram plot for the ''height_cm'' Series; requires `plt.show()` to display.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1150,74,'.plot(kind=''bar'')','Creates a bar plot; typically used after grouping and aggregating data.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1151,74,'pd.read_csv()','Imports data from a CSV file into a DataFrame; uses comma as default delimiter.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1152,74,'.to_csv()','Exports a DataFrame to a CSV file; use `index=False` to avoid writing row numbers.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1153,75,'merge() method','Inner merge of two DataFrames on a common column.','merge',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1154,75,'suffixes parameter','Rename overlapping non‑key columns with the given tuple.','(''_ward'',''_cen'')',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1155,75,'Merging on multiple columns','Merge using a composite key of two columns.','[''address'',''zip'']',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1156,75,'Chaining merges','Chain two merges together, the second using the result of the first.','\',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1157,75,'left_on and right_on parameters','Specify different key column names in left and right DataFrames.','id',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1158,75,'Self join','Self join linking each movie to its sequel by matching sequel id to movie id.','sequel',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1159,75,'Merging on index','Merge using a named index level as the join key.','on',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1160,75,'MultiIndex merge','Merge on a MultiIndex with exactly matching level names and order.','[''movie_id'',''cast_id'']',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1161,75,'left_index and right_index parameters','Use the left DataFrame''s index and a column from the right as keys.','True',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1162,75,'isin() method','Return a boolean Series indicating membership of each gid in the other Series.','isin',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1163,75,'indicator parameter','Add a ''_merge'' column showing row origin (''both'',''left_only'',''right_only'').','indicator',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1164,75,'concat() method','Stack DataFrames vertically and reset row index.','concat',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1165,75,'ignore_index parameter (concat)','Discard old indices and assign a new 0‑based integer index.','ignore_index',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1166,75,'keys parameter (concat)','Create a MultiIndex with a top‑level label for each original DataFrame.','keys',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1167,75,'join parameter in concat','Keep only columns that exist in all concatenated DataFrames.','join',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1168,75,'validate parameter (merge)','Raise MergeError if keys are not unique in both tables.','validate',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1169,75,'verify_integrity parameter (concat)','Raise ValueError if the resulting index contains duplicates.','verify_integrity',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1170,75,'merge_ordered() function','Perform an ordered outer join, sorting results by the key column.','merge_ordered',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1171,75,'merge_asof() function','Match each left row to the nearest previous right row (backward).','merge_asof',4,'general',1,'2026-06-18 07:39:40');
