INSERT INTO concepts VALUES(1175,75,'Left join','Returns all rows from the left table and matching right rows, NaN otherwise.','how',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1176,75,'Right join','Returns all rows from the right table and matching left rows, NaN otherwise.','how',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1177,75,'Outer join','Returns all rows from both tables, filling NaN where there is no match.','outer',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1178,75,'Inner join','Returns only rows with matching keys in both tables.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1179,75,'One-to-one relationship','Every row in the left table is related to exactly one row in the right table.',NULL,1,'general',1,'2026-06-18 07:39:40');
