INSERT INTO concepts VALUES(1183,75,'Forward fill (ffill)','Forward fill missing values using the last valid observation.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1184,75,'Wide format','Each row is one subject, columns are different attributes.',NULL,4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1185,75,'Long format','Each row is one observation of a variable, with variable‑name and value columns.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1186,79,'Function definition using def','Starts a function definition, must end with a colon',':',1,'general',1,'2026-06-18 07:39:40');
