INSERT INTO concepts VALUES(1217,80,'enumerate() function','Returns (index, value) pairs starting at 0.','enumerate',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1218,80,'zip() function','Combines iterables element-wise into tuples.','zip',2,'general',2,'2026-06-18 07:39:40');
