INSERT INTO concepts VALUES(1221,80,'List comprehension','List comprehension adding 1 to each element.','num + 1',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1222,80,'For loop vs list comprehension','When logic is complex or involves side effects like printing.','num**2',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1223,80,'List comprehension with range()','[i for i in range(5)]','range',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1224,80,'Nested list comprehension','for j in range(2)','for num2 in range(6, 8)',4,'general',3,'2026-06-18 07:39:40');
