INSERT INTO concepts VALUES(1266,84,'ResultProxy.fetchall()','Each tuple represents a row with values in the order of the columns. Be careful with large results as they may consume a lot of memory.','rows',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1267,84,'ResultProxy.fetchmany()','If fewer rows remain, it returns just the remaining ones. It''s memory‑efficient for large queries.','fetchmany',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1268,84,'ResultProxy.keys()','Call `.keys()` before fetching all rows, because once the result is fully consumed, the keys may no longer be available.','columns',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1269,84,'pandas.read_sql_query()','Function that directly returns a DataFrame from a query','read_sql_query',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1270,84,'skiprows parameter (loadtxt)','The `skiprows` parameter tells `loadtxt` to ignore that many leading rows. With `skiprows=1`, the header is ignored, and the 10 data rows form the array. The shape will be (10, columns).','skiprows',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1271,84,'usecols parameter (loadtxt)','`numpy.loadtxt` uses zero‑based column indexing. Age is index 1 and Weight is index 3. Using one‑based indices like [2,4] is a common off‑by‑one mistake.','usecols',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1272,84,'dtype parameter (loadtxt)','The array `data` has string dtype, so attempting to add an integer (`10`) results in a TypeError. To do arithmetic, the array must have a numeric dtype.','dtype',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1273,84,'pickle.load()','Loads a pickled object from a binary file','''rb''',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1274,84,'INNER JOIN','Combines rows from two tables where the ON condition is true','INNER',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1275,84,'ON clause (SQL JOIN)','Specifies the equality condition for a SQL JOIN','=',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1276,84,'Flat file','A plain‑text file storing tabular data as rows/columns',NULL,1,'general',1,'2026-06-18 07:39:40');
