INSERT INTO concepts VALUES(1279,84,'CSV (Comma-Separated Values)','Comma‑Separated Values flat‑file format',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1280,84,'numpy.genfromtxt()','`genfromtxt` gracefully handles files with blanks or inconsistent entries by using placeholders and missing‑value markers.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1281,84,'Mixed datatypes','Columns contain different types (strings, floats, etc.)',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1282,84,'DataFrame','The DataFrame is the core of pandas. It provides methods like `.head()`, `.info()`, and `.to_numpy()`.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1283,84,'Pickle / serialization','Process of converting a Python object to/from a byte stream',NULL,2,'general',2,'2026-06-18 07:39:40');
