INSERT INTO concepts VALUES(1294,86,'year attribute (date)','Accesses the year component of a date object','year',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1295,86,'Adding timedelta to date','Arithmetic with `date` and `timedelta` returns a shifted date.','+',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1296,86,'date() constructor','Creates a date object with year, month, day as integers','date',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1297,86,'weekday() method','Returns day of week as integer, Monday=0','weekday',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1298,86,'Subtracting dates -> timedelta','Subtracting dates returns a timedelta','days',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1299,86,'isoformat() method (date)','Returns date as ''YYYY-MM-DD'' string','isoformat',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1300,86,'ISO 8601 format','Date strings like ''2017-11-05'' that sort chronologically','sorted',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1301,86,'isoformat() for datetime','For a datetime, `isoformat()` includes the time with a `T` separator.','isoformat',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1302,86,'Adding/subtracting timedelta to datetime','Arithmetic with `timedelta` and `datetime` returns a new `datetime`.','timedelta',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1303,86,'datetime() constructor','The datetime constructor expects integers in 24-hour format. 3 PM is hour 15. Option c gives the correct naive datetime.','datetime',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1304,86,'replace() method (datetime)','Returns new datetime with minute set to 0, original unchanged','replace',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1305,86,'strftime() method (date)','Formats a date into a string using directives like %Y','strftime',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1306,86,'Format codes %Y, %m, %d','The format codes %m and %d always produce two-digit, zero-padded representations. Therefore, January (1) becomes ''01'' and day 5 becomes ''05''.','strftime',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1307,86,'strftime() for datetime with time codes','The format ''%I:%M %p'' produces hours in 12-hour format (01-12), minutes, and the locale’s AM/PM string. For 15:23, that yields ''03:23 PM''.','strftime',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1308,86,'strptime() function (datetime)','Parses a string into a datetime using the specified format','strptime',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1309,86,'fromtimestamp() class method','datetime.fromtimestamp(ts) converts a Unix timestamp to the local date and time (naive). With a UTC+2 offset, the local time is two hours ahead of UTC.','fromtimestamp',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1310,86,'total_seconds() method (timedelta)','Returns total duration in seconds, including days','total_seconds',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1311,86,'Negative timedelta','A timedelta stores days and seconds separately. The .days attribute directly reflects the days argument, here -2, even though the total duration is affected by the seconds component.','timedelta',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1312,86,'Naive datetime','A datetime with tzinfo=None, no timezone awareness','tzinfo',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1313,86,'Aware datetime','A datetime with tzinfo set to a timezone object','tzinfo',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1314,86,'UTC offset','Difference in hours and minutes from UTC, e.g., -5','timezone',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1315,86,'timezone class (datetime)','Represents a fixed offset from UTC, not DST-aware','timezone',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1316,86,'tz.gettz() function','`tz.gettz()` looks up the IANA time zone database and returns an object that knows the offset rules (including DST transitions).','tz.gettz',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1317,86,'EST vs EDT (Eastern Time)','Eastern Time switches between EST (Standard) and EDT (Daylight) based on the time of year.','-5',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1318,86,'pd.read_csv() with parse_dates','Reads CSV and parses specified columns as datetime','parse_dates',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1319,86,'dt accessor','Using `.dt` on non‑datetime columns raises an AttributeError because pandas does not know how to interpret string data as datetime properties.','.dt.',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1320,86,'dt.total_seconds() on timedelta series','For a Series of timedelta64, you must use the `.dt` accessor to call `.total_seconds()`. The method returns the total duration in seconds as a float.','dt.total_seconds()',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1321,86,'astimezone() method','Converts aware datetime to another timezone, adjusting clock time','astimezone',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1322,86,'replace(tzinfo=...) method for timezone','Changes tzinfo without adjusting the clock time, often wrong','replace',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1323,86,'Ambiguous time (fall back)','When a local clock time occurs twice during fall‑back transition','datetime_ambiguous',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1324,86,'enfold() function (dateutil.tz)','`tz.enfold()` marks an ambiguous datetime as the second (post-fall-back) occurrence. When converted to UTC, this second 1 AM corresponds to a time one hour later than the first 1 AM.','enfold',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1325,86,'Converting to UTC for accurate arithmetic','During a DST transition, the same local time may map to two different UTC times, or an hour may be skipped. Subtracting aware datetimes directly can produce a duration that is one hour too short or long. Converting to UTC first ensures the arithmetic uses a constant scale.','UTC',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1326,86,'dt.tz_localize() method','Assigns timezone to naive Series, setting ambiguous times to NaT','tz_localize',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1327,86,'dt.tz_convert() method','`tz_convert` changes the timezone of an already‑aware Series, adjusting the clock time.','tz_convert',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1328,86,'shift() method (Pandas)','`shift(1)` moves all values one row down, introducing `NaT` at the first position. The index remains unchanged.','.shift',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1329,86,'UTC (Coordinated Universal Time)','Primary time standard; all timezones are offsets from UTC',NULL,3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1330,86,'Daylight Saving Time (DST)','Practice of springing forward and falling back to extend daylight',NULL,3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1331,86,'month attribute (date)','`d.month` accesses the month as an integer (1‑12).',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1332,86,'day attribute (date)','`d.day` is the day of the month (1‑31).',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1333,86,'timedelta class','Represents a duration between two dates or times',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1334,86,'timedelta.days attribute','The `.days` attribute only returns the day component (whole days). It does not include fractional days. `36 hours = 1 day + 43200 seconds`, so `.days` is 1.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1335,86,'+= operator (plus-equals)','`x += 1` is equivalent to `x = x + 1`.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1336,86,'Creating timedelta with multiple units','Multiple units are summed internally: days remain in `.days`, while hours, minutes, etc. are converted to `.seconds`.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1337,86,'Pandas library','Data analysis library with DataFrame and datetime support',NULL,4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1338,86,'pd.to_datetime() function','`pd.to_datetime()` with `format` provides explicit parsing. Without it, pandas infers the format, which can be slower and may fail on ambiguous strings.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1339,86,'Timestamp object (Pandas)','Pandas'' datetime type with nanosecond precision',NULL,4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1340,86,'mean() on timedelta series','`.mean()` on a timedelta Series computes the arithmetic mean as a `Timedelta`, not a float.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1341,86,'sum() on timedelta series','`.sum()` aggregates all durations into a single `Timedelta`.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1342,86,'value_counts() method','`value_counts()` tallies the frequency of each unique entry.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1343,86,'plot() method (Pandas)','`.plot()` generates a Matplotlib plot using pandas defaults, perfect for quick time‑series exploration.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1344,86,'ambiguous=''NaT'' in tz_localize','Without this parameter, an `AmbiguousTimeError` would be raised. `''NaT''` replaces those timestamps with Not‑a‑Time, allowing the operation to complete.',NULL,4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1345,86,'dt.year, dt.month, dt.day_name()','The `.dt` accessor exposes datetime properties like `year`, `month`, and methods like `day_name()`.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1346,86,'date class','Represents a calendar date (year, month, day) without time',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1347,86,'tzinfo parameter in datetime','When you set `tzinfo` without ensuring the offset matches the actual local rules, you may assign a wrong UTC time. December is EST, so -5 is correct in this case, but for summer it would be wrong. The issue is blindly using a fixed offset.',NULL,3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1348,86,'dateutil.tz module','Third-party module with IANA timezone database for DST handling',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1349,86,'groupby() method','Splits data by group and computes mean per group',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1350,86,'Comparing dates','Date objects support direct comparison. d1 (November 5) is earlier than d2 (December 4), so min() returns d1, printed as 2017-11-05.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1351,86,'timedelta() constructor','Creates a timedelta of 29 days using keyword argument',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1352,86,'datetime class','Combines a date and a time into one object',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1353,86,'timezone() constructor','The `timezone` constructor accepts one argument: a `timedelta`. For UTC+5:30, use `timedelta(hours=5, minutes=30)`.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1354,86,'datetime_ambiguous() function (dateutil.tz)','The `datetime_ambiguous()` function requires an aware datetime (with tzinfo). If given a naive datetime, it raises a ValueError because ambiguity cannot be determined.',NULL,3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1355,86,'resample() method','Resamples time‑series data by month‑end frequency',NULL,4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1356,87,'Referencing vs calling a function','Assigns the function object; x() will call it later.','my_function',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1357,87,'with statement','Syntax to automatically close the file after the block.','with',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1358,87,'Docstring','First string literal in a function, stored in __doc__.','Return the answer to life, the universe, and everything.',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1359,87,'Google-style docstring','Google-style docstring showing optional argument.','str, optional',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1360,87,'Numpydoc docstring','Numpydoc-style parameter section with dash underline.','----------',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1361,87,'__doc__ attribute','Raw docstring exactly as written, including indentation.','__doc__',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1362,87,'inspect.getdoc()','Docstring with leading whitespace stripped for display.','getdoc',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1363,87,'DRY (Don''t Repeat Yourself)','Principle: abstract repeated logic into reusable functions.','load_and_plot',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1364,87,'Do One Thing principle','A function that loads and plots data violates ''Do One Thing'' even if it''s not repeated. Both principles lead to cleaner, more maintainable code.','plot_data',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1365,87,'Context manager','Setup and teardown pattern, e.g., opening and closing a file.','open',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1366,87,'Functions as first-class objects','Can be assigned to variables, passed as arguments, and returned.','my_function',7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1367,87,'Built‑in scope','Built-in names are always available unless shadowed by a local or global assignment.','max',8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1368,87,'Pass by assignment','In Python, arguments are passed by assignment. For a mutable list, modifying elements affects the original. For an immutable int, reassigning the parameter does not change the original variable.','x',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1369,87,'Nested contexts','Nested context managers, closing inner then outer.','with open(dst, ''w'') as f_dst:',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1370,87,'try/finally for context managers','Guarantees teardown even if an error occurs in the with block.','try:',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1371,87,'Exception handling in context managers','This pattern guarantees that even if the with block raises an error, the printer is disconnected. The try/finally structure is the standard way to enforce teardown.','raise',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1372,87,'Functions as arguments','Passing a function as an argument to check if it has a docstring.','no',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1373,87,'Nested function','A nested function is a function defined inside another function. It can access variables from the enclosing scope (nonlocal variables).','in_range',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1374,87,'Functions as return values','get_function returns the inner function print_me. Assigning it to new_func and calling it with ''Hello'' prints the string.','print_me',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1375,87,'Local scope','x only exists during the execution of foo. After the function returns, the name is removed from the local namespace, so the global scope cannot see it.','x',8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1376,87,'Global scope','Understanding scope prevents accidental shadowing and helps with variable lifetime management.','x',8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1377,87,'Nonlocal scope (enclosing scope)','Nonlocal variables can be accessed by inner functions, but to modify them, the nonlocal keyword is required.','x',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1378,87,'global keyword','Allows a function to modify a variable in the module‑level scope.','global x',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1379,87,'Decorator','A function that takes a function and returns a modified version.','double_args',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1380,87,'Decorator syntax (@)','Decorator syntax: equivalent to func = timer(func).','@timer',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1381,87,'Wrapper function in decorators','Inner function that replaces the original, often modifying arguments.','return wrapper',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1382,87,'*args and **kwargs in decorators','Generic signature to pass any arguments to the wrapped function.','*args, **kwargs',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1383,87,'functools.wraps','Preserves __name__ and __doc__ of the original function in the wrapper.','@wraps(func)',12,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1384,87,'__wrapped__ attribute','When `functools.wraps` is used, the wrapper gains a `__wrapped__` attribute that holds a reference to the original function, allowing introspection or direct access.','__wrapped__',12,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1385,87,'timer decorator','The timer decorator records the start time, calls the original function, computes elapsed time, and prints it formatted to two decimal places.','time.time() - t_start',11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1386,87,'memoize decorator','The memoize decorator works for hashable arguments, but if a list is passed, converting it to a tuple will fail because lists aren''t hashable. Additionally, the cache dictionary grows indefinitely without eviction.','key = (args, tuple(sorted(kwargs.items())))',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1387,87,'signal module','The signal module allows you to register handlers for signals like SIGALRM, enabling functions to be interrupted after a set duration.','signal.SIGALRM',14,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1388,87,'Mutable default arguments danger','Default arguments are evaluated once at function definition. Because the same list object is reused, successive calls append to the same list, causing accumulation. The safe pattern uses None as default.','None',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1389,87,'@contextlib.contextmanager decorator','Decorator transforming a generator function into a context manager.','@contextlib.contextmanager',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1390,87,'yield keyword','Inside a generator-based context manager, provides the value to `as`.','yield 42',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1391,87,'nonlocal keyword','Lets a nested function assign to a variable in the enclosing scope.','nonlocal x',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1392,87,'Closure','Closure: bar captures a and remembers it after foo returns.','a',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1393,87,'__closure__ attribute','The __closure__ attribute is a tuple of cell objects, each with a cell_contents attribute storing the captured variable''s value. It is None if no nonlocal variables are captured.','__closure__',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1394,87,'Decorator factory','Decorator factory: outer function returns a decorator that takes func.','def decorator(func):',13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1395,87,'timeout decorator (using signals)','The decorator sets an alarm, runs the function, and cancels the alarm in finally. If the function takes too long, SIGALRM is raised, triggering a TimeoutError (assuming a handler is set).','signal.alarm(0)',14,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1396,87,'Code smell','Code smells are subjective but often point to violations of principles like DRY or ''Do One Thing''.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1397,95,'Storage (cloud service)','Cloud object storage service.','client',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1398,95,'Pay-as-you-go pricing','This model eliminates upfront capital expenses and allows organisations to scale costs with actual usage.','hours',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1399,95,'Horizontal scaling','Adding more machines to share the workload.','add_instances',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1400,95,'Cloud security','Customers are responsible for security *in* the cloud, while providers secure the cloud infrastructure itself.','Allow',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1401,95,'Database (cloud service)','Managed relational database service.','dynamodb',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1402,95,'Platform as a Service (PaaS)','Cloud platform for developing and deploying applications.','web',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1403,95,'Virtualization','Splits one physical server into multiple virtual machines.','hypervisor',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1404,95,'Reliability (cloud)','Replication ensures data remains safe and accessible even during regional outages. SLAs define the provider''s commitments.','uptime_sla',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1405,95,'DevOps engineer','Combines software development and IT operations for automation.','my-app',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1406,95,'Major cloud providers','AWS, Microsoft Azure, and Google Cloud Platform.','create_bucket',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1407,95,'Cloud computing','Delivery of IT services over internet with pay-as-you-go pricing.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1408,95,'On-premises computing','Hosting and managing servers locally within an organization.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1409,95,'Scalability','Ability to handle growing workloads by adding resources.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1410,95,'Vertical scaling','Upgrading a single machine with more RAM or CPU.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1411,95,'High Availability (HA)','HA is achieved through redundancy and failover mechanisms. It aims for minimal, not zero, downtime.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1412,95,'Cloud service models','IaaS gives maximum control; PaaS manages the runtime; SaaS delivers ready‑to‑use applications.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1413,95,'Infrastructure as a Service (IaaS)','Virtualized computing resources; you manage the OS and apps.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1414,95,'Software as a Service (SaaS)','Cloud apps like Gmail, fully managed by provider.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1415,95,'Compute (cloud service)','Cloud compute service for virtual servers.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1416,95,'Redundancy','Duplication of critical systems to improve availability.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1417,95,'Serverless computing','Serverless abstracts away infrastructure management. FaaS (like AWS Lambda) is a common implementation.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1418,95,'Public cloud','Shared cloud infrastructure accessible over the internet.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1419,95,'Private cloud','Cloud dedicated to a single organization, offering more control.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1420,95,'Community cloud','Cloud shared by organizations with common compliance requirements.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1421,95,'Personal data (PII)','Any information relating to an identifiable individual.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1422,95,'Data protection regulations (other)','Many regions have enacted privacy regulations with unique requirements, so GDPR compliance alone may not be sufficient.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1423,95,'Cloud architect','Designs cloud solutions based on business requirements.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1424,95,'Cloud engineer','Builds, maintains, and monitors cloud infrastructure.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1425,95,'Security engineer (cloud)','They ensure compliance and protection across the cloud environment, working within the shared responsibility model.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1426,95,'Amazon Web Services (AWS)','AWS''s broad service portfolio and early entry established it as a dominant force. NerdWallet uses SageMaker for ML.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1427,95,'Microsoft Azure','Azure''s hybrid capabilities and support for both Windows and Linux make it versatile. Ottawa Hospital uses Azure for disaster recovery.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1428,95,'Google Cloud','Google Cloud emphasizes AI/ML services and hybrid‑cloud flexibility. Lush uses it for e‑commerce scalability.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1429,95,'Disaster recovery (cloud)','Processes to restore systems after outages or disasters.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1430,95,'Cloud Governance','Governance is needed regardless of company size; it covers cost controls, security baselines, and regulatory compliance.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1431,95,'SecOps','SecOps aims to embed security into the operational workflow, contrasting with DevOps which merges development and operations.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1432,95,'Elasticity','Auto-scaling resources up/down based on demand.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1433,95,'Function as a Service (FaaS)','Serverless model to run code functions without managing servers.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1434,95,'General Data Protection Regulation (GDPR)','EU law regulating personal data collection and processing.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1435,95,'Hybrid cloud','Mix of public and private cloud linked together.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1436,95,'Multicloud','Using multiple cloud providers for different services.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1437,95,'Cloud bursting','Cloud bursting requires orchestration and networking setup; it''s not automatic. It works best for stateless workloads.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1438,95,'Server','A computer that provides resources or services to other computers over a network.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1439,95,'XaaS (Anything as a Service)','XaaS is a catch-all term that reflects the expansion of cloud services beyond the traditional IaaS, PaaS, and SaaS models. It includes any IT capability delivered via the cloud.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1440,95,'Latency','Time delay between a request and the response.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1441,95,'Data center','Physical facility housing servers and cloud infrastructure.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1442,96,'String data type','Assigns a string to a variable using double quotes.','pasta',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1443,96,'Integer data type','Assigns an integer (whole number) to a variable.','2',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1444,96,'print function','Built-in function that displays output to the console.','print',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1445,96,'type function','Returns the data type of the argument (e.g., <class ''str''>).','type',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1446,96,'.replace() method','Returns a new string with replacements; original unchanged unless reassigned.','replace',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1447,96,'.lower() method','Returns a lowercase copy of the string; does not modify original.','lower',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1448,96,'.upper() method','Returns an uppercase copy of the string; must be reassigned to update variable.','upper',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1449,96,'.values() method (dict)','Returns a view of all values in the dictionary.','values',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1450,96,'.keys() method (dict)','Returns a view of all keys in the dictionary.','keys',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1451,96,'.items() method (dict)','Returns a view of key-value pairs as tuples.','items',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1452,96,'Convert to set','Converts a list to a set, eliminating duplicates.','set',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1453,96,'sorted() function','Returns a new sorted list from the elements of the set.','sorted',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1454,96,'Code comment','Text after # that Python ignores; used for explanations.','#',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1455,96,'Variable','A named container that stores a value for reuse.','ingredient_name',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1456,96,'Printing variables','Displays the value stored in the variable ingredient_name.','ingredient_name',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1457,96,'Updating variables','Reassigns the variable to a new value, overwriting the old one.','3',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1458,96,'Boolean data type','Assigns the Boolean value True to a variable.','True',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1459,96,'Single and double quotes','Escapes the apostrophe inside single-quoted string.','"',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1460,96,'Multi-line strings','Creates a multi-line string that preserves line breaks.','"""',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1461,96,'List','Creates a list, a mutable ordered collection.','[',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1462,96,'List indexing','Accesses the first element of the list (zero-based indexing).','0',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1463,96,'Negative indexing','Accesses the last element of the list.','-1',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1464,96,'List slicing','Returns a sublist from index 1 up to but not including index 3.','1:3',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1465,96,'Dictionary','Creates a dictionary with key ''pasta'' and value 500.','{',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1466,96,'Access dictionary by key','Returns the value associated with the key ''pasta''.','"pasta"',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1467,96,'Add key-value pair to dict','Adds a new key ''parmesan'' with value 50 to the dictionary.','"parmesan"',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1468,96,'Update dictionary value','Updates the value for key ''pasta'' to 1000.','"pasta"',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1469,96,'Duplicate keys in dictionary','Prints 15 because the last duplicate key overwrites earlier ones.','"garlic"',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1470,96,'Set','Creates a set, which automatically removes duplicate elements.','{',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1471,96,'Tuple','A tuple is created by enclosing values in parentheses ( ) and separating them with commas.','(',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1472,96,'Tuple indexing','Tuples are indexed exactly like lists, starting from 0. serving_sizes[1] accesses the second element, which is 2.','1',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1473,96,'Else statement','The else clause runs when no preceding if or elif condition was True.','else',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1474,96,'Variable assignment','Uses the assignment operator = to store 10 in count.','=',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1475,96,'Arithmetic operators','Adds an integer and a float, printing 3.5.','+',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1476,96,'String operators','Raises TypeError because you can''t concatenate string and int.','+',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1477,96,'Step slicing','Returns every second element from the whole list.','::2',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1478,96,'Comparison operators','The assignment operator = cannot be used in a conditional expression; Python expects an expression that evaluates to a Boolean. The correct equality operator is ==. Option a would raise a SyntaxError.','==',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1479,96,'String comparison','Strings are compared using Unicode order. The first differing character decides the result: ''J'' has a higher code point than ''B'', so "James" > "Brian" returns True.','>',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1480,96,'Conditional statement (if)','The if statement requires the condition followed by a colon, and the indented body runs when True.','if',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1481,96,'For loop','The syntax ''for variable in iterable:'' is the standard Python for loop.','for',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1482,96,'Python','A popular, general-purpose programming language known for its clear syntax.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1483,96,'Python script','A file with .py extension containing Python code.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1484,96,'Development practices','Start small, iterate, test, and document your code.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1485,96,'Variable naming convention','snake_case: lowercase with underscores, standard Python style.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1486,96,'Float data type','Assigns a decimal number (float) to a variable.',NULL,3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1487,96,'Method','A function that belongs to a specific data type, called with dot notation.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1488,96,'Set limitations','Raises TypeError because sets are unordered and not subscriptable.',NULL,7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1489,97,'print function','`print()` is the built-in function that outputs strings and other objects to the standard output (usually the console).','print',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1490,97,'Code comment','In Python, the hash symbol `#` starts a comment. Everything after `#` on that line is ignored by the interpreter. Other languages use different symbols, but Python''s design is intentionally simple.','#',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1491,97,'Variable assignment','Using `=` to bind a value to a name, e.g., `servings = 4`','=',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1492,97,'Printing variables','`print(variable_name)` displays the value stored in the variable','print',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1493,97,'type function','`type(3.14)` returns a type object representing `float`. When printed, it shows `<class ''float''>`.','type',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1494,97,'Arithmetic operators','Python follows standard arithmetic precedence: `*` and `/` have higher precedence than `+` and `-`. So `2 * 3` is evaluated first, giving 6, then `5 + 6` gives 11.','+',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1495,97,'String operators','`"Hi" * 3` repeats `"Hi"` three times, concatenating them: `"Hi" + "Hi" + "Hi"` = `"HiHiHi"`.','+',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1496,97,'Single and double quotes','Both single and double quotes create strings. Double quotes allow you to embed apostrophes without backslashes. Conversely, single quotes allow embedding double quotes. Choose whichever makes the string cleaner.','"',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1497,97,'Method','Methods are associated with objects (e.g., `''hello''.upper()`). Functions like `print()` are not tied to a specific type. Methods often operate on the object they belong to.','.upper',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1498,97,'.replace() method','Strings are immutable. `.replace()` returns a **new** string with the replacement; it does not modify the original. The returned value is not stored, so `message` remains unchanged.','replace',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1499,97,'List','Ordered, mutable collection created with square brackets, e.g., `["pasta", "tomatoes"]`','[',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1500,97,'List indexing','List indices start at 0. `ingredients` has 3 elements, indices 0,1,2. Index 3 is out of range, causing an `IndexError`.','2',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1501,97,'Negative indexing','`-1` accesses the last element of the list. Here, the last element is `"d"`.','-1',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1502,97,'List slicing','`letters[1:4]` takes indices 1 (b), 2 (c), and 3 (d). Index 4 (e) is excluded. Result is `[''b'',''c'',''d'']`.','1',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1503,97,'Step slicing','The step in a slice must be a non‑zero integer. A step of 0 would mean infinite repetition, which is not allowed, so Python raises a `ValueError`.',NULL,5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1504,97,'Dictionary','Key-value pairs enclosed in `{}` with colons, e.g., `{"pasta": 500}`',NULL,6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1505,97,'Access dictionary by key','Accessing a dictionary with a missing key raises a `KeyError`. The key `''tomatoes''` is not present.','"pasta"',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1506,97,'.values() method (dict)','Views are dynamic: if the dictionary changes, the view updates. Lists are static copies. To get an indexable list, use `list(dict.values())`.','values',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1507,97,'.keys() method (dict)','The view is dynamic and memory‑efficient; the list is a snapshot. For most iteration, the view is sufficient and preferred.','keys',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1508,97,'.items() method (dict)','The loop iterates over `recipe.items()`, which yields `(''a'', 1)` then `(''b'', 2)`. Unpacking prints the key and value separated by a space.','items',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1509,97,'Add key-value pair to dict','Dictionary assignment `dict[key] = value` adds the key if it does not exist, or updates the value if it does. Here `''garlic''` is new, so it is added.','"garlic"',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1510,97,'Update dictionary value','The key `"pasta"` already exists, so the assignment overwrites its value with 1000. The dictionary is modified in place.','"pasta"',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1511,97,'Set','Unordered, unique elements enclosed in `{}` without colons, e.g., `{"pasta", "garlic"}`','{',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1512,97,'Convert to set','`set(ingredients_list)` returns a set containing the unique elements from the list. Duplicates are removed.','set',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1513,97,'sorted() function','The `sorted()` built-in function takes any iterable (like a set) and returns a new list containing all items in sorted order. For strings, it sorts lexicographically. The output is a list: `[''basil'', ''garlic'', ''pasta'']`.','sorted',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1514,97,'Tuple','Immutable, ordered sequence created with parentheses, e.g., `(1, 2, 4)`','(',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1515,97,'Tuple indexing','Tuples are indexed starting at 0. The element `2` is the second element, so its index is 1. `serving_sizes[1]` returns 2.','1',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1516,97,'range() function','Generates a sequence of numbers; `range(start, stop)` includes `start` but excludes `stop`','1',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1517,97,'Conditionals inside for loops','Nested `if-elif-else` inside a `for` loop to process each element differently based on its value','elif',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1518,97,'While loop','Repeatedly executes a block as long as a condition is true; condition checked before each iteration','<',10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1519,97,'Building a workflow','Both approaches produce a list of missing ingredients. The loop is explicit and allows adding extra logic (e.g., checking amounts). Set operations are concise and efficient but treat all keys equally.','items',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1520,97,'*args (arbitrary positional arguments)','Collects extra positional arguments into a tuple; defined as `*args` in the function signature','*args',19,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1521,97,'**kwargs (arbitrary keyword arguments)','Collects extra keyword arguments into a dictionary; defined as `**kwargs`','**kwargs',19,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1522,97,'lambda function','Anonymous, single‑expression function defined with `lambda`, e.g., `lambda x: x**2`','lambda',20,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1523,97,'try-except block','Allows handling of exceptions gracefully, preventing program termination: `try:` block then `except:`','except',22,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1524,97,'Python','Python is an interpreted, object-oriented, high-level programming language with dynamic semantics. Its simple syntax makes it an excellent choice for beginners and experts alike.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1525,97,'Python script','Any text file with Python code that the interpreter can run is a script. The `.py` extension is conventional but not strictly required.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1526,97,'Development practices','Agile development practices emphasize iterative development. Small increments with frequent testing allow early detection of issues and easier debugging, whereas big‑bang integration often results in hidden bugs and longer debugging sessions.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1527,97,'Variable','A named storage location that holds a value (e.g., `ingredient_name = "tomatoes"`)',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1528,97,'String data type','Text enclosed in quotes, e.g., `"pasta"`',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1529,97,'Integer data type','Whole numbers without a decimal point, e.g., `500`',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1530,97,'Updating variables','`count = count + 2` reads the old value (5), adds 2 to get 7, then assigns that new value to `count`. So `print(count)` outputs 7.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1531,97,'Variable naming convention','Use `snake_case` (all lowercase with underscores) for variable names per PEP 8',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1532,97,'Duplicate keys in dictionary','Dictionaries cannot have duplicate keys. When you provide the same key twice in a literal, the later value overwrites the earlier one silently. So `recipe["garlic"]` is 15.',NULL,6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1533,97,'Set limitations','Sets are unordered collections with no index positions. You cannot use `[]` to get an element by position. To access elements, iterate over the set or convert to a list.',NULL,7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1534,97,'raise statement','`raise ValueError("message")` creates and raises a `ValueError` with the given message. This stops normal execution and transfers control to an enclosing `try/except` if any.',NULL,22,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1535,97,'Comparison operators','The expression `5 >= 5` evaluates to `True` because 5 is equal to 5, satisfying the ''greater than or equal'' condition. Comparison operators always produce boolean values.',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1536,97,'String comparison','Python compares strings lexicographically (dictionary order) using Unicode code points. Uppercase letters (A-Z) have code points 65-90, lowercase (a-z) have 97-122. Since `''a''` (97) > `''B''` (66), the whole string `"apple"` is considered greater than `"Banana"`, so the output is `True`.',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1537,97,'Conditional statement (if)','`if condition:` followed by an indented block that runs when condition is True',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1538,97,'Elif statement','Short for ''else if'', checks a condition only if previous `if`/`elif` conditions were false',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1539,97,'Else statement','Optional block after `if`/`elif` that runs when all preceding conditions are false',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1540,97,'Indentation','Python uses spaces or tabs to define code blocks; inconsistent indentation raises `IndentationError`',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1541,97,'For loop','Iterates over an iterable, executing the indented block for each item: `for item in list:`',NULL,9,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1542,97,'break keyword','Exits the innermost loop immediately, skipping the remaining iterations',NULL,10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1543,97,'in keyword','Checks membership in a sequence or mapping; for dictionaries, checks keys by default',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1544,97,'not keyword','The `not in` operator returns `True` if the value is **not** found in the sequence. Here, `"salt"` is not in the list `pantry`, so `"salt" not in pantry` evaluates to `True`.',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1545,97,'and keyword','Logical AND: returns `True` only if both operands are true; short‑circuits on first false',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1546,97,'or keyword','The `or` operator evaluates to `True` if at least one of its operands is `True`. Since `has_tomatoes` is `True`, the condition `has_pasta or has_tomatoes` is `True`, so the `if` block executes, printing `Make sauce`.',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1547,97,'+= operator','The `+=` operator adds the right operand to the left variable and assigns the result. For strings, `+=` performs concatenation. So `message += " World"` is equivalent to `message = message + " World"`, resulting in `"Hello World"`.',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1548,97,'-= operator','The `-=` operator subtracts the right operand from the left variable and assigns the result. `count -= 3` is equivalent to `count = count - 3`, which gives 10 - 3 = 7.',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1549,97,'.append() method (list)','The `.append()` method adds an element to the end of a list and returns `None`. It modifies the list in place. Here, `result` gets the return value `None`, so `print(result)` outputs `None`. The list `shopping_list` becomes `["pasta"]`, but that is not printed.',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1550,97,'round() function','Python''s `round()` function uses round-half-to-even (also called bankers rounding) for ties. Moreover, due to binary floating-point representation, the decimal 2.675 cannot be represented exactly; it is stored as a value slightly less than 2.675. As a result, `round(2.675, 2)` returns 2.67, not 2.68.',NULL,13,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1551,97,'pip','The recommended practice is to use `python -m pip install <package>` because it guarantees that you are using the pip version associated with the Python interpreter you are currently using. This avoids problems on systems with multiple Python installations where the `pip` command might point to a different environment.',NULL,15,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1552,97,'DataFrame (pandas)','The `pd.DataFrame` constructor converts a dictionary of lists into a DataFrame where each key becomes a column name and the corresponding list provides the column values. The output is a nicely formatted table with row indices (0,1) and the columns `name` and `age`.',NULL,15,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1553,97,'pd.read_csv() function','A `FileNotFoundError` occurs when the file specified does not exist at the given path. The most likely cause is that `sales.csv` is not present in the current working directory. You should check the file location or provide an absolute path.',NULL,15,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1554,97,'map() function','Applies a function to every item of an iterable and returns an iterator',NULL,20,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1555,97,'ValueError','Raised when a function gets the right type but an inappropriate value, e.g., `int("hello")`',NULL,21,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1556,97,'KeyError','Raised when accessing a dictionary (or pandas DataFrame) with a key that does not exist',NULL,21,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1557,97,'TypeError','Raised when an operation is applied to an object of inappropriate type, e.g., `"Hello" + 5`',NULL,21,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1558,97,'Float data type','A number with a decimal point, e.g., `1.5`',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1559,97,'Boolean data type','`True` or `False` values, often the result of comparison operators',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1560,97,'Looping through dictionaries','Use `for key in dict:` for keys, `for value in dict.values():` for values, or `for key, value in dict.items():` for both',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1561,97,'def keyword','Used to define a custom function: `def function_name():` followed by an indented block',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1562,97,'return statement','Exits a function and optionally passes a value back to the caller; without `return`, the function returns `None`',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1563,97,'Custom function','A reusable block defined with `def` that performs a specific task, e.g., `def average(values):`',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1564,104,'pwd','Prints the current working directory path.','pwd',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1565,104,'ls','Lists files and directories in the current location.','ls',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1566,104,'cd','Changes the current directory to ''archive''.','cd',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1567,104,'git --version','Displays the installed version of Git.','--version',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1568,104,'git init','Creates a new directory and turns it into a Git repository.','mental-health-workspace',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1569,104,'git status','Shows which files are tracked, modified, or staged.','status',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1570,104,'git add','Stages all new and modified files in the current directory.','README.md',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1571,104,'git commit','Creates a new snapshot with the message ''Fix typos''.','Adding a README.',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1572,104,'Commit hash','A unique 40-character string that identifies a commit (deterministic).','ad8acfe',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1573,104,'git log','Shows commit history in reverse chronological order.','log',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1574,104,'git log -n','Shows only the three most recent commits.','-3',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1575,104,'git log --since','Displays commits made on or after April 2, 2024.','Apr 2 2024',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1576,104,'git log --until','Limits log output to commits before April 11, 2024.','Apr 11 2024',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1577,104,'git diff','Shows unstaged changes between the working directory and the last commit.','diff',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1578,104,'git diff --staged','Compares what is staged to the last commit.','--staged',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1579,104,'HEAD~ syntax','Refers to the commit two steps before the current one (grandparent).','HEAD',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1580,104,'git show','Displays metadata and diff for the commit with hash c27fa856.','show',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1581,104,'git revert','Creates a new commit that reverses the latest commit''s changes, preserving history.','revert',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1582,104,'git revert --no-edit','Reverts the latest commit using the default message, skipping the editor.','HEAD',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1583,104,'git revert -n','Applies the inverse changes but does not commit, leaving them staged.','HEAD',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1584,104,'git checkout (restore file)','Restores the file data.csv to its state from the previous commit.','report.md',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1585,104,'git restore --staged','Removes data.csv from the staging area, keeping working changes.','restore',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1586,104,'Version control','System for tracking changes to files over time, enabling comparison and reversion.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1587,104,'Git','Distributed open-source version control system that records snapshots of a project.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1588,104,'Shell','Program for typing and executing commands like git status.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1589,104,'Repository (repo)','A directory containing project files and a hidden .git metadata folder.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1590,104,'git directory','Hidden folder that stores all of Git''s metadata and history.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1591,104,'Nested repositories','When a .git directory exists inside another .git directory, causing confusion.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1592,104,'Staging area (index)','Intermediate area where changes are placed before being committed.',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1593,104,'Commit','A recorded snapshot of the repository including author, date, and message.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1594,104,'Tree','Records the names and locations of files and directories in a commit.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1595,104,'Blob','Short for binary large object; stores a file''s content, not its name.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1596,104,'Hash function','Determinism ensures that identical objects have identical hashes, so Git can deduplicate storage and verify data integrity.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1597,104,'HEAD','A symbolic pointer to the current commit (usually the tip of the current branch).',NULL,6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1598,122,'Query','A request for data or an operation written in SQL.','SELECT',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1599,122,'Keyword','Reserved words like SELECT, FROM, WHERE.','WHERE',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1600,122,'SELECT statement','The SELECT keyword retrieves specified columns from a table.',',',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1601,122,'FROM statement','The FROM keyword indicates the source table for a query.','FROM',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1602,122,'Asterisk (*) wildcard','The asterisk symbol, used in SELECT to mean all columns.','*',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1603,122,'Aliasing (AS)','The AS keyword renames a column in the result set.','AS',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1604,122,'DISTINCT','The DISTINCT keyword returns only unique values, eliminating duplicates.','DISTINCT',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1605,122,'CREATE VIEW','The SQL command to create a view, using AS before the SELECT.','AS',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1606,122,'VARCHAR','Variable-length character type with max length.','VARCHAR',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1607,122,'INT','Abbreviation for the integer data type.','INT',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1608,122,'NUMERIC','A data type that stores exact decimal numbers, with precision and scale.','2',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1609,122,'LIMIT (PostgreSQL)','The keyword in PostgreSQL to restrict the number of rows returned.','LIMIT',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1610,122,'TOP (SQL Server)','TOP is SQL Server''s way to limit rows. The number is typically in parentheses.','TOP',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1611,122,'WHERE clause','In SQL, `= NULL` does not work because NULL is not equal to anything. Use `IS NULL` to check for null values.','WHERE',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1612,122,'COUNT function','`COUNT(column)` counts only rows where the column is not NULL. To count all rows, use `COUNT(*)`.','DISTINCT',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1613,122,'CREATE TABLE statement','The column `name VARCHAR` lacks a length parameter. It should be `name VARCHAR(250)` to specify the maximum number of characters.','VARCHAR',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1614,122,'IS NOT NULL','A view always runs its defining query on the current table data. Because the WHERE clause filters out NULL year_hired, the updated row is excluded.','IS NOT',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1615,122,'Semicolon','The semicolon indicates the end of a SQL statement. While some tools may tolerate its absence, it''s required by many database systems to separate statements.',';',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1616,122,'Table naming conventions','Following naming conventions makes databases easier to understand and maintain. Plural lowercase names with underscores are a widely used style.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1617,122,'Field naming conventions','Using singular, lowercase field names with underscores avoids confusion and improves readability. A field like ''names'' would be plural and incorrect.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1618,122,'Server','A centralized computer that stores database files and provides data access.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1619,122,'Relational database','A database that defines relationships between tables.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1620,122,'Table','An object holding data in rows and columns.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1621,122,'Record (row)','A single row of data, representing one observation.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1622,122,'Field (column)','A column in a table, representing an attribute.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1623,122,'Unique Identifier / Key','A column that uniquely identifies each record.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1624,122,'Relationship (table relationship)','A connection between tables via shared columns.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1625,122,'SQL (Structured Query Language)','The standard language for managing relational databases.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1626,122,'Result set','The output of a SELECT query, a collection of rows and columns.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1627,122,'View','A virtual table defined by a saved SELECT query that updates dynamically.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1628,122,'Data type','The kind of data a column stores (e.g., integer, text).',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1629,122,'String','Data type for text sequences.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1630,122,'Integer','Whole number data type.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1631,122,'Float','Numbers with a fractional part, stored approximately.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1632,122,'Schema','A blueprint of the database design, showing tables and relationships.',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1633,122,'SQL flavor','A specific version of SQL, like PostgreSQL or T-SQL, with extensions.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1634,122,'PostgreSQL','A free, open-source relational database system, using LIMIT.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1635,122,'SQL Server (T-SQL)','A Microsoft database system using TOP instead of LIMIT.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1636,123,'COUNT(*)','Returns the total number of rows, including rows with NULLs','COUNT(*)',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1637,123,'LIMIT keyword','Restricts the result set to at most 10 rows','LIMIT',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1638,123,'COUNT() function','Counts only non‑null birthdates','COUNT',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1639,123,'DISTINCT keyword','Returns each language without duplicates','DISTINCT',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1640,123,'COUNT(DISTINCT)','Counts unique non‑null birthdates','COUNT',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1641,123,'WHERE clause','Filters rows to only those with release year after 2000','WHERE',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1642,123,'Comparison operators','The standard ''not equal to'' operator','<>',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1643,123,'Filtering strings with single quotes','String values must be in single quotes','''',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1644,123,'OR operator','Rows with release year equal to 1994 or 2000 are included','OR',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1645,123,'AND operator','Rows with release year strictly between 1994 and 2000','AND',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1646,123,'Parentheses in WHERE conditions','Movies from 1994 or 1995 that are rated PG','OR',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1647,123,'BETWEEN operator','Includes both 1994 and 2000','BETWEEN',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1648,123,'IN operator','Equivalent to release_year = 1920 OR release_year = 1930 OR release_year = 1940','IN',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1649,123,'LIKE operator','Matches names that begin with ''Ade'' (case‑sensitive)','LIKE',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1650,123,'NOT LIKE operator','Excludes names that start with ''A.''','NOT LIKE',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1651,123,'IS NULL operator','Returns rows where birthdate is missing','IS',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1652,123,'IS NOT NULL operator','Filters out rows with NULL birthdate','IS NOT',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1653,123,'Aggregate functions','Summarize multiple rows: COUNT, SUM, AVG, MIN, MAX','SUM',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1654,123,'AVG() function','Returns the arithmetic mean of non‑null budgets','AVG',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1655,123,'SUM() function','Adds all non‑null budget values','SUM',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1656,123,'MIN() function','The alphabetically first country name','MIN',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1657,123,'MAX() function','The most recent release year in the table','MAX',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1658,123,'ROUND() function','Rounds the average to the nearest hundred','2',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1659,123,'Arithmetic operators (+, -, *, /)','Uses arithmetic subtraction to calculate profit','-',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1660,123,'Integer division behavior','Returns 1 because of integer division','decimal',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1661,123,'Aliasing with AS','Alias ''max_budget'' can be used in ORDER BY but not WHERE','AS',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1662,123,'ORDER BY clause','Sorts result rows by budget in ascending order','ORDER BY',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1663,123,'ASC keyword','Explicitly sorts smallest budget first','ASC',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1664,123,'DESC keyword','Largest budget appears first; NULLs appear first as well','DESC',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1665,123,'Sorting by multiple columns','Sorts first by wins descending, then by imdb_score descending for ties','DESC',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1666,123,'GROUP BY clause','PostgreSQL requires that any column not inside an aggregate function be listed in the GROUP BY clause. The correct query is SELECT certification, COUNT(title) FROM films GROUP BY certification;','certification',10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1667,123,'GROUP BY multiple columns','When grouping by multiple columns, the combination determines the groups. Every unique pair of (certification, language) gets its own count.','language',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1668,123,'GROUP BY with ORDER BY','ORDER BY title_count DESC sorts the grouped results so certifications with the most films appear first.','DESC',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1669,123,'HAVING clause','HAVING is a post‑aggregation filter. The query groups rows by release_year, counts titles in each group, and then keeps only groups where that count exceeds 10. It returns the years that have more than 10 films.','HAVING',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1670,123,'HAVING vs WHERE','The WHERE clause is evaluated before aggregation, so it cannot contain aggregate functions. The correct approach is to move the condition to a HAVING clause: HAVING AVG(duration) > 120, which filters after grouping.','HAVING',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1671,123,'Query execution order','The logical execution order of SQL clauses','GROUP BY',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1672,123,'NULL value','Represents missing or unknown data; cannot be compared with =','IS',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1673,123,'SQL (Structured Query Language)','SQL is the standard language for interacting with relational database systems such as PostgreSQL.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1674,123,'PostgreSQL','PostgreSQL implements the SQL language and is the database system used in this course.',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1675,123,'Films Database','The course''s exercises use a realistic film database to illustrate filtering, aggregation, and grouping.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1676,123,'Holywell''s Style Guide','Holywell''s guide promotes consistent style choices that make SQL code easier to read, debug, and collaborate on.',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1677,123,'SQL error handling','Reading error messages: the actual mistake may be earlier than the caret indicates',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1678,123,'SQL style guide','Conventions for formatting SQL: line breaks, indentation, and capitalization',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1679,123,'Semicolon in SQL','Signals the end of a SQL statement; optional in PostgreSQL but best practice',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1680,124,'INNER JOIN','Returns only rows that match in both tables','INNER JOIN',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1681,124,'ON clause','Specifies join condition between tables','ON',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1682,124,'USING clause','Shorthand join when column names match','USING',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1683,124,'Table alias','Gives a temporary name to a table','AS',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1684,124,'LEFT JOIN','Returns all rows from left table, NULLs for missing right matches','LEFT JOIN',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1685,124,'RIGHT JOIN','Returns all rows from right table, NULLs for missing left matches','RIGHT JOIN',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1686,124,'FULL JOIN','Returns all rows from both tables, NULLs where no match','FULL JOIN',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1687,124,'CROSS JOIN','Produces Cartesian product of two tables','CROSS JOIN',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1688,124,'SELF JOIN','Joining a table to itself using aliases','INNER JOIN',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1689,124,'UNION','Combines result sets and removes duplicates','UNION',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1690,124,'UNION ALL','Combines result sets and keeps all duplicates','UNION ALL',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1691,124,'INTERSECT','Finds rows that appear in both result sets','INTERSECT',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1692,124,'EXCEPT','Returns rows from the first query that do not appear in the second','EXCEPT',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1693,124,'Semi join','Semi join: filters presidents of countries that gained independence before 1800','IN',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1694,124,'Anti join','Anti join: returns countries that have no matching row','NOT IN',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1695,124,'Subquery','A query nested inside another SQL statement','AVG(gdp_percapita)',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1696,124,'WHERE clause (with subqueries)','Semi join returning rows with a match in the subquery','WHERE',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1697,124,'Subquery in SELECT clause','Correlated scalar subquery in SELECT: counts monarchs per continent','COUNT(*)',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1698,124,'Subquery in FROM clause','Subquery in FROM clause requiring an alias','AS sub',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1699,124,'Multiple joins (chaining)','Sequentially joining multiple tables in one query','INNER JOIN',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1700,124,'Joining on multiple keys','Using AND to match on more than one column','AND',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1701,124,'DISTINCT','Removes duplicate rows from a query result','DISTINCT',6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1702,124,'NULL in joins','Finds rows with no match in an outer join','IS',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1703,124,'Set operation column requirements','Set operation column requirements','income_group',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1704,124,'Cartesian product','Result of CROSS JOIN: N * M rows','INNER JOIN',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1705,124,'Column alias','Renames a column in the output','AS',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1706,124,'Join (general)','SQL operation that combines columns from two or more tables','JOIN',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1707,124,'FROM clause','Specifies the source table(s) for a query','FROM',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1708,124,'Key (primary key)','Uniquely identifies each row in a table',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1709,124,'One-to-many relationship','One record in table A relates to many records in table B',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1710,124,'One-to-one relationship','Each record in table A corresponds to exactly one record in table B',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1711,124,'Many-to-many relationship','Requires a junction table to link records',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1712,124,'Correlated subquery','Subquery that references outer query, evaluated row by row',NULL,6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1713,124,'Data leader','Individual who champions data use and helps others learn',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1714,124,'LOWESS','Smoothing technique for scatterplots',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1715,124,'Table','Database object storing data in rows and columns',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1716,124,'Column','Named field in a table holding a specific data type',NULL,1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1717,125,'CREATE TABLE','This DDL statement defines a new table with specified column names and data types.','numeric',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1718,125,'information_schema','You can query `information_schema.tables` and `information_schema.columns` to explore the structure of the database.','information_schema.tables',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1719,125,'information_schema.columns','`information_schema.columns` provides column‑level metadata; filtering by `table_name` shows the structure of that table.','table_name = ''pg_config''',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1720,125,'INSERT INTO SELECT DISTINCT','`SELECT DISTINCT` ensures that only unique combinations are inserted, preventing duplicate rows in the target table.','DISTINCT',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1721,125,'varchar(n)','Variable‑length character type with a maximum of n characters','varchar(64)',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1722,125,'char(n)','Fixed‑length type: stores exactly 5 characters, padding with spaces if needed','char(5)',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1723,125,'numeric(p, s)','`numeric(p,s)` gives precise control. If a value has more than `p` digits, an error occurs.','numeric(3,2)',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1724,125,'serial','`serial` is a convenient way to generate surrogate keys, but it is not transactional – gaps are possible.','serial',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1725,125,'CAST','`CAST` performs an ad‑hoc type conversion without altering the table definition. It is essential when mixing types.','CAST(wind_speed AS integer)',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1726,125,'DISTINCT','`DISTINCT` operates on the entire row, not on individual columns. `SELECT DISTINCT a, b` keeps only unique (a,b) pairs.','DISTINCT organization',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1727,125,'INSERT INTO VALUES','`INSERT INTO … VALUES` adds rows one at a time (or multiple by listing several `(…)` sets). The column list is optional but recommended.','VALUES',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1728,125,'ALTER TABLE RENAME COLUMN','This DDL statement changes the column label. Dependencies like views or foreign keys might need updating.','old_name TO new_name',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1729,125,'ALTER TABLE DROP COLUMN','`DROP COLUMN` is destructive. PostgreSQL protects referential integrity by blocking the drop when dependencies exist.','column_name',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1730,125,'NOT NULL constraint','Ensures every row has a concrete value for the column; disallows NULL','SET NOT NULL',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1731,125,'UNIQUE constraint','Allows multiple NULLs because NULL is not equal to any other value','UNIQUE(column_name)',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1732,125,'Primary key','Defines the column as the unique, non‑null row identifier for the table','PRIMARY KEY',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1733,125,'Composite key','A primary or candidate key made of two or more columns','PRIMARY KEY (a, c)',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1734,125,'Surrogate key','Surrogate keys decouple the row identity from mutable business data, ensuring stability and simplicity.','serial PRIMARY KEY',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1735,125,'CONCAT','`CONCAT` is NULL‑safe in PostgreSQL. `CONCAT(''A'', NULL)` returns `''A''`.','CONCAT',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1736,125,'Foreign key','Column(s) that reference the primary key of another table, enforcing referential integrity','REFERENCES manufacturers (name)',10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1737,125,'N:M (many-to-many) relationship','Example: `affiliations` table with `professor_id` and `organization_id` foreign keys models the N:M relationship.','organization_id varchar(256) REFERENCES organizations(id)',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1738,125,'ON DELETE NO ACTION','`ON DELETE NO ACTION` is the default and, critically, can be deferred to the end of the transaction, allowing temporary violations that are resolved before commit. `RESTRICT` checks immediately and cannot be deferred.','ON DELETE NO ACTION',12,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1739,125,'ON DELETE CASCADE','With `ON DELETE CASCADE`, deleting a parent row silently removes all child rows. This is powerful but dangerous if the operator does not expect the chain of deletions.','ON DELETE CASCADE',12,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1740,125,'ON DELETE SET NULL / SET DEFAULT','A column with a NOT NULL constraint cannot be set to NULL. Thus, `ON DELETE SET NULL` cannot be used on such a column; the table definition will fail.','ON DELETE SET NULL',12,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1741,125,'ALTER TABLE ALTER COLUMN TYPE','When changing a column''s type, the `USING` clause provides a transformation to be applied to each existing value, ensuring a proper conversion (e.g., rounding a numeric to integer).','ROUND(average_grade)',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1742,125,'ALTER TABLE ADD CONSTRAINT','When adding a constraint, you can provide a name so that the constraint can be easily referenced later (e.g., to drop it). The name follows the keyword `CONSTRAINT`.','pk',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1743,125,'text (data type)','PostgreSQL type for character strings of any length, no maximum limit','text',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1744,125,'boolean','SQL boolean supports three‑valued logic. NULL is used when the truth value is missing.','boolean',5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1745,125,'integer','`integer` is the typical choice for whole numbers. Exceeding this range requires `bigint` or `numeric`.','integer',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1746,125,'date, time, timestamp','Using the right type avoids storing irrelevant components. `timestamp` without time zone is ambiguous across locations.','date',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1747,125,'Relational database','Structured collection of data organised into tables that model entities and relationships',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1748,125,'Table','A database object storing rows about a single entity type, with columns defining attributes',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1749,125,'Column (Attribute)','A named vertical field in a table that defines a data element and its type for every row',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1750,125,'Row (Record)','A single horizontal entry in a table representing one instance of the entity type',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1751,125,'Redundancy','Duplication of data, often from storing multiple entity types in one table, causing update anomalies',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1752,125,'Entity type','A category of real‑world objects (e.g., professors) that becomes a table in the database',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1753,125,'Entity-Relationship Diagram (ERD)','ERDs help visualize the schema before writing SQL. Entities are rectangles, attributes ellipses, relationships diamonds.',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1754,125,'Data type','Defines the kind of values a column can hold, constraining storage and allowed operations',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1755,125,'NULL','Because NULL is unknown, comparisons like `= NULL` do not work; you must use `IS NULL`.',NULL,6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1756,125,'Superkey','A set of columns that uniquely identifies rows, but may include unnecessary columns',NULL,7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1757,125,'Key (minimal superkey)','A set of columns uniquely identifying rows; removing any column destroys uniqueness',NULL,7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1758,125,'Candidate key','A key from which the primary key is selected; a table can have several',NULL,7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1759,125,'Cardinality','Cardinality determines the type of foreign key or junction table needed to model the relationship correctly.',NULL,10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1760,125,'1:N (one-to-many) relationship','In a professors‑universities relationship (1:N), the `professors` table gets a `university_id` foreign key.',NULL,10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1761,125,'Referential integrity','Referential integrity is the rule that every foreign key must match an existing primary key value in the referenced table, maintaining consistent relationships.',NULL,12,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1762,125,'Database Management System (DBMS)','A DBMS is the software system that manages databases. PostgreSQL, MySQL, and SQL Server are examples.',NULL,13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1763,125,'Database system','A database system is the combination of the DBMS (e.g., PostgreSQL) and all the databases it controls.',NULL,13,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1764,125,'Domain','The domain is the complete specification of what values a column may contain, encompassing both the data type and all column-level constraints.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1765,125,'Referential integrity violation','With `ON DELETE NO ACTION` (the default), the database enforces referential integrity by rejecting the deletion if any child rows exist. This prevents orphaned references.',NULL,12,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1766,125,'Time-invariant (primary key property)','Primary keys must be immutable. Surrogate keys like `serial` are designed to be stable; natural keys such as emails or phone numbers risk becoming outdated, causing costly updates and integrity issues.',NULL,8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1767,137,'list','Ordered, mutable collection that can hold any data types','''sugar''',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1768,137,'tuple','Ordered, immutable sequence type',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1769,137,'append method','Adds a single element to the end of a list, returns None','append',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1770,137,'extend method','Appends each element of the iterable individually to the list','extend',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1771,137,'tuple unpacking','zip pairs the lists. top_pairs[0] is (''Chocolate Chip'', ''Punjabi''). Unpacking assigns ''Chocolate Chip'' to us_num_1 and ''Punjabi'' to in_num_1.','0',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1772,137,'f-string','Formatted string literal that embeds variables directly','cookie_name',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1773,137,'startswith method (string)','Returns True if the string starts with ''A'' (case-sensitive)','startswith',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1774,137,'endswith method (string)','filename.endswith(''.csv'') returns True because the string ends with ''.csv''.','endswith',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1775,137,'in operator (string)','Because ''L'' is uppercase in the sentence, the substring ''life'' (lowercase) is not found. Use .lower() for case‑insensitive search.','in',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1776,137,'lower method (string)','Strings are immutable, so lower() returns a new lowercase version. The original string is not modified.','lower',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1777,137,'dict assignment','art_galleries[''zip''] = ''10021'' creates a key‑value pair. Both are strings.','''zip''',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1778,137,'list indexing','Python lists are zero‑indexed. len(cookies) returns 4, but valid indices are 0‑3. Accessing index 4 raises an IndexError.','2',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1779,137,'list concatenation with + operator','The + operator between two lists returns a new list that is the concatenation of both.','+',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1780,137,'index method (list)','Returns the position of the first matching element','index',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1781,137,'list comprehension','The comprehension filters for names starting with ''c'' and applies .title(), yielding ''Chocolate Chip''.','title',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1782,137,'sorted function','sorted() takes an iterable and returns a new sorted list. The reverse=True parameter sorts in descending order.','reverse',1,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1783,137,'zip function','zip pairs elements from multiple iterables. It stops at the end of the shortest input; here, the second list has only 2 elements.','list',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1784,137,'tuple unpacking in loops','Each tuple in pairs has three elements, but the for loop tries to unpack each into only two variables, raising a ValueError.','us_cookie',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1785,137,'enumerate function','enumerate returns an enumerate object, an iterator that yields (index, element) tuples. It is not a list or tuple itself.','enumerate',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1786,137,'dict (dictionary)','Mutable collection of key-value pairs','{}',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1787,137,'update method (dict)','update(other_dict) adds all key‑value pairs from other_dict into the dictionary, overwriting existing keys.','update',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1788,137,'del instruction','The del statement removes the specified key and its value from the dictionary.','del',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1789,137,'items method (dict)','The .items() method returns a view of (key, value) tuples, which you can unpack directly in the loop.','items',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1790,137,'in operator (dict)','The in operator checks the presence of keys in a dictionary. To check values, use `1 in d.values()`.','in',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1791,137,'keys method (dict)','art_galleries.keys() gives a view of all keys, e.g., dict_keys([''Miakey Art Gallery'']).','keys',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1792,137,'float division (/)','The / operator performs true division and always returns a float. To get integer division, use the // operator.','/',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1793,137,'comparison operators','cookie_qty == 3 returns True because the two values are equal.','==',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1794,137,'set creation','To create an empty set, use set(), not {}. {} always creates an empty dictionary.','set()',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1795,137,'Decimal','Floating‑point numbers are binary approximations. Decimal, constructed from strings, ensures precise base‑10 calculations.','''0.1''',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1796,137,'f-string float formatting','The :f specifier always shows a fixed‑point number, never scientific notation. Default precision is 6 digits after the decimal point.','.7f',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1797,137,'floor division (//)','7 // 3 = 2, but -7 // 3 = -3 because -3 * 3 = -9, which is less than -7 (floor).','//',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1798,137,'pop method (list)','Removes and returns the element at index 2','pop',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1799,137,'pop method (dict)','dict.pop(key, default) removes the key and returns its value if present; otherwise, it returns the default without raising an error.','None',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1800,137,'get method (dict)','dict.get(key, default) returns the value for the key if it exists; otherwise, it returns the supplied default (here, ''Not Found'').','get',4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1801,137,'join method (string)','join is a method of str, not list. The correct usage is `'',''.join(words)`. Calling words.join('','') raises AttributeError.',''', ''',3,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1802,137,'bool (boolean)','The only boolean values are True and False. Using lowercase true or false causes a NameError.',NULL,6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1803,137,'container sequence','Data type that holds a sequence of elements (e.g., list, tuple)',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1804,137,'int','Whole number type with arbitrary precision',NULL,5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1805,137,'float','Floating-point number type with binary approximation',NULL,5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1806,137,'set','Sets do not allow duplicates and are unordered, so you cannot index them. Use set() or curly braces with elements.',NULL,7,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1807,137,'Counter','Counter accepts an iterable and returns a dict‑like object with elements as keys and their frequencies as values.',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1808,137,'defaultdict','Dict subclass that provides a default value for missing keys',NULL,8,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1809,137,'namedtuple','namedtuple(''Point'', [''x'', ''y'']) creates an immutable Point class where instances can be accessed via .x and .y.',NULL,9,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1810,137,'dataclass','With @dataclass, you just list fields with type hints; Python generates the constructor and common special methods.',NULL,10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1811,137,'KeyError','Square bracket access on a missing key raises KeyError. Use d.get(''b'') to avoid the exception.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1812,137,'defaultdict with list','With defaultdict(list), you can do `d[key].append(value)` even if `key` has never been seen before.',NULL,8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1813,137,'intersection method (set)','Returns a new set with elements common to both sets',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1814,137,'namedtuple attribute access','Namedtuple instances can be accessed by name (attribute) or by index. Here, `e.name` returns the first field value.',NULL,9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1815,137,'asdict function (dataclasses)','asdict() converts a dataclass instance into a dictionary, preserving field names and values.',NULL,10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1816,137,'falsey','Evaluates to False (falsey)',NULL,6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1817,137,'discard method (set)','discard() silently does nothing when the element is absent, whereas remove() would raise KeyError.',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1818,137,'difference method (set)','difference() returns a new set containing elements present in the first set but absent from the second.',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1819,137,'defaultdict with int','With defaultdict(int), you can write `d[key] += 1` without initialising the key first.',NULL,8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1820,137,'trailing comma tuple gotcha','A trailing comma after a value creates a one‑element tuple. Without it, item would be just the string.',NULL,2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1821,137,'float equality problem','Returns False due to floating-point representation error',NULL,6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1822,137,'update method (set)','s.update(other) adds elements from other to s. s.union(other) creates a completely new set containing the union.',NULL,7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1823,137,'most_common method (Counter)','most_common(n) returns a list of the n most common elements as (element, count) tuples.',NULL,8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1824,137,'property decorator (dataclass)','A property looks like a data attribute but runs a getter method under the hood. In the example, `c.value_of_goods` computes the total value.',NULL,10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1825,137,'frozen dataclass','Immutable instance: assignment to a field raises FrozenInstanceError',NULL,10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1826,137,'truthy','None is one of the falsey values in Python. The other options are all truthy: 1 (non‑zero), [0] (non‑empty list), "False" (non‑empty string).',NULL,6,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1827,137,'nested dictionary','data[''a''] returns the inner dictionary. Accessing [''c''] on that dict raises KeyError because ''c'' is not a key in it.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1828,137,'add method (set)','Sets store only unique elements. When add(2) is called and 2 is already in the set, the set remains {1, 2}.',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1829,137,'pop method (set)','set.pop() removes and returns an arbitrary element. On an empty set, it raises KeyError because there is nothing to remove.',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1830,137,'union method (set)','Returns a new set with elements from both sets',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1831,140,'String','A sequence of characters enclosed in quotes','"This is a string"',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1832,140,'len() function','''Awesome day'' has 10 letters and 1 space, total 11 characters. len() returns the number of characters in the string.','len(my_string)',1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1833,140,'String concatenation','String concatenation with `+` joins strings exactly as they are, resulting in ''Awesome dayfor biking''. Missing the space is a very common beginner mistake.','my_string1 + " " + my_string2',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1834,140,'String indexing','Python strings are zero-indexed: `s[0]` is ''P'', `s[1]` is ''y''. Confusing 1-based indexing leads to the wrong character.','3',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1835,140,'String slicing','The slice `my_string[5:8]` returns characters at positions 5,6,7 → ''m'',''e'','' ''. The common mistake is assuming the end index is inclusive, which would incorrectly include ''d''.','5',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1836,140,'Stride in slicing','`my_string[0:6:2]` returns characters from index 0 to 5 with a step of 2: indices 0,2,4 → ''A'',''e'',''o'' → ''Aeo''.','::-1',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1837,140,'.lower() method','String methods like `.lower()` return a new string, leaving the original unchanged. Without reassignment (`my_string = my_string.lower()`), `my_string` stays ''HELLO''.','lower',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1838,140,'.upper() method','`.upper()` converts every letter to uppercase, so the output is `''THIS IS A NICE STRING''`. The original `my_string` remains `''This is a nice string''`.','upper',2,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1839,140,'.split() method','`''a-b-c-d''.split(''-'', maxsplit=2)` splits at the first two hyphens, producing `[''a'', ''b'', ''c-d'']`. The `maxsplit` parameter prevents further splitting of ''c-d''.','split',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1840,140,'.join() method','`.join()` is a string method: `separator.join(iterable)`. Calling it on the hyphen string correctly inserts it between each list element.','" "',2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1841,140,'.find() method','`.find(''Wenda'')` returns -1 because ''Wenda'' is not in the string. Unlike `.index()`, `.find()` does not raise an exception on failure.','find',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1842,140,'.count() method','`.count()` finds the first `"aa"` at index 0 and consumes it, leaving only `"a"`, which cannot match again. Overlapping occurrences are never counted.','16',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1843,140,'.replace() method','`.replace(old, new, count)` replaces up to `count` occurrences, leaving the rest unchanged. Output: `''The red car is between the blue car and the old house''`.','2',3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1844,140,'String formatting (str.format)','`str.format` expects as many positional arguments as there are empty `{}` placeholders. Supplying fewer raises an IndexError.','"Machine learning provides {} the ability to learn {}"',4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1845,140,'f-string (formatted string literal)','Missing the `f` prefix means the string is a regular string, so `${price}` is printed literally. This is a common mistake when switching between formatting styles.','f',5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1846,140,'Format specifiers in f-strings','Inside an f-string, `{expression:spec}` formats the value. `:.2f` rounds to 2 decimal places.','.2f',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1847,140,'Regular expression (regex)','Pattern describing text to match using metacharacters','r',7,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1848,140,'re.findall()','`re.findall(r''aa'', ''aaa'')` finds one match at index 0-1, then continues from index 2, where only ''a'' remains – insufficient for a second match. Result: `[''aa'']`.','findall',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1849,140,'re.split()','When the pattern passed to `re.split` includes a capturing group, the captured text is also included in the result list. `r''(,)''` captures each comma, yielding `[''one'', '','', ''two'', '','', ''three'']`.','split',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1850,140,'re.sub()','The pattern `(\w+) \1` matches a word followed by a space and the same word again. Replacing with just the captured word (`\1`) removes the duplicate.','sub',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1851,140,'\d metacharacter','Without a raw string, `''\d''` is interpreted as the literal character `d`. Since there are no `d` characters in ''a1b2'', the result is an empty list.','\d',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1852,140,'\w metacharacter','`\w` matches any letter (a-z, A-Z), digit (0-9), or underscore `_`. In ''a1_!'', it matches ''a'', ''1'', and ''_'', but not ''!''.','\w',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1853,140,'\s metacharacter','`\s` matches space, tab, newline, carriage return, and other Unicode whitespace. The string ''a b\tc\nd'' contains a space, a tab (`\t`), and a newline (`\n`), so all three are returned.','\s',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1854,140,'Quantifier +','`\d+` requires at least one digit. The string ''abc'' contains no digits, so `findall` returns an empty list.','+',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1855,140,'Quantifier *','`\d*` matches zero or more digits. In ''abc'', it matches the empty string at position 0, after ''a'', after ''b'', and after ''c'' (four times). Hence `['''', '''', '''', '''']`.','*',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1856,140,'Quantifier ?','`a+?` matches one or more ''a''s, but as few as possible. On ''aaaa'', it matches the first ''a'', then moves past it and matches the next, resulting in four separate ''a''s.','?',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1857,140,'Quantifier {n}','`\d{3}` requires exactly three digits in a row. The string ''12'' only has two, so `search` returns `None`.','{3}',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1858,140,'Quantifier {n,m}','`{5,3}` is an invalid quantifier because the minimum cannot be greater than the maximum. Python''s `re` module raises a `re.error` during compilation.','{2,4}',8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1859,140,'Dot (.) metacharacter','By default, `.` matches any character except newline (`\n`). Therefore, `.+` matches ''line1'', then ''line2'' as separate matches, producing a list of two strings.','.',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1860,140,'Caret (^) anchor','Without `^`, the pattern would match both `the 80s` and `the 90s`. With `^`, only the one at the start is found.','^',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1861,140,'Dollar ($) anchor','With `$`, only the `the 90s` at the end of the string matches. The first occurrence is ignored.','$',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1862,140,'Character set []','In a character set, a hyphen is treated literally if it is placed as the first or last character, or is escaped. Both `[0-9-]` and `[-0-9]` correctly match any digit or ''-''.','[aeiou]',9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1863,140,'Capturing group','`match.group(0)` returns the entire match (`''12-03-2008''`). Individual groups start at index 1.','(\d{2})',10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1864,140,'Non-capturing group (?:)','`(?:\d{2}-){3}` matches three pairs of digits followed by hyphens but does not capture them. This saves memory when capturing is not needed.','?:',11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1865,140,'Backreference (numbered)','`(\d+) \1` matches a number, a space, and the same number again. ''123 124'' does not contain the same number twice, so `search` returns `None`.','\1',12,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1866,140,'str() function','Converts an object to its string representation',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1867,140,'.capitalize() method','Capitalizes first character, lowercases rest',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1868,140,'.rsplit() method','With `maxsplit`, `.split()` consumes the leftmost separators, while `.rsplit()` consumes the rightmost ones. For `''a b c d''` with `maxsplit=2`, `.split()` gives `[''a'',''b'',''c d'']`; `.rsplit()` gives `[''a b'',''c'',''d'']`.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1869,140,'.splitlines() method','Splits string at line boundaries',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1870,140,'.strip() method','Removes leading and trailing whitespace',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1871,140,'.rstrip() method','`.rstrip()` is useful when you want to clean trailing characters while preserving indentation or leading spaces.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1872,140,'.lstrip() method','Use `.lstrip()` to clean only leading characters, e.g., removing indentation without affecting trailing newlines.',NULL,2,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1873,140,'.index() method','Returns index or raises ValueError if not found',NULL,3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1874,140,'Indexed placeholders','Indexed placeholders allow reordering: `{1}` refers to the second argument (`"Hello"`) and `{0}` to the first (`"world"`). Output: `''Hello world''`.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1875,140,'Positional placeholders','Filled in order by positional arguments',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1876,140,'Format specifier in .format()','The format specifier `:.2f` means ''fixed-point notation with 2 decimal places''. The value is rounded to 0.52.',NULL,4,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1877,140,'Type conversion in f-strings','Uses repr() to include quotes in output',NULL,5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1878,140,'Datetime formatting in f-strings','Formats datetime using strftime codes',NULL,5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1879,140,'Inline operations in f-strings','Any valid Python expression can go inside `{}`, including arithmetic. The result is converted to a string and inserted.',NULL,5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1880,140,'Calling functions in f-strings','f-strings allow calling functions inside braces. The return value is converted to a string and placed in the output.',NULL,5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1881,140,'Template strings','Simpler formatting with $ placeholders',NULL,6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1882,140,'.substitute() method (Template)','`substitute()` is designed to fail fast if any placeholder is unresolved. Use `safe_substitute()` to leave missing placeholders untouched.',NULL,6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1883,140,'.safe_substitute() method (Template)','Use `safe_substitute()` when you are not sure all placeholders can be filled, e.g., when the template comes from an external source.',NULL,6,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1884,140,'re module','Python''s built-in module for regular expressions',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1885,140,'\D metacharacter','Matches any non-digit character',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1886,140,'\W metacharacter','Matches any non-word character',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1887,140,'\S metacharacter','Matches any non-whitespace character',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1888,140,'Numbered groups','Returns entire match text',NULL,10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1889,140,'Quantifier on a group','Quantifier on a capturing group captures only the last repetition',NULL,10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1890,140,'Alternation with groups','Parentheses scope the alternation so only ''cat'' or ''dog'' is captured',NULL,11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1891,140,'Named group (?P<name>)','Captures text and assigns it a name',NULL,12,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1892,140,'Backreference to named group','Backreference to a named group in substitution',NULL,12,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1893,140,'Negative lookahead (?!...)','Negative lookahead – asserts that '' transferred'' does NOT follow',NULL,13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1894,140,'Negative lookbehind (?<!...)','Negative lookbehind – excludes matches preceded by ''brown ''',NULL,13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1895,140,'Escape sequences in f-strings','The example is valid. The gotcha is that `f"Hello {name\n}"` would fail. So the question is a trick – this one works.',NULL,5,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1896,140,'Capturing repeated group','`(\d)+` repeatedly captures digits, but each new capture overwrites the previous one. After the entire match, the group holds only the final digit `''5''`.',NULL,10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1897,140,'Dictionary unpacking in .format()','Access dict values in .format() without quotes around key',NULL,4,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1898,140,'Named placeholders','`.format()` raises a KeyError when a placeholder name does not match any keyword argument. Here `name` is missing.',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1899,140,'Greedy matching','Greedy matching of .+ takes the longest possible span',NULL,8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1900,140,'Non-greedy (lazy) matching','Lazy matching with .+? matches as few characters as possible',NULL,8,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1901,140,'re.search() vs re.match()','search anywhere, match only at start of string',NULL,9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1902,140,'Escaping special characters','Matches a literal dot character',NULL,9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1903,140,'Alternation (|) operator','Matches either ''cat'' or ''dog''',NULL,9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1904,140,'Negated character set [^]','Matches any character except digits',NULL,9,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1905,140,'Positive lookahead (?=...)','`(?=\stransferred)` asserts that the file name must be followed by a space and ''transferred''. It excludes ''keywords.txt'' because it is followed by '' error''.',NULL,13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1906,140,'Positive lookbehind (?<=...)','Positive lookbehind – asserts that ''Member: '' precedes the match',NULL,13,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1941,142,'pwd command','pwd ignores any arguments and simply outputs the current directory''s full path.','pwd',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1942,142,'ls command','Files beginning with a dot are considered hidden and are not listed unless you use the -a flag.','ls',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1943,142,'cd command','Without a space, the shell looks for a program named `cd..`, which doesn''t exist.','cd',1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1944,142,'cp command','Fails unless -r flag is used (reports is a directory)','cp',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1945,142,'mv command','Silently overwrites existing_file2 without warning','mv',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1946,142,'rm command','Error: myfolder is a directory, use rm -r','rm',2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1947,142,'cat command','Prints entire file content to terminal','cat',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1948,142,'head command','Shows first 10 lines by default','head',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1949,142,'tail command','Script hangs waiting for new data','tail',3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1950,142,'man command','May show no manual entry for shell built-ins','man',4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1951,142,'cut command','-d sets the delimiter (comma here), and -f 2 selects the second field.','cut',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1952,142,'grep command','The -i flag makes the search case‑insensitive, and *.log expands to all log files in the current directory.','grep',5,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1953,142,'Output redirection (>)','Using `>` accidentally can destroy important data. Always double‑check when you intend to append.','>',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1954,142,'Pipes (|)','Pipes let you build pipelines without creating temporary files. The output of the left command is fed directly to the right command.','|',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1955,142,'wc command','Counts all lines including blank ones','wc',6,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1956,142,'* wildcard','* matches zero or more characters. So it catches `a.txt`, `report.txt`, and even `.txt` (if any).','*.csv',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1957,142,'? wildcard','So `file?.txt` matches `file1.txt` but not `file10.txt` or `file.txt`.','?',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1958,142,'[] wildcard','[0-9] matches any one digit. To allow multiple digits you would need multiple brackets or a different pattern.','78',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1959,142,'{} expansion','Brace expansion treats spaces as literal characters that break the expansion. Write it as `{*.txt,*.csv}`.','txt',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1960,142,'sort command','By default, `sort` performs a lexicographic (dictionary) sort. As strings, ''1'' < ''10'' < ''2''. Use `-n` to sort numerically.','sort',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1961,142,'uniq command','`uniq` only removes duplicate lines that are immediately adjacent. To remove all duplicates, the input must be sorted first (`sort | uniq`).','uniq',7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1962,142,'echo command','Prints Hello followed by username, variable expands','echo',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1963,142,'set command','`set | grep HISTFILESIZE` filters the long list to show just the line with HISTFILESIZE.','set',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1964,142,'Variable assignment','Using $ on left side of assignment is an error','datasets',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1965,142,'$ prefix','The $ tells the shell to replace the variable name with its contents before running the command.','$',8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1966,142,'for loop syntax','When written on one line, you need a semicolon before `do` and before `done`.',';',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1967,142,'Wildcards in loops','Wrapping the wildcard in single quotes suppresses expansion, so the loop variable receives the literal string `seasonal/*.csv` instead of a list of matching files.','*',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1968,142,'Multiple commands in loop','Multiple commands on one line must be separated by `;` or a newline. Here `echo $f head ...` is interpreted as a single command, so `head` becomes text printed by echo.',';',9,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1969,142,'nano editor','Ctrl+S may freeze terminal; it does not save','nano',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1970,142,'bash script','Missing execute permission; use chmod +x','bash',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1971,142,'Script parameters $@','When no arguments are provided, `$@` expands to nothing. The `for` loop therefore has an empty list and does not run any iterations.','$@',10,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1972,142,'Script parameters $1, $2, ...','In a script, `$0` contains the script''s name as it was invoked. `$1`, `$2`, etc., are the actual arguments.','$1',10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1973,142,'Comments in shell (#)','Everything after `#` on that line is treated as a comment, except when the `#` appears inside quotes.','#',10,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1974,142,'Quoting filenames with spaces','The shell splits unquoted command-line arguments on spaces, so `rm file with spaces.txt` becomes three separate arguments. To delete a file with spaces, use quotes: `rm ''file with spaces.txt''` or escape the spaces.','2017 July data.csv',11,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1975,142,'Saving command history to a file','`history` lists all commands, `tail -n 5` keeps the last five, and `>` writes them to a file.','>',11,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1976,142,'Shell','Command-line interface that interprets typed commands',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1977,142,'Command Prompt','Indicator that the shell is ready for input',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1978,142,'Filesystem','Hierarchical structure organizing files and directories',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1979,142,'Absolute Path','Absolute path',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1980,142,'Relative Path','Relative path',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1981,142,'Home Directory','Home directory',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1982,142,'Current Working Directory','Prints working directory, ignores extra argument',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1983,142,'Parent directory (..)','Command fails because missing space between cd and ..',NULL,1,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1984,142,'Tab completion','Does not work inside quotes',NULL,3,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1985,142,'Command-line flags','Flag modifying command behavior (e.g., head/tail)',NULL,4,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1986,142,'history command','Output is empty because history is not enabled in non-interactive shells',NULL,5,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1987,142,'Wildcards','Does not expand wildcard; looks for literal file named *.csv',NULL,7,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1988,142,'Environment Variable','Variable not visible to child processes',NULL,8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1989,142,'Shell Variable','Assignment with spaces causes ''name: command not found'' error',NULL,8,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1990,142,'Stopping a program (Ctrl+C)','Does not work as expected because nano captures keys',NULL,11,'general',2,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1991,142,'rmdir command','Error: directory not empty',NULL,2,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1992,142,'less command','Pressing q after quitting less types ''q'' on command line',NULL,3,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1993,142,'Loops in shell scripts','The idiomatic way to iterate over all arguments is `for arg in "$@"; do ... done` (unquoted `$@` also works but has word-splitting issues; here the given correct option a is simple and works). Option b misses the semicolon.',NULL,10,'general',3,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1994,142,'ls .','Lists files in current directory',NULL,1,'general',1,'2026-06-18 07:39:40');
INSERT INTO concepts VALUES(1995,141,'pass statement','A placeholder statement that does nothing; used in empty class bodies.','pass',2,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(1996,141,'Docstrings for classes','Docstrings are string literals placed directly after the class (or function) definition. They are accessed via `help()` and document the class.','"""This class does nothing"""',3,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(1997,141,'type() function','Built‑in function that returns the class (type) of an object.','type',1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(1998,141,'dir() function','Built‑in function that displays all attributes and methods of an object.','dir',1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(1999,141,'Object creation','Creating an instance by calling the class name with parentheses.','()',2,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2000,141,'Method definition','Defined with def inside a class; first parameter must be self.','self',2,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2001,141,'Attribute creation (assignment)','self.name = new_name   (inside a method)','self.name',2,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2002,141,'Using attributes in methods','print(''I am Customer '' + self.name)','self.name',2,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2003,141,'Class definition syntax','Uses the `class` keyword, class name, colon, and indented body.',':',2,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2004,141,'__init__ method (constructor)',unistr('def __init__(self, name):\u000a    self.name = name'),'__init__',3,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2005,141,'Default arguments in __init__','Default arguments are evaluated only once at definition time. If the default is mutable (e.g., a list), all instances share the same object. Using immutable defaults like numbers or strings avoids this pitfall.','balance',3,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2006,141,'Class attributes','Defined in the class body outside methods; shared by all instances.','MIN_SALARY',4,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2007,141,'Modifying class attribute via instance','emp1.MIN_SALARY = 50000 creates an instance attribute, leaving the class attribute unchanged.','50000',4,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2008,141,'Class methods (@classmethod)',unistr('@classmethod\u000adef from_file(cls, filename):'),'classmethod',5,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2009,141,'Alternative constructors','return cls(name, salary)  # creates an instance from custom data.','cls',5,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2010,141,'Inheritance syntax','In Python, every class definition header must end with a colon. Without it, a `SyntaxError` is raised.','BankAccount',6,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2011,141,'isinstance() function','Because `SavingsAccount` inherits from `BankAccount`, an instance of the subclass is also an instance of the superclass. This is the ''is‑a'' relationship demonstrated in the course.','isinstance',6,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2012,141,'Customizing constructor in child class','When a child class defines its own `__init__`, the parent''s `__init__` is not called automatically. The explicit call `ParentClass.__init__(self, ...)` is needed to initialise inherited attributes like `self.balance`.','BankAccount',7,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2013,141,'Adding methods in child class','Child classes can define new methods that rely on attributes from both the parent and the child, extending the parent’s functionality.','=1',7,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2014,141,'Overriding methods','Method overriding means the child''s version replaces the parent''s when called on a child instance. However, the child can still call the original parent method using `ParentClass.method(self, ...)`.','BankAccount',7,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2015,141,'__eq__ method','When `__eq__` is defined, Python uses it for the `==` operator. The method compares the two attributes, and since they are equal, the result is `True`.','__eq__',8,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2016,141,'Type checking in __eq__','Without a type check, equality could be true across unrelated classes that happen to have the same attribute names. Adding `type(self) == type(other)` ensures only objects of the exact same class are considered equal.','type',8,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2017,141,'__eq__ in inheritance','When comparing `child_obj == parent_obj`, Python looks up `child_obj.__class__.__eq__` (the child''s definition) and invokes it with `parent_obj` as the `other` argument. This can lead to different behaviour than `parent_obj == child_obj` if the implementations differ.','__eq__',9,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2018,141,'__str__ method','`print(obj)` calls `str(obj)`, which in turn calls `obj.__str__()`. If `__str__` is defined, its return value is printed.','__str__',9,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2019,141,'__repr__ method','If `__str__` is not defined, `str(obj)` returns `obj.__repr__()`. So `print()` shows the formal developer representation.','__repr__',9,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2020,141,'Exception handling (try-except)','`try‑except` prevents program termination by intercepting specific exceptions. The `except` block only runs if the named exception (or a subclass) is raised.','except',10,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2021,141,'Raising exceptions (raise)','`raise` is used to throw an exception when a condition occurs that cannot be handled locally. You can pass an error message to describe the problem.','raise',10,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2022,141,'Custom exceptions','Custom exceptions are user‑defined error types. They are typically simple subclasses of `Exception` (or a more specific built‑in exception). They allow application‑specific error handling.','Exception',10,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2023,141,'Using custom exceptions in class','When the negative balance triggers `BalanceError`, the `except` clause catches it and executes the fallback, creating a new instance with balance 0. Then `cust.name` is printed normally.','BalanceError',10,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2024,141,'self convention','The standard name for the first parameter of instance methods.',NULL,3,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2025,141,'Procedural programming','Code written as a sequence of steps; no bundling of data and behavior.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2026,141,'Object-oriented programming (OOP)','Paradigm organizing code as interacting objects with state and behavior.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2027,141,'Object','Instance of a class; combines data (attributes) and functionality (methods).',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2028,141,'State','Data associated with an object, represented by attributes.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2029,141,'Behavior','methods',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2030,141,'Class','Blueprint or template for creating objects, defining possible attributes and methods.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2031,141,'Instance','A specific realization of a class blueprint; an object created from a class.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2032,141,'Attribute','A variable bound to an object, storing its state; accessed via obj.attr.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2033,141,'Method','A function defined inside a class; defines object behavior, first parameter is self.',NULL,1,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2034,141,'Inheritance (core principle)','A child class extends a parent class, acquiring its attributes and methods.',NULL,4,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2035,141,'Polymorphism (core principle)','Different objects respond to the same method call each in their own way.',NULL,4,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2036,141,'cls argument','The first parameter of a class method, referencing the class itself.',NULL,5,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2037,141,'Use cases for class methods','Alternative constructors, methods that don''t need instance data, Singleton pattern.',NULL,5,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2038,141,'Object equality default behavior','By default, `==` calls `object.__eq__`, which returns `True` only if the two operands are the exact same object (i.e., `c1 is c2`).',NULL,8,'general',3,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2039,141,'Method overriding with additional arguments','Polymorphism relies on method signatures being compatible. Adding required parameters changes the contract, so the child is no longer a drop‑in replacement for the parent.',NULL,7,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2040,141,'Other comparison operators','You do not need to explicitly define `__ne__` if the desired behaviour is the logical opposite of equality. Defining `__ne__` separately is only necessary for custom inequality logic.',NULL,8,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2041,141,'Difference between __str__ and __repr__','`__str__` should return a nice, informal string. `__repr__` should return a string that, if passed to `eval()`, would ideally recreate the object (though not always required).',NULL,9,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2042,141,'finally block','After the `ZeroDivisionError` is caught and ''Oops'' is printed, execution continues to the `finally` block, which prints ''Done''.',NULL,10,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2043,141,'CamelCase naming for classes','Customer, BankAccount – each word starts uppercase, no underscores.',NULL,3,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2044,141,'snake_case for methods and attributes','set_name, balance – lowercase with underscores.',NULL,3,'general',1,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2045,141,'self parameter','A reference to the instance of the class, used to access attributes and other methods.',NULL,2,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2046,141,'Instance attributes','Belong to a specific object; each instance can have different values.',NULL,4,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2047,141,'Encapsulation','Bundling data (attributes) and behavior (methods) inside a class, hiding internal details.',NULL,4,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2048,141,'Parent class (superclass)','The class whose name appears in parentheses is the parent (superclass). In `class SavingsAccount(BankAccount):`, `BankAccount` is the superclass.',NULL,6,'general',2,'2026-06-19 04:29:19');
INSERT INTO concepts VALUES(2049,141,'Child class (subclass)','`SavingsAccount` is the child class (subclass) because it inherits from `BankAccount`. The child can extend or override the parent’s functionality.',NULL,6,'general',2,'2026-06-19 04:29:19');
INSERT INTO flashcards VALUES(871,1049,72,'What is Python?','A high-level programming language widely used for data science, machine learning, web development, and automation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(872,1050,72,unistr('What does the ''>>>'' prompt indicate in this code?\u000a\u000a```python\u000a>>> 2 + 2\u000a4\u000a```'),'Python Shell — an interactive command-line interface that executes Python commands one at a time.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(873,1051,72,'What is a Python Script?','A Python file containing code that can be executed all at once, with a .py extension.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(874,998,72,unistr('What does this code print?\u000a\u000a```python\u000aprint(4 + 5)\u000a```'),unistr('9\u000a\u000aprint() evaluates the expression and outputs the result.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(875,999,72,'What is the result of 19 / 2 in Python?',unistr('9.5\u000a\u000aThe / operator always performs true division and returns a float.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(876,1000,72,'Write the code to assign the value 1.79 to a variable named height.',unistr('```python\u000aheight = 1.79\u000a```\u000a\u000aThe assignment operator = stores the right-hand value into the variable.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(877,1001,72,unistr('What is wrong with this code?\u000a\u000a```python\u000a5 = x\u000a```'),'The assignment direction is reversed; the variable name must be on the left.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(878,1052,72,'What is a data type in Python?','A classification of data, such as integer, float, string, or boolean.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(879,1053,72,'What does type(5) return?',unistr('<class ''int''>\u000a\u000a5 is a whole number, so it''s an integer.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(880,1054,72,'What does type(1.79) return?',unistr('<class ''float''>\u000a\u000aNumbers with a decimal point are floats.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(881,1055,72,'What does type(''body mass index'') return?',unistr('<class ''str''>\u000a\u000aText enclosed in quotes is a string.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(882,1056,72,unistr('What is wrong with this code?\u000a\u000a```python\u000ax = true\u000a```'),'true should be capitalized: True. Python''s boolean literals are True and False.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(883,1002,72,unistr('Given:\u000a\u000a```python\u000abmi = 21.4413\u000aprint(type(bmi))\u000a```\u000aWhat is printed?'),unistr('<class ''float''>\u000a\u000abmi is a float, so type() returns the float type object.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(884,1057,72,'Write the expression to calculate BMI using variables weight and height (BMI = weight / height²).',unistr('```python\u000abmi = weight / height ** 2\u000a```\u000a\u000aThe ** operator performs exponentiation.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(885,1004,72,'Create a list named fam containing the heights 1.73, 1.68, 1.71, 1.89.',unistr('```python\u000afam = [1.73, 1.68, 1.71, 1.89]\u000a```\u000a\u000aLists are defined with square brackets.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(886,1005,72,unistr('What concept does this code demonstrate?\u000a\u000a```python\u000afam2 = [["liz", 1.73], ["emma", 1.68], ["mom", 1.71], ["dad", 1.89]]\u000a```'),'List of Lists — a nested list structure where each element is itself a list.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(887,1005,72,unistr('Given:\u000a\u000a```python\u000afam2 = [["liz", 1.73], ["emma", 1.68], ["mom", 1.71], ["dad", 1.89]]\u000aprint(fam2[1][0])\u000a```\u000aWhat is output?'),unistr('emma\u000a\u000aThe first index selects the second inner list, the second index picks the first element of that inner list.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(888,1006,72,'What does type(fam) return if fam = [1.73, 1.68, 1.71, 1.89]?',unistr('<class ''list''>\u000a\u000aLists are objects of type list.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(889,1007,72,unistr('Given:\u000a\u000a```python\u000afam = [''liz'', 1.73, ''emma'', 1.68, ''mom'', 1.71, ''dad'', 1.89]\u000aprint(fam[6])\u000a```\u000aWhat is output?'),unistr('dad\u000a\u000aIndex 6 corresponds to the seventh element because counting starts at 0.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(890,1008,72,'Given fam as above, what does fam[-1] return?',unistr('1.89\u000a\u000aNegative indices count from the end: -1 is the last element.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(891,1009,72,'Given fam as above, what does fam[3:5] return?',unistr('[1.68, ''mom'']\u000a\u000aThe slice starts at index 3 (inclusive) and stops before index 5.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(892,1009,72,'Write a slice to get the elements at indices 1, 2, and 3 from the list fam.',unistr('```python\u000afam[1:4]\u000a```\u000a\u000aBecause the end index is exclusive, you go one past the last desired index.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(893,1010,72,'Change the element at index 7 of the list fam to 1.86.',unistr('```python\u000afam[7] = 1.86\u000a```\u000a\u000aLists are mutable, so you can replace an element by index.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(894,1011,72,unistr('Given:\u000a\u000a```python\u000afam = [''lisa'', 1.74, ''emma'', 1.68, ''mom'', 1.71, ''dad'', 1.86]\u000aprint(fam + [''me'', 1.79])\u000a```\u000aWhat is output?'),unistr('[''lisa'', 1.74, ''emma'', 1.68, ''mom'', 1.71, ''dad'', 1.86, ''me'', 1.79]\u000a\u000a+ concatenates two lists into a new one.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(895,1012,72,'Delete the element at index 2 from the list fam.',unistr('```python\u000adel fam[2]\u000a```\u000a\u000aThe del statement removes an item at a specific index.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(896,1012,72,'Given fam = [''lisa'', 1.74, ''emma'', 1.68, ''mom''], what is fam after del fam[2]?',unistr('[''lisa'', 1.74, 1.68, ''mom'']\u000a\u000aThe element ''emma'' is removed, and 1.68 shifts to index 2.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(897,1012,72,'What is the difference between del fam[2] and fam.remove(''emma'')?','del removes by index; remove() removes by value (first occurrence). Both modify the list in place.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(898,1013,72,'How do you create an independent copy of a list x?',unistr('```python\u000ay = list(x)\u000a# or\u000ay = x[:]\u000a```\u000a\u000aBoth create a new list with the same elements.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(899,1013,72,unistr('What concept does this code demonstrate?\u000a\u000a```python\u000ax = [''a'', ''b'', ''c'']\u000ay = list(x)\u000ay[1] = ''z''\u000aprint(x)\u000a```\u000aOutput: [''a'', ''b'', ''c'']'),'List Copying — using list() creates a new list, so changes to y do not affect x.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(900,1013,72,unistr('Given:\u000a\u000a```python\u000ax = [''a'', ''b'', ''c'']\u000ay = list(x)\u000ay[1] = ''z''\u000aprint(x[1])\u000a```\u000aWhat is printed?'),unistr('b\u000a\u000aBecause y is a copy, the original x remains unchanged.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(901,1014,72,unistr('What does this code print?\u000a\u000a```python\u000ax = ["a", "b", "c"]\u000ay = x\u000ay[1] = "z"\u000aprint(x)\u000a```'),unistr('[''a'', ''z'', ''c'']\u000a\u000ay = x makes y a reference to the same list; mutations through y affect x.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(902,1014,72,unistr('What is the mistake in this code?\u000a\u000a```python\u000ax = [1, 2, 3]\u000ay = x\u000ay[0] = 9\u000aprint(x)   # user expects [1,2,3]\u000a```'),'y = x creates a reference, not a copy. Both variables point to the same list, so x is now [9, 2, 3].','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(903,1014,72,'What is the difference between y = x and y = list(x) when x is a list?','y = x makes y a reference to the same list; modifying one affects the other. y = list(x) creates a new, independent copy.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(904,1015,72,'What is a function in Python?','A reusable block of code that performs a specific task, called by name with parentheses.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(905,1016,72,'What does max([1.73, 1.68, 1.71, 1.89]) return?',unistr('1.89\u000a\u000amax() returns the largest item in the iterable.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(906,1017,72,'What does round(1.68) return?',unistr('2\u000a\u000aWhen ndigits is omitted, round() returns an integer (rounded to the nearest whole number).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(907,1017,72,'What is surprising about round(2.5)?','It returns 2, not 3, because Python uses banker''s rounding: .5 cases round to the nearest even number.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(908,1017,72,'Round the number 1.68 to one decimal place.',unistr('```python\u000around(1.68, 1)\u000a```\u000aThe second argument is the number of decimal places.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(909,1018,72,'How do you view the documentation for the round function?',unistr('```python\u000ahelp(round)\u000a```\u000a\u000ahelp() is a built‑in function that displays documentation.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(910,1019,72,'What is a method in Python?','A function that is associated with a specific object and called using dot notation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(911,1020,72,'Given fam = [''liz'', 1.73, ''emma'', 1.68, ''mom'', 1.71, ''dad'', 1.89], what does fam.index(''mom'') return?',unistr('4\u000a\u000aThe method returns the zero‑based index of the first occurrence.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(912,1020,72,'Find the index of ''dad'' in the list fam.',unistr('```python\u000afam.index(''dad'')\u000a```\u000a\u000aIt returns the position of the first match.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(913,1021,72,'Given fam includes two occurrences of 1.73, what does fam.count(1.73) return?',unistr('2\u000a\u000acount() returns the number of times the value appears.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(914,1022,72,unistr('What does this code print?\u000a\u000a```python\u000afam = [''liz'', 1.73]\u000aresult = fam.append(''me'')\u000aprint(result)\u000a```'),unistr('None\u000a\u000aappend() modifies the list in place and returns None.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(915,1022,72,unistr('What is wrong with this code?\u000a\u000a```python\u000aitems = []\u000aitems = items.append(''a'')\u000a```'),'append() returns None, so items becomes None after the assignment. Simply call items.append(''a'') without reassigning.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(916,1022,72,'Add the string ''me'' to the end of the list fam.',unistr('```python\u000afam.append(''me'')\u000a```\u000a\u000aappend() takes one argument and adds it at the end.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(917,1023,72,'What does ''liz''.capitalize() return?',unistr('''Liz''\u000a\u000aThe first character is uppercased, the rest lowercased.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(918,1024,72,'What does ''liz''.replace(''z'', ''sa'') return?',unistr('''Lisa''\u000a\u000aAll occurrences of ''z'' are replaced by ''sa''.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(919,1024,72,'Replace all ''z'' with ''sa'' in the string sister.',unistr('```python\u000asister.replace(''z'', ''sa'')\u000a```\u000a\u000aThis returns a new string; the original sister remains unchanged.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(920,1025,72,'Given fam = [''liz'', ''emma''], what is fam after fam.remove(''emma'')?',unistr('[''liz'']\u000a\u000aremove() deletes the first occurrence of the given value.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(921,1025,72,unistr('What is wrong with this code?\u000a\u000a```python\u000aresult = fam.remove(''emma'')\u000aprint(result)\u000a```'),'remove() returns None, so result is None. The list is still modified, but printing result outputs None.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(922,1026,72,unistr('What does this print?\u000a\u000a```python\u000anums = [3, 1, 2]\u000anums.reverse()\u000aprint(nums)\u000a```'),unistr('[2, 1, 3]\u000a\u000areverse() reverses the list in place.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(923,1030,72,'What is a Python package?','A collection of Python modules containing functions and methods for specific tasks (e.g., NumPy, Matplotlib).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(924,1058,72,'What is a module?','A single Python script file (.py) that contains functions, classes, and variables.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(925,1027,72,'Import the NumPy module.',unistr('```python\u000aimport numpy\u000a```\u000a\u000aNow you can use numpy.array(), numpy.mean(), etc.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(926,1027,72,unistr('What is wrong with this code?\u000a\u000a```python\u000aimport numpy\u000aarray([1, 2, 3])\u000a```'),'array is not defined; after ''import numpy'', you must call numpy.array([1, 2, 3]).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(927,1027,72,'What is the difference between import numpy and import numpy as np?','import numpy keeps the full name; import numpy as np creates an alias ''np'' that is shorter and commonly used.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(928,1028,72,'Import NumPy with the conventional alias np.',unistr('```python\u000aimport numpy as np\u000a```\u000a\u000aNow you can use np.array() etc.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(929,1029,72,'Import only the array function from NumPy.',unistr('```python\u000afrom numpy import array\u000a```\u000a\u000aNow you can call array() directly without a prefix.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(930,1029,72,unistr('What is wrong with this code?\u000a\u000a```python\u000afrom numpy import array\u000aarr = numpy.array([1,2])\u000a```'),'The name ''numpy'' is not defined; only ''array'' was imported. Use arr = array([1,2]) instead.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(931,1059,72,'What is NumPy?','A Python package for numerical computing, providing fast arrays and mathematical functions.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(932,1036,72,'Create a NumPy array from the list height = [1.73, 1.68, 1.71] (assume import numpy as np).',unistr('```python\u000anp_height = np.array(height)\u000a```\u000a\u000anp.array() converts a list to a NumPy array.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(933,1036,72,'After creating np_height as above, what does type(np_height) return?',unistr('<class ''numpy.ndarray''>\u000a\u000aIt''s a NumPy n‑dimensional array.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(934,1031,72,'Convert a Python list my_list into a NumPy array.',unistr('```python\u000anp.array(my_list)\u000a```\u000a\u000aPass the list as the single argument.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(935,1032,72,unistr('What concept allows this code to work?\u000a\u000a```python\u000abmi = np_weight / np_height ** 2\u000a```\u000a(where np_weight and np_height are NumPy arrays)'),'Vectorization — performing arithmetic operations on entire arrays element‑wise without explicit loops.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(936,1032,72,unistr('What does this print?\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([1, 2, 3])\u000aprint(arr + arr)\u000a```'),unistr('[2 4 6]\u000a\u000a+ performs element‑wise addition for NumPy arrays.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(937,1033,72,unistr('What does this code output?\u000a\u000a```python\u000aimport numpy as np\u000aprint(np.array([1.0, "is", True]))\u000a```'),unistr('[''1.0'' ''is'' ''True'']\u000a\u000aAll elements are coerced to strings because the array must be homogeneous.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(938,1033,72,unistr('What is wrong with this code?\u000a\u000a```python\u000aarr = np.array([1.73, 1.68, ''1.71''])\u000aprint(np.mean(arr))\u000a```'),'The array becomes all strings because of the string ''1.71''. np.mean() on a string array raises a TypeError.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(939,1033,72,'Create a NumPy array from a list that contains numbers and no strings, to ensure it stays numeric.',unistr('```python\u000anp.array([1.73, 1.68, 1.71])\u000a```\u000a\u000aOnly include numeric types to get a numeric array.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(940,1034,72,unistr('What do these two lines print?\u000a\u000a```python\u000apython_list = [1,2,3]\u000aprint(python_list + python_list)\u000a\u000anumpy_array = np.array([1,2,3])\u000aprint(numpy_array + numpy_array)\u000a```'),unistr('[1,2,3,1,2,3]\u000a[2 4 6]\u000a\u000aLists concatenate; arrays add element‑wise.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(941,1034,72,'What is the difference between Python list + and NumPy array +?','List + concatenates the lists into a longer list. Array + performs element‑wise addition, returning an array of sums.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(942,1034,72,'What happens if you try to add a Python list and a NumPy array with +?','TypeError — you cannot directly add a list and an array with +. Convert the list to an array first.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(943,1035,72,'Given bmi = np.array([21.85, 20.98, 21.75, 24.75, 21.44]), what does bmi[bmi > 23] return?',unistr('array([24.75])\u000a\u000aOnly elements where the condition is True are kept.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(944,1035,72,unistr('What is wrong with this code?\u000a\u000a```python\u000abmi[bmi > 23 and bmi < 25]\u000a```'),'Use & instead of ''and''. The correct syntax is bmi[(bmi > 23) & (bmi < 25)]. Parentheses are required.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(945,1035,72,'Select all BMI values that are less than 20 from the array bmi.',unistr('```python\u000abmi[bmi < 20]\u000a```\u000a\u000aThis uses a boolean condition inside the square brackets.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(946,1037,72,'Create a 2D NumPy array with two rows: [1.73, 1.68, 1.71] and [65.4, 59.2, 63.6].',unistr('```python\u000anp_2d = np.array([[1.73, 1.68, 1.71], [65.4, 59.2, 63.6]])\u000a```\u000a\u000aThe inner lists become rows.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(947,1037,72,'What is wrong with trying to create a 2D array with np.array([[1,2], [3,4,5]])?','Rows have different lengths; NumPy will create a 1D array of list objects, not a true 2D numeric array.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(948,1037,72,'After creating the 2D array correctly as above, what is its shape?',unistr('(2, 3)\u000a\u000aTwo rows and three columns.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(949,1038,72,'What does np_2d.shape return for a 2D array with 2 rows and 5 columns?',unistr('(2, 5)\u000a\u000a.shape is an attribute, not a method.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(950,1039,72,'Given np_2d as above, what does np_2d[0, 2] return?',unistr('1.71\u000a\u000aRow 0, column 2.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(951,1039,72,'Select the element at row 1, column 0 from np_2d.',unistr('```python\u000anp_2d[1, 0]\u000a```\u000a\u000aThe row comes first, then the column.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(952,1039,72,'What is the difference between np_2d[0][2] and np_2d[0, 2]?','Both return the same element (row 0, column 2). np_2d[0, 2] is the more efficient NumPy idiom, while [0][2] chains two separate indexing operations.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(953,1040,72,'Given np_2d with shape (2,5), what does np_2d[:, 1:3] return?','A 2D subarray containing all rows, but only columns 1 and 2.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(954,1040,72,'Select all rows and the first column from np_2d.',unistr('```python\u000anp_2d[:, 0]\u000a```\u000a\u000aThe colon selects all rows; 0 selects the first column.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(955,1040,72,'You want to select columns 1 to 2 of np_2d, but you write np_2d[1:2]. What does this actually do?','It selects rows 1 to 2 (a 2D array of those rows), not columns. To select columns, use np_2d[:, 1:2].','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(956,1041,72,'Using the course''s np_city array, what does np.median(np_city[:, 0]) return?',unistr('1.75\u000a\u000aIt computes the median of the first column (heights).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(957,1041,72,'Compute the median of the array arr.',unistr('```python\u000anp.median(arr)\u000a```\u000a\u000aReturns the median value.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(958,1042,72,'What does np.mean([1, 2, 3, 4]) return?',unistr('2.5\u000a\u000aThe arithmetic mean of the values.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(959,1042,72,'Calculate the average of the NumPy array np_weight.',unistr('```python\u000anp.mean(np_weight)\u000a```\u000a\u000aReturns the mean weight.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(960,1043,72,'What does np.sum([1, 2, 3]) return?',unistr('6\u000a\u000aIt adds all elements together.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(961,1044,72,'What does np.sort([3, 1, 2]) return?',unistr('array([1, 2, 3])\u000a\u000aIt returns a sorted copy; the original array is unchanged.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(962,1044,72,'Sort the array arr in ascending order, returning a new sorted array.',unistr('```python\u000anp.sort(arr)\u000a```\u000a\u000aTo sort in place, use arr.sort() (the ndarray method).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(963,1045,72,'Generate 5000 height samples from a normal distribution with mean 1.75 and standard deviation 0.20.',unistr('```python\u000anp.random.normal(1.75, 0.20, 5000)\u000a```\u000a\u000aThe arguments are (loc, scale, size).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(964,1045,72,'What is the shape of np.random.normal(0, 1, 100)?',unistr('(100,)\u000a\u000aIt''s a 1D array of 100 samples.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(965,1045,72,'What happens if you call np.random.normal() without importing numpy?','NameError: name ''np'' is not defined. You must import numpy (usually as np) first.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(966,1046,72,'What does np.round([1.678, 2.345], 1) return?',unistr('array([1.7, 2.3])\u000a\u000aEach element is rounded to one decimal place.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(967,1046,72,'Round the array arr to 2 decimal places.',unistr('```python\u000anp.round(arr, 2)\u000a```\u000a\u000aThe second argument is the number of decimals.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(968,1047,72,'Stack two 1D arrays height and weight as columns into a 2D array.',unistr('```python\u000anp.column_stack((height, weight))\u000a```\u000a\u000aThe arrays must have the same length.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(969,1047,72,'If height and weight are each 1D arrays of length 3, what is the shape of np.column_stack((height, weight))?',unistr('(3, 2)\u000a\u000aThree rows, two columns.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(970,1048,72,'What is the off‑diagonal value in the matrix returned by np.corrcoef([1,2,3], [1,2,3])?',unistr('1.0\u000a\u000aPerfect positive correlation because the two variables are identical.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(971,1048,72,'Compute the correlation between two arrays x and y.',unistr('```python\u000anp.corrcoef(x, y)\u000a```\u000a\u000aReturns a 2x2 correlation matrix.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(972,1048,72,'Why does np.corrcoef(height, weight) fail if height contains NaN values?','np.corrcoef does not handle NaN; you must remove or impute missing values before computing correlation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(973,1060,72,'What is an outlier?','A data point significantly different from others, which can distort averages like the mean.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(974,1060,72,'Which statistic is more robust to outliers: the mean or the median?',unistr('The median.\u000a\u000aIt is not pulled by extreme values.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(975,1061,72,'Convert a NumPy array height_in_inches to meters using the factor 0.0254.',unistr('```python\u000aheight_m = height_in_inches * 0.0254\u000a```\u000a\u000aVectorized multiplication applies the factor to every element.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(976,1062,73,'What is the standard convention for importing matplotlib''s pyplot subpackage?',unistr('```python\u000aimport matplotlib.pyplot as plt\u000a```\u000aThis imports the pyplot module and gives it the alias `plt`, providing a MATLAB-like plotting interface.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(977,1062,73,unistr('```python\u000aimport matplotlib.pyplot as plt\u000a```\u000aWhat programming concept does this code represent?'),'Importing a module (specifically the pyplot subpackage) and giving it an alias (plt). This is the standard way to access matplotlib''s plotting functions.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(978,1063,73,'Write the code to create a line plot with `year` on the x-axis and `pop` on the y-axis using matplotlib (assuming `import matplotlib.pyplot as plt` is already done).',unistr('```python\u000aplt.plot(year, pop)\u000a```\u000aThe first argument is the x-axis data, the second is the y-axis data. It draws lines between consecutive points.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(979,1064,73,'What does `plt.scatter()` do, and how is it different from `plt.plot()`?','`plt.scatter()` creates a scatter plot where each data point is shown as an individual marker, with no connecting lines. In contrast, `plt.plot()` draws lines between points to show trends.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(980,1065,73,'Why is `plt.show()` necessary after calling `plt.plot()` or `plt.scatter()`?','`plt.show()` displays the current figure. Without it, the plot is created only in memory and never appears on screen. It must be called after all plotting commands.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(981,1106,73,'What is a histogram, and what does the `bins` parameter control?','A histogram is a plot that shows the distribution of a dataset by dividing values into bins (intervals) and counting how many values fall into each bin. The `bins` parameter controls the number of equal-width bins.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(982,1066,73,unistr('```python\u000aplt.hist(values, bins=10)\u000a```\u000aWhat does this code do, and what does the `bins=10` argument mean?'),'It creates a histogram of the data in `values`. The `bins=10` argument tells matplotlib to divide the data range into 10 equal-width bins and count how many values fall into each bin.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(983,1066,73,unistr('```python\u000aimport matplotlib.pyplot as plt\u000adata = [0, 0.6, 1.4, 1.6, 2.2, 2.5, 2.6, 3.2, 3.5, 3.9, 4.2, 6]\u000aplt.hist(data, bins=20)\u000aplt.show()\u000a```\u000aWhat is the potential problem with this code?'),'With data ranging from 0 to 6 (range 6), using 20 bins creates bins of width 0.3. Many bins will be empty or have only one observation, producing a noisy histogram that hides the underlying distribution. A smaller number of bins (e.g., 3 or 5) would be more appropriate.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(984,1067,73,'You have a line plot of population over years. Write the code to add the label ''Year'' to the x‑axis.',unistr('```python\u000aplt.xlabel(''Year'')\u000a```\u000aThe function `plt.xlabel()` sets the label for the horizontal axis. It should be called before `plt.show()`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(985,1068,73,'Write the code to add the label ''Population (millions)'' to the y‑axis of your current plot.',unistr('```python\u000aplt.ylabel(''Population (millions)'')\u000a```\u000a`plt.ylabel()` sets the label for the vertical axis. Units in parentheses are a good practice for clarity.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(986,1069,73,'What does `plt.title()` do, and where should it be placed relative to other plotting commands?','`plt.title()` adds a title to the current plot. It should be placed after the plotting commands (e.g., `plt.plot()`) and before `plt.show()`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(987,1070,73,unistr('```python\u000aplt.yticks([0, 2, 4, 6, 8, 10], [''0'', ''2B'', ''4B'', ''6B'', ''8B''])\u000a```\u000aWhat error will this cause, and why?'),'ValueError: The number of tick positions (6) does not match the number of labels (5). `plt.yticks(ticks, labels)` requires the two lists to have the same length.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(988,1071,73,'What is a dictionary in Python? Provide a code example.','A dictionary is an unordered collection of key‑value pairs, where keys must be unique and immutable (e.g., strings, numbers, tuples). Example: `world = {''afghanistan'':30.55, ''albania'':2.77, ''algeria'':39.21}`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(989,1071,73,unistr('```python\u000ad = {[1,2]: ''list key''}\u000a```\u000aWhy does this code raise a TypeError?'),'Because dictionary keys must be immutable (hashable). Lists are mutable, so they cannot be used as keys. The error message is: `TypeError: unhashable type: ''list''`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(990,1072,73,'What is a key‑value pair in a dictionary, and how is it written in Python?','A key‑value pair is a mapping from a unique key to a value, written as `key: value`. For example, in `''albania'': 2.77`, the key is `''albania''` and the value is `2.77`. Keys and values are separated by a colon.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(991,1073,73,unistr('```python\u000aworld = {''afghanistan'':30.55, ''albania'':2.77}\u000aprint(world[''albania''])\u000a```\u000aWhat does this code output, and what concept does it demonstrate?'),'Output: `2.77`. It demonstrates dictionary access using square brackets: `dict[key]` returns the value associated with that key.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(992,1107,73,'Why can a tuple be used as a dictionary key but a list cannot?','Tuples are immutable (cannot be changed after creation), so they are hashable and can serve as keys. Lists are mutable (can be changed), making them unhashable and therefore invalid as keys.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(993,1074,73,'You have a dictionary `world` with existing countries. Write the code to add a new key `''sealand''` with value `0.000027`.',unistr('```python\u000aworld[''sealand''] = 0.000027\u000a```\u000aAssignment to a new key adds the key‑value pair to the dictionary.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(994,1075,73,'Given `world = {''albania'':2.77}`, write the code to change the value of `''albania''` to `2.81`.',unistr('```python\u000aworld[''albania''] = 2.81\u000a```\u000aThe same syntax as adding, but because the key already exists, it updates the existing value rather than adding a new pair.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(995,1076,73,unistr('```python\u000adel(world[''sealand''])\u000a```\u000aWhat does this code do, and what potential error can it cause?'),'It removes the key‑value pair with key `''sealand''` from the dictionary `world`. If `''sealand''` does not exist, it raises a `KeyError`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(996,1076,73,unistr('```python\u000aworld = {''a'':1}\u000adel(world[''b''])\u000a```\u000aWhat error occurs and why?'),'A `KeyError: ''b''` occurs because the key `''b''` does not exist in the dictionary. The `del` statement requires that the key be present.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(997,1077,73,'Given `d = {''a'':1, ''b'':2}`, what is the difference between `''a'' in d` and `1 in d`?','`''a'' in d` returns `True` because `''a''` is a key. `1 in d` returns `False` because `in` checks keys, not values. The value `1` is not a key.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(998,1108,73,'What is a pandas DataFrame, and how does it differ from a 2D NumPy array?','A DataFrame is a 2‑dimensional labeled data structure with columns of potentially different data types (like a spreadsheet). A 2D NumPy array is homogeneous (one data type) and uses only integer indexing, whereas DataFrames have row and column labels.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(999,1108,73,'Compare a pandas Series and a pandas DataFrame.','A Series is a 1‑dimensional labeled array (like a single column). A DataFrame is a 2‑dimensional labeled data structure (like multiple columns). Selecting a single column from a DataFrame returns a Series; selecting multiple columns returns a DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1000,1078,73,unistr('```python\u000abrics = pd.read_csv(''brics.csv'', index_col=0)\u000a```\u000aWhat does this code do, and what does `index_col=0` mean?'),'It reads the CSV file `brics.csv` into a pandas DataFrame. `index_col=0` tells pandas to use the first column of the CSV as the row index (row labels) instead of creating a default integer index.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1001,1109,73,'What is a pandas Series? Provide an example of how one is created from a DataFrame.','A Series is a one‑dimensional labeled array that can hold any data type. Example: `brics[''country'']` returns a Series containing the ''country'' column. Series have an index and methods like `.mean()`, but they are 1D.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1002,1079,73,unistr('```python\u000abrics[''country'']\u000abrics[[''country'']]\u000a```\u000aWhat is the difference in output between these two expressions?'),'`brics[''country'']` returns a pandas Series (1D). `brics[[''country'']]` returns a pandas DataFrame with one column (2D). The double brackets are used to select a subset of columns as a DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1003,1080,73,unistr('```python\u000abrics[1:4]\u000a```\u000aWhat rows does this return if `brics` has default integer index 0,1,2,3,4?'),'It returns rows with index labels 1, 2, and 3 (the second, third, and fourth rows). The slice end index (4) is exclusive, following Python list slicing rules.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1004,1081,73,unistr('```python\u000abrics.loc[1:4]\u000a```\u000aAssuming `brics` has integer index labels that are not in order from 0, why might this cause an error or unexpected result?'),'`loc` is label‑based. If the index labels are not integers (or are integers but not consecutive starting at 0), `1:4` is interpreted as a slice of labels, not positions. This includes labels 1,2,3,4 (if they exist). If label 4 does not exist, it will raise a `KeyError`. For position‑based slicing, u','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1005,1082,73,unistr('```python\u000abrics.iloc[''RU'':''CH'']\u000a```\u000aWhat error will this code produce and why?'),'A `TypeError` because `iloc` requires integer positions, not labels. `iloc` is strictly integer‑position based. To select rows by label, use `loc`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1006,1083,73,'List all six comparison operators in Python and give an example of each.','< (less than), <= (less than or equal), > (greater than), >= (greater than or equal), == (equal), != (not equal). Examples: `2 < 3` → True; `3 <= 3` → True; `2 == 3` → False; `2 != 3` → True.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1007,1084,73,'What is the difference between `and` and `&` when used with NumPy arrays?','`and` is a Python logical operator that cannot be used element‑wise on arrays (it raises `ValueError: The truth value of an array is ambiguous`). `&` is the bitwise AND operator, but when used with boolean arrays it performs element‑wise logical AND. For arrays, you should use `np.logical_and()` or ','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1008,1085,73,unistr('```python\u000anp.logical_and(bmi > 21, bmi < 22)\u000a```\u000aWhat does this code do, and why is it preferred over `bmi > 21 and bmi < 22`?'),'It performs element‑wise logical AND on two boolean arrays, returning a boolean array of the same shape. It is preferred because Python''s `and` does not work element‑wise on arrays and would raise a `ValueError`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1009,1086,73,unistr('```python\u000anp.logical_or(a, b)\u000a```\u000aWhat does this compute, and what are the shape requirements for `a` and `b`?'),'It computes the element‑wise logical OR of two arrays (or an array and a scalar). `a` and `b` must be broadcastable to the same shape. If shapes are incompatible, a `ValueError` is raised.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1010,1087,73,unistr('```python\u000anp.logical_not(arr)\u000a```\u000aWhat does this function return if `arr` is `[True, False, True]`?'),'It returns `[False, True, False]`. `np.logical_not()` applies element‑wise logical NOT (negation) to the input array.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1011,1088,73,unistr('```python\u000ax = 10\u000aif x > 5\u000a    print(''x is greater than 5'')\u000a```\u000aWhat error does this code produce?'),'A `SyntaxError` because the `if` statement is missing a colon (`:`) at the end of the condition line. The correct syntax is `if x > 5:`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1012,1089,73,unistr('```python\u000ax = 5\u000aelse:\u000a    print(''x is not greater than 10'')\u000aif x > 10:\u000a    print(''x is greater than 10'')\u000a```\u000aWhat is wrong with this code?'),'The `else` clause appears before any `if` statement. In Python, `else` must directly follow an `if` (or `elif`) block. This will raise a `SyntaxError`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1013,1090,73,'What is the difference between using `elif` and nesting separate `if` statements?','`elif` chains check conditions sequentially and execute only the block of the first true condition, then skip the rest. Separate `if` statements check each condition independently, potentially executing multiple blocks if more than one condition is true.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1014,1091,73,'Write a condition that checks if a number `z` is even.',unistr('```python\u000az % 2 == 0\u000a```\u000aThe modulo operator `%` returns the remainder. If the remainder when dividing by 2 is 0, the number is even.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1015,1092,73,unistr('```python\u000aimport pandas as pd\u000adf = pd.DataFrame({''A'': [1, 2, 3], ''B'': [4, 5, 6]})\u000abool_series = df[''A''] > 1\u000aprint(df[bool_series])\u000a```\u000aWhat is printed?'),unistr('```\u000a   A  B\u000a1  2  5\u000a2  3  6\u000a```\u000aThe boolean Series `bool_series` is `[False, True, True]`. Using it inside `df[]` selects rows where the Series is `True` (rows 1 and 2).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1016,1092,73,unistr('```python\u000aimport pandas as pd\u000adf = pd.DataFrame({''A'': [1,2,3]}, index=[0,1,2])\u000acondition = [True, False]\u000afiltered = df[condition]\u000a```\u000aWhat happens and why?'),'A `IndexingError` is raised because the length of the boolean list (2) does not match the number of rows in the DataFrame (3). Boolean filters must have the same length as the axis being filtered.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1017,1093,73,unistr('```python\u000aerror = 50\u000awhile error > 1:\u000a    print(error)\u000a```\u000aWhy does this loop run forever?'),'The variable `error` is never updated inside the loop, so it always remains 50. The condition `error > 1` is always `True`, causing an infinite loop. To fix, add an update like `error = error / 4` inside the loop.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1018,1094,73,unistr('```python\u000anumbers = [1,2,3,4,5]\u000afor num in numbers:\u000a    if num % 2 == 0:\u000a        numbers.remove(num)\u000a```\u000aWhat unexpected behavior can occur and why?'),'Modifying a list (removing elements) while iterating over it can cause skipped elements. After removing an element, the list shifts, and the loop index moves to the next position, potentially skipping the element that shifted into the removed element''s position.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1019,1095,73,unistr('```python\u000afor index, value in enumerate([''a'',''b'',''c''], start=1):\u000a    print(index, value)\u000a```\u000aWhat is printed, and what does `enumerate` do?'),unistr('Output:\u000a1 a\u000a2 b\u000a3 c\u000a\u000a`enumerate()` returns an iterator that yields tuples of (index, value) for each element in the iterable. The `start` parameter changes the starting index (default 0).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1020,1097,73,unistr('```python\u000aworld = {''a'':1, ''b'':2}\u000afor k, v in world.items():\u000a    print(k, v)\u000a```\u000aWhat does this code do, and what does `.items()` return?'),'It iterates over the dictionary''s key‑value pairs, printing each key and its corresponding value. `.items()` returns a view object that yields tuples of (key, value) for each entry in the dictionary.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1021,1098,73,unistr('```python\u000aimport numpy as np\u000aarr = np.array([[1,2],[3,4]])\u000afor val in np.nditer(arr):\u000a    print(val)\u000a```\u000aIn what order are the values printed?'),'They are printed in row‑major (C‑style) order: 1, 2, 3, 4. `np.nditer()` iterates over the array elements in memory order, which for NumPy defaults to row‑major.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1022,1110,74,'What is the purpose of the .head() method in pandas?','It returns the first few rows of a DataFrame (default 5 rows) for quick inspection.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1023,1140,74,'Write the standard import statement to use the pandas library.','import pandas as pd','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1024,1141,74,'What is a key structural difference between a DataFrame and a Series?','A DataFrame is a 2‑dimensional labeled table (rows and columns), while a Series is a 1‑dimensional labeled array.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1025,1142,74,'What is a Series in pandas?','A one‑dimensional labeled array that holds data for a single variable, with an index to label each value.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1026,1143,74,'What does ''rectangular data'' mean in pandas?','Data stored in rows (observations) and columns (variables), where all columns have the same length.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1027,1111,74,unistr('What is wrong with this code?\u000a\u000a```python\u000ainfo = df.info()\u000aprint(info.shape)\u000a```'),'`info` is None because `.info()` prints to console and returns None; calling `.shape` on None fails.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1028,1112,74,unistr('Why does this code raise an error?\u000a\u000a```python\u000adf.shape()\u000a```'),'`.shape` is an attribute, not a method; remove the parentheses.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1029,1113,74,unistr('What pandas method is being used?\u000a\u000a```python\u000adf.describe()\u000a```'),'`.describe()` – it generates summary statistics (count, mean, std, min, quartiles, max) for numeric columns.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1030,1116,74,'How would you select the ''weight_kg'' column from a DataFrame `dogs` as a Series?','dogs[''weight_kg'']','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1031,1119,74,unistr('What method is shown?\u000a\u000a```python\u000adf.to_numpy()\u000a```'),'`.to_numpy()` – it converts the DataFrame into a 2‑dimensional NumPy array.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1032,1114,74,'A learner writes `df.columns()`. Why is this wrong?','`.columns` is an attribute, not a method; remove the parentheses.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1033,1115,74,'What is wrong with `df.index = [10,20,30]` when the DataFrame has 5 rows?','The new index list must have the same length as the number of rows (5), otherwise a ValueError occurs.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1034,1120,74,'Write the code to sort the DataFrame `dogs` by the ''weight_kg'' column in descending order, storing the result in the same variable.','dogs = dogs.sort_values(''weight_kg'', ascending=False)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1035,1121,74,unistr('What operation is being performed?\u000a\u000a```python\u000adogs[dogs[''height_cm''] > 50]\u000a```'),'Boolean indexing – filtering rows where the condition is True.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1036,1144,74,'What is a Boolean mask in pandas?','A pandas Series of True/False values used to filter rows of a DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1037,1122,74,unistr('What method is shown?\u000a\u000a```python\u000adogs[dogs[''color''].isin([''Black'', ''Brown''])]\u000a```'),'`.isin()` – it checks whether each value in the Series is contained in the given list.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1038,1123,74,'Write a chain of pandas operations to: filter `dogs` for rows with `bmi < 100`, then sort by `height_cm` descending, and finally select only the columns `name`, `height_cm`, and `bmi`.','dogs[dogs[''bmi''] < 100].sort_values(''height_cm'', ascending=False)[[''name'', ''height_cm'', ''bmi'']]','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1039,1124,74,'Write the code to compute the 30th percentile (quantile 0.3) of the ''weight_kg'' column using a custom function with `.agg()`.',unistr('```python\u000adef pct30(column):\u000a    return column.quantile(0.3)\u000adogs[''weight_kg''].agg(pct30)\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1040,1125,74,unistr('What method is being used?\u000a\u000a```python\u000adogs[''weight_kg''].cumsum()\u000a```'),'`.cumsum()` – it returns a Series of cumulative sums, not a single number.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1041,1126,74,'Write the code to remove duplicate rows from `dogs` based on the ''color'' column, keeping the first occurrence, and assign the result back to `dogs`.','dogs = dogs.drop_duplicates(subset=''color'', keep=''first'')','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1042,1127,74,'What does `.groupby()` do in pandas?','It splits the data into groups based on one or more columns, returning a GroupBy object ready for aggregation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1043,1145,74,'What is the default aggregation function used by `.pivot_table()` if `aggfunc` is not specified?','`mean` (average).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1044,1128,74,'Write the code to set the ''name'' column as the index of the DataFrame `dogs`, making the change permanent (in place).','dogs.set_index(''name'', inplace=True)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1045,1129,74,'Write the code to reset the index of `dogs` to default integers and completely discard the old index.','dogs.reset_index(drop=True, inplace=True)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1046,1130,74,unistr('What indexer is being used?\u000a\u000a```python\u000adogs.loc[''Bella'', ''weight_kg'']\u000a```'),'`.loc[]` – label‑based indexer; here it accesses the row with index ''Bella'' and column ''weight_kg''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1047,1131,74,unistr('What indexer is shown?\u000a\u000a```python\u000adogs.iloc[2:5, 1:4]\u000a```'),'`.iloc[]` – position‑based indexer; it selects rows at positions 2,3,4 and columns at positions 1,2,3.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1048,1136,74,'What is a multi‑level index (hierarchical index) in pandas?','An index with two or more levels, allowing grouping by multiple keys without flattening the data.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1049,1137,74,unistr('What operation does this code perform?\u000a\u000a```python\u000adogs.loc[''2014-08-25'':''2016-09-16'']\u000a``` (assuming the index is datetime)'),'It selects rows with dates between August 25, 2014 and September 16, 2016 inclusive.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1050,1138,74,'A learner expects margins to show sums, but the pivot table was created with `aggfunc=''mean''`. What is the actual margin value?','The margin is the mean of the row/column, not the sum, because margins use the same aggfunc.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1051,1139,74,unistr('What misconception does this code reveal?\u000a\u000a```python\u000asales.pivot_table(..., fill_value=0, margins=True)\u000a```'),'`fill_value` only replaces NaN in the pivot table output; it does not affect the original data or the margin calculations.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1052,1178,75,'Define an inner join in pandas.','An inner join returns only rows with matching key values in both tables. No unmatched rows appear.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1053,1179,75,'What is a one-to-one relationship between two tables?','Every row in the left table relates to exactly one row in the right table, and vice versa. Keys are unique in both tables.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1054,1180,75,'Define a one-to-many relationship between DataFrames.','Every row in the left table relates to one or more rows in the right table. The right key is not unique.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1055,1175,75,'How does a left join differ from an inner join?','Left join keeps all rows from the left table, filling NaN in right columns where no match exists. Inner join drops non‑matching rows.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1056,1176,75,'What is a right join?','A right join returns all rows from the right DataFrame and only matching rows from the left. Unmatched left columns become NaN.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1057,1177,75,'What is an outer join?','An outer join returns all rows from both tables, filling NaN where there is no match. It’s a full union of keys.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1058,1181,75,'Describe a semi join and how to perform it in pandas.','A semi join filters the left table to rows that have a match in the right table, returning only left columns. Use isin() after extracting matching keys.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1059,1182,75,'Explain an anti join and its implementation in pandas.','An anti join returns rows from the left table with no match in the right table. Do a left merge with indicator=True, then filter _merge == ''left_only''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1060,1183,75,'What do NaNs at the start of a column look like after merge_ordered with fill_method=''ffill''?','They remain NaN because there is no previous non‑null value to propagate.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1061,1184,75,'Define wide format data.','Each row represents one subject, and each column contains a different attribute of that subject.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1062,1185,75,'Contrast long format with wide format data.','Long format stores each observation as a separate row, with columns for variable name and value. Wide format puts variables in columns.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1063,1153,75,unistr('What pandas operation is shown?\u000a\u000a```python\u000awards.merge(census, on=''ward'')\u000a```'),'An inner join of wards and census DataFrames on the ''ward'' column.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1064,1153,75,unistr('What type of join is performed by this code?\u000a\u000a```python\u000amovies.merge(taglines, on=''id'', how=''left'')\u000a```'),'A left join, keeping all movies and adding taglines where available.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1065,1154,75,'Write the merge call that renames overlapping columns with ''_ward'' and ''_cen'' suffixes.',unistr('```python\u000awards.merge(census, on=''ward'', suffixes=(''_ward'',''_cen''))\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1066,1155,75,'Write the merge that joins grants and licenses on both ''address'' and ''zip'' columns.',unistr('```python\u000agrants.merge(licenses, on=[''address'',''zip''])\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1067,1156,75,unistr('What does this code accomplish?\u000a\u000a```python\u000agrants.merge(licenses, on=[''address'',''zip'']) \\\u000a     .merge(wards, on=''ward'', suffixes=(''_bus'',''_ward''))\u000a```'),'It chains two merges: first grants with licenses on address/zip, then the result with wards on ''ward''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1068,1157,75,'Movies has column ''id'', tv_genre has ''movie_id''. Write a right join using these mismatched column names.',unistr('```python\u000amovies.merge(tv_genre, how=''right'', left_on=''id'', right_on=''movie_id'')\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1069,1158,75,'Write a self-join on the sequels DataFrame to link each movie to its sequel, using suffixes ''_org'' and ''_seq''.',unistr('```python\u000asequels.merge(sequels, left_on=''sequel'', right_on=''id'', suffixes=(''_org'',''_seq''))\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1070,1159,75,'How do you merge using the index of the left DataFrame when the right key is a column?',unistr('```python\u000amovies.merge(movie_to_genres, left_index=True, right_on=''movie_id'')\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1071,1160,75,'What is required when merging two DataFrames with MultiIndex keys?','Both DataFrames must have the same MultiIndex level names and order for the merge to match correctly.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1072,1161,75,'Write a merge where the left DataFrame uses its index and also specifies a column name for the key, while the right DataFrame uses a column.',unistr('```python\u000amovies.merge(movie_to_genres, left_on=''id'', left_index=True, right_on=''movie_id'')\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1073,1162,75,unistr('What does this line do?\u000a\u000a```python\u000agenres[''gid''].isin(genres_tracks[''gid''])\u000a```'),'Returns a boolean Series indicating whether each gid in genres appears in genres_tracks.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1074,1163,75,'Add an indicator column to a left merge to identify unmatched rows.',unistr('```python\u000agenres.merge(top_tracks, on=''gid'', how=''left'', indicator=True)\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1075,1164,75,'Write a pd.concat call that stacks three DataFrames (inv_jan, inv_feb, inv_mar) vertically and resets the index.',unistr('```python\u000apd.concat([inv_jan, inv_feb, inv_mar], ignore_index=True)\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1076,1164,75,'Concatenate inv_jan and inv_feb vertically, keeping only columns that exist in both.',unistr('```python\u000apd.concat([inv_jan, inv_feb], join=''inner'')\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1077,1165,75,'How do you prevent old indices from being kept when concatenating?','Set ignore_index=True in pd.concat().','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1078,1166,75,unistr('What is wrong with this code?\u000a\u000a```python\u000apd.concat([inv_jan, inv_feb], ignore_index=True, keys=[''jan'',''feb''])\u000a```'),'Keys and ignore_index cannot be used together; a ValueError will be raised.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1079,1167,75,'inv_jan has columns A,B,C; inv_feb has columns B,C,D. What columns appear after pd.concat([inv_jan, inv_feb], join=''inner'')?','Only columns B and C (the intersection).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1080,1168,75,unistr('Why does this merge raise a MergeError?\u000a\u000a```python\u000atracks.merge(specs, on=''tid'', validate=''one_to_one'')\u000a```\u000aspecs contains duplicate ''tid'' values.'),'validate=''one_to_one'' checks that the key is unique in both DataFrames. Duplicate keys in specs violate this, causing a MergeError.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1081,1169,75,'What error will occur if you run pd.concat([df1, df2], verify_integrity=True) and both DataFrames contain an index value 5?','A ValueError because the resulting index would have duplicate value 5.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1082,1170,75,'What does pd.merge_ordered(aapl, mcd, on=''date'', suffixes=(''_aapl'',''_mcd'')) do?','An ordered, outer join of aapl and mcd on ''date'', sorting the result by date.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1083,1171,75,unistr('What type of merge does this code perform?\u000a\u000a```python\u000apd.merge_asof(visa, ibm, on=''date_time'', suffixes=(''_visa'',''_ibm''))\u000a```'),'An asof (ordered left) join that matches the nearest previous key in ibm for each visa time.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1084,1171,75,'Which parameter in merge_asof prevents data leakage by matching to the last known value?','direction=''backward'' (the default).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1085,1172,75,'Write the merge_asof call that matches each visa time to the nearest future ibm time.',unistr('```python\u000apd.merge_asof(visa, ibm, on=''date_time'', suffixes=(''_visa'',''_ibm''), direction=''forward'')\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1086,1173,75,unistr('What does this code return?\u000a\u000a```python\u000astocks.query(''nike >= 90'')\u000a```'),'Rows of the stocks DataFrame where the ''nike'' column value is at least 90.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1087,1174,75,unistr('What transformation does this code apply?\u000a\u000a```python\u000asocial_fin.melt(id_vars=[''financial'',''company''], value_vars=[''2018'',''2017''], var_name=''year'', value_name=''dollars'')\u000a```'),'It unpivots the wide data, turning columns ''2018'' and ''2017'' into rows with a ''year'' column and a ''dollars'' value column.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1088,1209,79,'What are built-in functions in Python?','Pre-defined functions like str(), print(), and sum() that are available for immediate use without importing or defining.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1089,1186,79,unistr('Identify the error in this code:\u000a\u000a```python\u000adef greet()\u000a    print("Hello")\u000a```'),'Missing colon after def greet()','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1090,1187,79,unistr('What concept is demonstrated by the following code?\u000a\u000a```python\u000adef square(value):\u000a    new_value = value ** 2\u000a    print(new_value)\u000a```'),'Function parameter. ''value'' is a parameter that allows data to be passed into the function when called.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1091,1188,79,unistr('What is printed when this code runs?\u000a\u000a```python\u000adef add(a, b):\u000a    return a + b\u000a    print("Done")\u000aadd(2, 3)\u000a```'),'Nothing is printed. The return statement exits the function before print("Done") is reached, and the returned value is not captured.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1092,1189,79,unistr('Find the mistake in the following function:\u000a\u000a```python\u000adef square(value):\u000a"""Return the square."""\u000a    new_value = value ** 2\u000a    return new_value\u000a```'),'The docstring is not indented; it must be at the same indentation level as the function body.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1093,1190,79,'Write the first line of a function named raise_to_power that accepts two parameters: value1 and value2.',unistr('```python\u000adef raise_to_power(value1, value2):\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1094,1191,79,unistr('What is wrong with this code?\u000a\u000a```python\u000at = (5)\u000at[0] = 6\u000a```'),'t is an integer, not a tuple. A single-element tuple requires a trailing comma: (5,). Attempting t[0] on an int raises TypeError.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1095,1192,79,unistr('What error will this code produce?\u000a\u000a```python\u000aeven_nums = (2, 4, 6)\u000aa, b, c, d = even_nums\u000a```'),'ValueError: not enough values to unpack (expected 4, got 3)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1096,1193,79,'Given even_nums = (2, 4, 6), write code to assign the second element to a variable named second_num.',unistr('```python\u000asecond_num = even_nums[1]\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1097,1194,79,unistr('What will be printed?\u000a\u000a```python\u000adef raise_both(value1, value2):\u000a    new_value1 = value1 ** value2\u000a    new_value2 = value2 ** value1\u000a    new_tuple = (new_value1, new_value2)\u000a    return new_tuple\u000aprint(raise_both(2, 3))\u000a```'),'(8, 9)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1098,1210,79,'What is the global scope in Python?','The outermost scope where names defined at the top level of a script or module are accessible throughout the entire program.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1099,1210,79,'How does local scope differ from global scope?','Local scope exists within a function; variables defined there are only accessible inside that function, while global variables are accessible throughout the file.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1100,1195,79,unistr('What happens when this code runs?\u000a\u000a```python\u000adef square(value):\u000a    new_val = value ** 2\u000a    return new_val\u000asquare(3)\u000aprint(new_val)\u000a```'),'NameError: name ''new_val'' is not defined','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1101,1196,79,unistr('What is printed?\u000a\u000a```python\u000anew_val = 10\u000adef square(value):\u000a    new_val = value ** 2\u000a    return new_val\u000aprint(square(3))\u000aprint(new_val)\u000a```'),unistr('9\u000a10'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1102,1211,79,unistr('What does this code demonstrate?\u000a\u000a```python\u000anew_val = 10\u000adef square(value):\u000a    new_value2 = new_val ** 2\u000a    return new_value2\u000aprint(square(3))\u000a```'),'Accessing a global variable inside a function without the global keyword (for reading only).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1103,1197,79,unistr('Identify the error in this code:\u000a\u000a```python\u000acount = 0\u000adef increment():\u000a    count = count + 1\u000a    return count\u000aprint(increment())\u000a```'),'UnboundLocalError: local variable ''count'' referenced before assignment. The assignment inside creates a local variable, but the right-hand side tries to use it before it has a value.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1104,1198,79,'What is a nested function?','A function defined inside another function. It can access variables from the enclosing function’s scope.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1105,1199,79,unistr('What is printed?\u000a\u000a```python\u000adef raise_val(n):\u000a    def inner(x):\u000a        return x ** n\u000a    return inner\u000asquare = raise_val(2)\u000acube = raise_val(3)\u000aprint(square(2), cube(4))\u000a```'),'4 64','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1106,1212,79,'What does the LEGB rule describe?','The order Python searches for names: Local, Enclosing, Global, Built-in.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1107,1212,79,'How does the enclosing scope differ from the global scope?','Enclosing scope is the scope of any outer function containing a nested function, while global scope is the top-level module scope.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1108,1201,79,unistr('What is the subtle bug in this function?\u000a\u000a```python\u000adef append_to(element, target=[]):\u000a    target.append(element)\u000a    return target\u000a```'),'The default argument [] is evaluated only once at definition, so all calls share the same list. Subsequent calls will append to the same list, leading to unexpected accumulation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1109,1202,79,unistr('What does the *args parameter do?\u000a\u000a```python\u000adef add_all(*args):\u000a    sum_all = 0\u000a    for num in args:\u000a        sum_all += num\u000a    return sum_all\u000a```'),'Collects an arbitrary number of positional arguments into a tuple named args.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1110,1203,79,unistr('What does **kwargs do in this function?\u000a\u000a```python\u000adef print_all(**kwargs):\u000a    for key, value in kwargs.items():\u000a        print(key + ": " + value)\u000a```'),'Collects arbitrary keyword arguments into a dictionary named kwargs, where keys are parameter names and values are the arguments.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1111,1204,79,unistr('What is the following?\u000a\u000a```python\u000alambda x, y: x ** y\u000a```'),'An anonymous lambda function that returns x raised to the power y.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1112,1205,79,unistr('What will be printed?\u000a\u000a```python\u000anums = [48, 6, 9, 21, 1]\u000asquare_all = map(lambda num: num ** 2, nums)\u000aprint(square_all)\u000a```'),'<map object at 0x...> (a map iterator, not a list)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1113,1206,79,unistr('What does this code do?\u000a\u000a```python\u000atry:\u000a    return x ** 0.5\u000aexcept:\u000a    print(''x must be an int or float'')\u000a```'),'It attempts to compute the square root; if any exception occurs, it prints an error message instead of crashing.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1114,1207,79,unistr('Write the code to catch only a TypeError in the following function:\u000a\u000a```python\u000adef sqrt(x):\u000a    try:\u000a        return x ** 0.5\u000a    # your code here\u000a```'),unistr('```python\u000aexcept TypeError:\u000a    print(''x must be an int or float'')\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1115,1208,79,unistr('What does this code do?\u000a\u000a```python\u000adef sqrt(x):\u000a    if x < 0:\u000a        raise ValueError(''x must be non-negative'')\u000a    return x ** 0.5\u000a```'),'It explicitly raises a ValueError with a message if x is negative, preventing an invalid square root calculation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1116,1200,79,unistr('Identify the error in this code:\u000a\u000a```python\u000adef outer():\u000a    n = 1\u000a    def inner():\u000a        n = 2\u000a    inner()\u000a    print(n)\u000aouter()\u000a```'),'The assignment n = 2 inside inner creates a local variable, so outer prints 1. To modify the enclosing n, you need nonlocal n inside inner.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1117,1213,80,unistr('Concept: **for loop**\u000a\u000aComplete the for loop that prints each employee name from the list `employees`.\u000a\u000a```python\u000aemployees = [''Nick'', ''Lore'', ''Hugo'']\u000a_____ employee in employees:\u000a    print(employee)\u000a```'),unistr('Answer: `for`\u000a\u000aThe `for` loop iterates over the `employees` list, assigning each name to the variable `employee` and then executing the indented `print()`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1118,1214,80,unistr('Concept: **Modulo operator (%)**\u000a\u000aComplete the condition that checks if `num` is even.\u000a\u000a```python\u000aif num _____ 2 == 0:\u000a    print(''even'')\u000a```'),unistr('Answer: `%`\u000a\u000aThe modulo operator `%` returns the remainder of the division. If the remainder is 0, the number is even.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1119,1215,80,unistr('Concept: **iter() function**\u000a\u000aCreate an iterator from the string `''Data''` using the correct built-in function.\u000a\u000a```python\u000aword = ''Data''\u000ait = _____(word)\u000a```'),unistr('Answer: `iter`\u000a\u000aThe `iter()` built‑in converts an iterable (like a string) into an iterator, enabling manual traversal with `next()`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1120,1216,80,unistr('Concept: **next() function**\u000a\u000aUse the correct function to retrieve the next element from the iterator `it`.\u000a\u000a```python\u000ait = iter([1, 2, 3])\u000aprint(_____(it))\u000a```'),unistr('Answer: `next`\u000a\u000a`next(it)` returns the next available value from the iterator. After this call, `it` is advanced by one position.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1121,1217,80,unistr('Concept: **enumerate() function**\u000a\u000aUse `enumerate()` to loop over `avengers` with a numeric index.\u000a\u000a```python\u000aavengers = [''hawkeye'', ''iron man'']\u000afor index, value in _____(avengers):\u000a    print(index, value)\u000a```'),unistr('Answer: `enumerate`\u000a\u000a`enumerate(avengers)` returns an enumerate object that yields `(0, ''hawkeye'')`, `(1, ''iron man'')`, etc., which can be unpacked in the loop.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1122,1217,80,unistr('Concept: **enumerate() function**\u000a\u000aComplete the `enumerate()` call to start indexing at 10 instead of 0.\u000a\u000a```python\u000aavengers = [''hawkeye'', ''iron man'']\u000afor index, value in enumerate(avengers, _____=10):\u000a    print(index, value)\u000a```'),unistr('Answer: `start`\u000a\u000a`enumerate(avengers, start=10)` sets the first index to 10, so the first pair is (10, ''hawkeye'').'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1123,1218,80,unistr('Concept: **zip() function**\u000a\u000aCombine the two lists `avengers` and `names` pair‑wise using the correct function.\u000a\u000a```python\u000aavengers = [''hawkeye'', ''iron man'']\u000anames = [''barton'', ''stark'']\u000az = _____(avengers, names)\u000a```'),unistr('Answer: `zip`\u000a\u000a`zip(avengers, names)` pairs the first elements, then the second, and so on, returning an iterator of tuples.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1124,1219,80,unistr('Concept: **Unpacking with zip() in for loop**\u000a\u000aWrite the for loop header that unpacks each tuple from `zip(avengers, names)` into `z1` and `z2`.\u000a\u000a```python\u000aavengers = [''hawkeye'', ''iron man'']\u000anames = [''barton'', ''stark'']\u000a_____ z1, z2 in zip(avengers, names):\u000a    print(z1, z2)\u000a```'),unistr('Answer: `for`\u000a\u000aThe syntax `for z1, z2 in zip(...):` iterates over the zip object and automatically unpacks each two‑element tuple into the loop variables.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1125,1220,80,unistr('Concept: **pandas read_csv() chunksize parameter**\u000a\u000aSet the parameter that reads `data.csv` in chunks of 1000 rows.\u000a\u000a```python\u000aimport pandas as pd\u000areader = pd.read_csv(''data.csv'', _____=1000)\u000a```'),unistr('Answer: `chunksize`\u000a\u000a`pd.read_csv(''data.csv'', chunksize=1000)` returns a `TextFileReader` object that iterates over the file in chunks of 1000 rows each.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1126,1220,80,unistr('Concept: **pandas read_csv() chunksize parameter**\u000a\u000aComplete the loop that accumulates the sum of column ''x'' from all chunks. Use the correct operator to add to the total.\u000a\u000a```python\u000aimport pandas as pd\u000atotal = 0\u000afor chunk in pd.read_csv(''data.csv'', chunksize=1000):\u000a    total _____ sum(chunk[''x''])\u000aprint(total)\u000a```'),unistr('Answer: `+=`\u000a\u000aAugmented assignment `+=` adds the right‑hand value to the variable. Using `=` would lose all previous sums.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1127,1221,80,unistr('Concept: **List comprehension**\u000a\u000aBuild a new list `new_nums` by adding 1 to each number in `nums`. Complete the output expression.\u000a\u000a```python\u000anums = [12, 8, 21]\u000anew_nums = [_____ for num in nums]\u000a```'),unistr('Answer: `num + 1`\u000a\u000aIn the list comprehension `[num + 1 for num in nums]`, `num + 1` is evaluated for each element in `nums`, producing the transformed list.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1128,1222,80,unistr('Concept: **For loop vs list comprehension**\u000a\u000aConvert this for loop into a list comprehension that squares each number in `nums`.\u000a\u000a```python\u000a# For loop version\u000anew_nums = []\u000afor num in nums:\u000a    new_nums.append(num**2)\u000a\u000a# List comprehension (one line)\u000anew_nums = [_____ for num in nums]\u000a```'),unistr('Answer: `num**2`\u000a\u000aThe list comprehension equivalent is `[num**2 for num in nums]`. It compactly generates the same list as the explicit loop.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1129,1223,80,unistr('Concept: **List comprehension with range()**\u000a\u000aGenerate a list of the squares of numbers 0 through 4 using a comprehension with `range()`.\u000a\u000a```python\u000asquares = [i**2 for i in _____(5)]\u000a```'),unistr('Answer: `range`\u000a\u000a`range(5)` returns an iterable that yields 0,1,2,3,4. The comprehension computes `i**2` for each.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1130,1224,80,unistr('Concept: **Nested list comprehension**\u000a\u000aComplete the nested list comprehension that generates all pairs `(i, j)` for `i` in 0..1 and `j` in 6..7.\u000a\u000a```python\u000apairs = [(num1, num2) for num1 in range(0, 2) _____ for num2 in range(6, 8)]\u000a```'),unistr('Answer: `for num2 in range(6, 8)`\u000a\u000aA nested comprehension is written as `(expr for outer for inner)`. The leftmost `for` is the outer loop; the next is the inner.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1131,1225,80,unistr('Concept: **Conditional in list comprehension (filtering)**\u000a\u000aFilter the list comprehension to keep only even numbers, then double them.\u000a\u000a```python\u000aresult = [num * 2 for num in range(10) _____ num % 2 == 0]\u000a```'),unistr('Answer: `if`\u000a\u000aIn `[num * 2 for num in range(10) if num % 2 == 0]`, the `if` filters the iterable so only even numbers are processed.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1132,1226,80,unistr('Concept: **Conditional in list comprehension (output expression)**\u000a\u000aUse a ternary expression to output the square if `num` is even, otherwise output 0.\u000a\u000a```python\u000aresult = [num ** 2 if num % 2 == 0 _____ 0 for num in range(5)]\u000a```'),unistr('Answer: `else`\u000a\u000aThe conditional expression `num ** 2 if num % 2 == 0 else 0` returns `num**2` for evens and `0` for odds.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1133,1227,80,unistr('Concept: **Dictionary comprehension**\u000a\u000aCreate a dictionary mapping each number to its negative. Use a dictionary comprehension.\u000a\u000a```python\u000apos_neg = {num: _____ for num in range(5)}\u000a```'),unistr('Answer: `-num`\u000a\u000aThe dictionary comprehension `{num: -num for num in range(5)}` yields `{0:0, 1:-1, 2:-2, ...}`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1134,1228,80,unistr('Concept: **Generator expression**\u000a\u000aCreate a generator that yields doubled numbers from 0..9. Use parentheses, not square brackets.\u000a\u000a```python\u000agen = (_____ for num in range(10))\u000a```'),unistr('Answer: `num * 2`\u000a\u000a`gen = (2 * num for num in range(10))` creates a generator object that computes each doubled value on demand.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1135,1229,80,unistr('Concept: **Conditionals in generator expressions**\u000a\u000aFilter the generator to yield only even numbers from 0..9.\u000a\u000a```python\u000aeven_gen = (num for num in range(10) _____ num % 2 == 0)\u000a```'),unistr('Answer: `if`\u000a\u000aThe generator expression `(num for num in range(10) if num % 2 == 0)` yields only even numbers.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1136,1230,80,unistr('Concept: **Generator function**\u000a\u000aComplete the generator function that yields numbers from 0 up to `n-1`. Use the correct keyword to produce each value.\u000a\u000a```python\u000adef num_sequence(n):\u000a    i = 0\u000a    while i < n:\u000a        _____ i\u000a        i += 1\u000a```'),unistr('Answer: `yield`\u000a\u000a`yield i` makes the function a generator. Each `next()` call resumes after the yield and continues the loop.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1137,1231,80,unistr('Concept: **yield keyword**\u000a\u000aModify this regular function to become a generator that returns each line of a file. Replace the wrong keyword.\u000a\u000a```python\u000adef read_lines(filename):\u000a    with open(filename) as f:\u000a        for line in f:\u000a            _____ line\u000a```'),unistr('Answer: `yield`\u000a\u000aUsing `yield` makes the function a generator that lazily reads and returns lines. The file stays open as long as the generator is alive.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1138,1232,80,unistr('Concept: **User-defined function syntax**\u000a\u000aFix the function definition by adding the missing punctuation after the parameters.\u000a\u000a```python\u000adef raise_both(value1, value2)_____\u000a    new_value1 = value1 ** value2\u000a    new_value2 = value2 ** value1\u000a    return (new_value1, new_value2)\u000a```'),unistr('Answer: `:`\u000a\u000aThe correct syntax is `def raise_both(value1, value2):` with a colon. Without it, Python raises a SyntaxError.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1139,1233,80,unistr('Concept: **Splat operator (*) for iterators**\u000a\u000aUnpack all remaining elements of the iterator `it` into the `print()` call using the correct operator.\u000a\u000a```python\u000aword = ''Data''\u000ait = iter(word)\u000aprint(_____it)\u000a```'),unistr('Answer: `*`\u000a\u000a`print(*it)` passes each character ''D'',''a'',''t'',''a'' as a separate argument to print, which outputs them space‑separated.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1140,1218,80,unistr('Concept: **zip() function**\u000a\u000aConvert the zip object to a list so you can print all pairs. Fill in the missing function.\u000a\u000a```python\u000aavengers = [''hawkeye'', ''iron man'']\u000anames = [''barton'', ''stark'']\u000az = zip(avengers, names)\u000az_list = _____(z)\u000aprint(z_list)\u000a```'),unistr('Answer: `list`\u000a\u000a`list(z)` consumes the zip iterator and stores all its tuples in a list, which can be printed and reused.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1141,1219,80,unistr('Concept: **Unpacking with zip() in for loop**\u000a\u000aComplete the for loop header to unpack each zip tuple into `avenger` and `name`.\u000a\u000a```python\u000aavengers = [''hawkeye'', ''iron man'']\u000anames = [''barton'', ''stark'']\u000afor _____, _____ in zip(avengers, names):\u000a    print(avenger, name)\u000a```'),unistr('Answer: `avenger`, `name`\u000a\u000aThe unpacking `for avenger, name in zip(...):` assigns each first element to `avenger` and each second to `name`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1142,1220,80,unistr('Concept: **pandas read_csv() chunksize parameter**\u000a\u000aThe code below is supposed to count total rows across all chunks but contains a bug. Fill in the correct operator to accumulate the count.\u000a\u000a```python\u000aimport pandas as pd\u000atotal_rows = 0\u000afor chunk in pd.read_csv(''data.csv'', chunksize=1000):\u000a    total_rows _____ len(chunk)\u000aprint(total_rows)\u000a```'),unistr('Answer: `+=`\u000a\u000aAugmented assignment `+=` is essential for aggregation loops. Without it, the variable is replaced each iteration.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1143,1221,80,unistr('Concept: **List comprehension**\u000a\u000aFill in the missing keyword that makes this a valid list comprehension.\u000a\u000a```python\u000anew_nums = [num + 1 _____ num in nums]\u000a```'),unistr('Answer: `for`\u000a\u000aThe correct list comprehension syntax is `[output for variable in iterable]`. The missing keyword is `for`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1144,1222,80,unistr('Concept: **For loop vs list comprehension**\u000a\u000aRewrite this loop as a list comprehension that creates `cubes`. Fill in the expression.\u000a\u000a```python\u000a# Loop\u000acubes = []\u000afor x in nums:\u000a    cubes.append(x**3)\u000a\u000a# Comprehension\u000acubes = [_____ for x in nums]\u000a```'),unistr('Answer: `x**3`\u000a\u000aA list comprehension directly embeds the transformation. `[x**3 for x in nums]` produces the same list of cubes.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1145,1224,80,unistr('Concept: **Nested list comprehension**\u000a\u000aComplete the nested comprehension to create `(i, j)` pairs for `i` in 0..1 and `j` in 0..2. Place the inner `for` clause.\u000a\u000a```python\u000apairs = [(i, j) for i in range(2) _____]\u000a```'),unistr('Answer: `for j in range(3)`\u000a\u000aThe full comprehension is `[(i, j) for i in range(2) for j in range(3)]`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1146,1224,80,unistr('Concept: **Nested list comprehension**\u000a\u000aThe following nested comprehension is written incorrectly. Swap the order of the `for` clauses so that the result is `[(0,6), (0,7), (1,6), (1,7)]`. Fill the entire corrected comprehension line.\u000a\u000a```python\u000a# Incorrect order:\u000apairs = [(num1, num2) for num2 in range(6, 8) for num1 in range(0, 2)]\u000a# Correct order:\u000apairs = [(num1, num2) for num1 in range(0, 2) _____]\u000a```'),unistr('Answer: `for num2 in range(6, 8)`\u000a\u000aThe order of `for` clauses dictates the nesting. The correct order places `for num1` (outer) before `for num2` (inner).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1147,1225,80,unistr('Concept: **Conditional in list comprehension (filtering)**\u000a\u000aAdd the filter condition so that only numbers greater than 5 are included from `range(1, 10)`.\u000a\u000a```python\u000afiltered = [n for n in range(1, 10) _____ n > 5]\u000a```'),unistr('Answer: `if`\u000a\u000aThe comprehension `[n for n in range(1, 10) if n > 5]` yields `[6, 7, 8, 9]`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1148,1225,80,unistr('Concept: **Conditional in list comprehension (filtering)**\u000a\u000aFix the misplaced `if` clause: the following comprehension should keep only odd numbers. Move the `if` to the correct location.\u000a\u000a```python\u000a# Incorrect\u000aodd = [n if n % 2 == 1 for n in range(10)]\u000a# Correct\u000aodd = [n for n in range(10) _____ n % 2 == 1]\u000a```'),unistr('Answer: `if`\u000a\u000aA filter `if` must follow the `for` clause: `[expr for var in iterable if condition]`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1149,1226,80,unistr('Concept: **Conditional in list comprehension (output expression)**\u000a\u000aInsert the missing `else` part to handle numbers that are not even.\u000a\u000a```python\u000aresult = [num ** 2 if num % 2 == 0 else _____ for num in range(5)]\u000a```'),unistr('Answer: `0`\u000a\u000aThe ternary `num ** 2 if num % 2 == 0 else 0` yields squares for evens and 0 for odds, matching `[0, 0, 4, 0, 16]`.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1150,1226,80,unistr('Concept: **Conditional in list comprehension (output expression)**\u000a\u000aProvide the complete ternary expression that outputs `num` if positive, else `-num`. The blank is the entire output part before `for`.\u000a\u000a```python\u000aabs_values = [_____ for num in [-2, 3, -1, 4]]\u000a```'),unistr('Answer: `num if num > 0 else -num`\u000a\u000aThe correct expression `num if num > 0 else -num` returns the absolute value of the number.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1151,1227,80,unistr('Concept: **Dictionary comprehension**\u000a\u000aComplete the dictionary comprehension that maps each number to its square. Use the correct key:value separator.\u000a\u000a```python\u000asquares = {num_____ num**2 for num in range(5)}\u000a```'),unistr('Answer: `:`\u000a\u000aThe dict comprehension `{num: num**2 for num in range(5)}` builds a mapping from each number to its square.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1152,1228,80,unistr('Concept: **Generator expression**\u000a\u000aYou have a generator `g`. To compute the sum of its values, which function should you use without converting to a list first?\u000a\u000a```python\u000ag = (x for x in range(1000))\u000atotal = _____(g)\u000a```'),unistr('Answer: `sum`\u000a\u000a`sum()` consumes the generator lazily, computing the total without storing all elements in memory.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1153,1228,80,unistr('Concept: **Generator expression**\u000a\u000aPrint the values of the generator `g` by converting it to a list inside `print()`. Fill the missing function.\u000a\u000a```python\u000ag = (num for num in range(5))\u000aprint(_____(g))\u000a```'),unistr('Answer: `list`\u000a\u000a`list(g)` consumes the generator and returns a list of its elements, which is then printed.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1154,1229,80,unistr('Concept: **Conditionals in generator expressions**\u000a\u000aCreate a generator that yields numbers from `range(20)` that are divisible by 3. Fill the filter condition.\u000a\u000a```python\u000adiv3 = (n for n in range(20) _____ n % 3 == 0)\u000a```'),unistr('Answer: `if`\u000a\u000aThe generator `(n for n in range(20) if n % 3 == 0)` yields 0,3,6,9,12,15,18.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1155,1230,80,unistr('Concept: **Generator function**\u000a\u000aDefine a generator function that yields the Fibonacci sequence up to a limit. Replace the keyword that returns all values at once with the correct keyword to yield each value individually.\u000a\u000a```python\u000adef fibonacci(limit):\u000a    a, b = 0, 1\u000a    while a < limit:\u000a        _____ a\u000a        a, b = b, a + b\u000a```'),unistr('Answer: `yield`\u000a\u000aUsing `yield` makes the function a generator. Each iteration of a loop will yield the next Fibonacci number.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1156,1231,80,unistr('Concept: **yield keyword**\u000a\u000aThe following function should be a generator that yields two values then stops. Replace the incorrect keyword that ends the function prematurely.\u000a\u000a```python\u000adef two_values():\u000a    yield 1\u000a    _____ 2\u000a```'),unistr('Answer: `yield`\u000a\u000a`yield 2` yields the second value and pauses. Since there’s no further code, the generator then exits normally.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1157,1240,84,'open()','The built‑in function that opens a file, returning a file object. Requires the file path and an optional mode string (default ''r'' for reading).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1158,1240,84,unistr('```python\u000afile = open(''data.txt'', ''r'')\u000a```'),'open() — opens the file ''data.txt'' in read mode and returns a file object.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1159,1241,84,'file.read()','A file object method that reads the entire contents of the file as a single string.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1160,1242,84,'file.close()','A file method that closes the file, releasing any system resources allocated to it.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1161,1243,84,'with statement (context manager)','A Python construct that ensures a resource (like a file) is automatically closed when the block exits, even if an error occurs.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1162,1243,84,unistr('```python\u000awith open(''huck_finn.txt'', ''r'') as file:\u000a    print(file.read())\u000a```'),'with statement — opens ''huck_finn.txt'', prints its contents, and automatically closes it after the block.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1163,1276,84,'Flat file','A plain‑text file that stores tabular data as rows and columns without any relationships between multiple tables. Examples: CSV, TSV.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1164,1277,84,'Header (in a flat file)','The first row of a flat file that describes the names of the columns, such as ''Name, Age, Height''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1165,1278,84,'Delimiter','The character used to separate fields within each row of a flat file, commonly a comma (,) or tab (\t).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1166,1279,84,'CSV (Comma‑Separated Values)','A flat‑file format where fields are separated by commas and rows by newlines. Despite the name, other delimiters may also be used.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1167,1244,84,'NumPy','A core Python library for numerical computing, providing the ndarray data structure and efficient array operations. Imported as `import numpy as np`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1168,1250,84,unistr('```python\u000aimport numpy as np\u000adata = np.loadtxt(''MNIST.txt'', delimiter='','')\u000a```'),'numpy.loadtxt() — loads numerical data from a text file into a NumPy array, with options for delimiter, skiprows, usecols, and dtype.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1169,1280,84,unistr('```python\u000aimport numpy as np\u000adata = np.genfromtxt(''messy_data.csv'', delimiter='','', filling_values=0)\u000a```'),'numpy.genfromtxt() — a more flexible loader than loadtxt, handling missing values and mixed types.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1170,1281,84,'Mixed datatypes (in a flat file)','When columns contain different data types (e.g., strings and floats), making it difficult for homogeneous array libraries like NumPy to import without losing type information.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1171,1245,84,'pandas','A Python library for data manipulation and analysis, providing labeled, table‑like data structures. Imported as `import pandas as pd`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1172,1282,84,'DataFrame','A two‑dimensional, labeled data structure in pandas with rows (observations) and columns (variables) that can hold different data types per column.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1173,1251,84,unistr('```python\u000aimport pandas as pd\u000adata = pd.read_csv(''winequality-red.csv'')\u000adata.head()\u000a```'),'pandas.read_csv() — reads a CSV file into a DataFrame, automatically handling headers and datatypes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1174,1246,84,unistr('```python\u000adata.head()\u000a```'),'DataFrame.head() — returns the first 5 rows of the DataFrame by default (or a specified number).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1175,1252,84,unistr('```python\u000aarray = df.to_numpy()\u000a```'),'DataFrame.to_numpy() — converts the DataFrame into a NumPy array.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1176,1283,84,'Pickle (serialization)','The process of converting a Python object into a binary byte stream (pickling) so it can be saved to disk and later restored (unpickled).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1177,1273,84,unistr('```python\u000aimport pickle\u000awith open(''pickled_fruit.pkl'', ''rb'') as file:\u000a    data = pickle.load(file)\u000aprint(data)\u000a```'),'pickle.load() — reads a pickled object from a binary file and reconstructs the original Python object.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1178,1284,84,'Excel files (.xlsx / .xls)','Spreadsheet files that can contain multiple sheets of tabular data, readable in pandas via `pd.ExcelFile` or `pd.read_excel()`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1179,1253,84,unistr('```python\u000aimport pandas as pd\u000axls = pd.ExcelFile(''urbanpop.xlsx'')\u000a```'),'pandas.ExcelFile — a class that encapsulates an Excel workbook, providing access to sheet names and parsing methods.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1180,1247,84,unistr('```python\u000aprint(xls.sheet_names)\u000a```'),'ExcelFile.sheet_names — an attribute that returns a list of sheet names in the workbook.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1181,1254,84,unistr('```python\u000adf1 = xls.parse(''1960-1966'')  # by sheet name\u000adf2 = xls.parse(0)            # by sheet index\u000a```'),'ExcelFile.parse() — reads a specific sheet (by name or zero‑based index) and returns a DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1182,1285,84,'SAS files (.sas7bdat)','Native dataset files from the SAS statistical software system, typically read in Python using the `sas7bdat` library.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1183,1255,84,unistr('```python\u000afrom sas7bdat import SAS7BDAT\u000awith SAS7BDAT(''urbanpop.sas7bdat'') as file:\u000a    df = file.to_data_frame()\u000a```'),'sas7bdat.SAS7BDAT — the class for reading SAS dataset files. It can be used as a context manager.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1184,1256,84,unistr('```python\u000adf_sas = file.to_data_frame()\u000a```'),'SAS7BDAT.to_data_frame() — converts the SAS dataset into a pandas DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1185,1257,84,unistr('```python\u000aimport pandas as pd\u000adata = pd.read_stata(''urbanpop.dta'')\u000a```'),'pandas.read_stata() — reads a Stata .dta file directly into a pandas DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1186,1258,84,unistr('```python\u000aimport h5py\u000a```'),'h5py — the Python library for interacting with HDF5 files, providing a dictionary‑like interface to explore groups and datasets.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1187,1259,84,unistr('```python\u000aimport h5py\u000adata = h5py.File(''H-H1_LOSC_4_V1-815411200-4096.hdf5'', ''r'')\u000a```'),'h5py.File() — opens an existing HDF5 file for reading (mode ''r'') and returns a file‑like object.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1188,1260,84,unistr('```python\u000afor key in data.keys():\u000a    print(key)\u000a```'),'h5py group keys — the `.keys()` method returns an iterator over the names of the items (groups or datasets) inside an HDF5 file or group.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1189,1261,84,unistr('```python\u000aimport scipy.io\u000amat = scipy.io.loadmat(''workspace.mat'')\u000aprint(type(mat))\u000aprint(type(mat[''x'']))\u000a```'),'scipy.io.loadmat() — loads a MATLAB .mat file into a Python dictionary, where keys are variable names and values are NumPy arrays.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1190,1286,84,'Relational database','A database organized into multiple tables of rows and columns, where relationships between tables are expressed via primary and foreign keys, and data is queried using SQL.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1191,1287,84,'Table (in a relational database)','A collection of related data organized into rows (records) and columns (attributes). Each table typically represents one entity type.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1192,1248,84,unistr('```sql\u000aSELECT * FROM Orders\u000a```'),'SELECT * FROM — the basic SQL query that returns all columns of every row from the specified table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1193,1249,84,'SQLAlchemy','A Python SQL toolkit and Object Relational Mapper (ORM) that provides a unified API to work with various relational databases (SQLite, PostgreSQL, etc.).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1194,1262,84,unistr('```python\u000afrom sqlalchemy import create_engine\u000aengine = create_engine(''sqlite:///Northwind.sqlite'')\u000a```'),'create_engine() — creates a database engine that manages connections to the specified database, using a URL‑style connection string.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1195,1263,84,unistr('```python\u000atable_names = engine.table_names()\u000aprint(table_names)\u000a```'),'engine.table_names() — returns a list of all table names in the connected database.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1196,1264,84,unistr('```python\u000acon = engine.connect()\u000a```'),'engine.connect() — returns a connection object, which can be used to execute SQL statements.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1197,1265,84,unistr('```python\u000ars = con.execute("SELECT * FROM Orders")\u000a```'),'connection.execute() — executes a SQL query and returns a ResultProxy object containing the results.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1198,1266,84,unistr('```python\u000arows = rs.fetchall()\u000a```'),'ResultProxy.fetchall() — fetches all remaining rows from the result set and returns them as a list of tuples.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1199,1267,84,unistr('```python\u000adf = pd.DataFrame(rs.fetchmany(size=5))\u000a```'),'ResultProxy.fetchmany() — fetches up to `size` rows from the result set, useful for batch processing.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1200,1268,84,unistr('```python\u000adf.columns = rs.keys()\u000a```'),'ResultProxy.keys() — returns the column names of the query result, which can be used to set DataFrame column headers.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1201,1269,84,unistr('```python\u000aimport pandas as pd\u000afrom sqlalchemy import create_engine\u000aengine = create_engine(''sqlite:///Northwind.sqlite'')\u000adf = pd.read_sql_query("SELECT * FROM Orders", engine)\u000a```'),'pandas.read_sql_query() — directly executes a SQL query and returns the result as a DataFrame.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1202,1329,86,'What is UTC and why is it important for datetime objects?','UTC (Coordinated Universal Time) is the primary time standard. All timezones are offsets from UTC, making it essential for comparing aware datetimes globally.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1203,1330,86,'Define Daylight Saving Time (DST) and its two effects on clocks.','DST advances clocks in spring (''spring forward'') and moves them back in fall (''fall back'') to extend evening daylight.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1204,1294,86,'What does `d.year` access for `d = date(2016, 10, 7)`?','The year attribute (returns 2016). It is an attribute, not a method, so no parentheses.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1205,1331,86,'What does `d.month` return for `d = date(2017, 11, 5)`?','The month attribute returns 11 (November).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1206,1332,86,'What does `d.day` give for `d = date(2016, 10, 7)`?','The day attribute returns 7.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1207,1333,86,'How does a `timedelta` differ from a `date` or `datetime`?','A `timedelta` represents a duration (difference), not a point in time. It has `.days`, `.seconds`, `.total_seconds()`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1208,1334,86,unistr('```python\u000adelta = timedelta(hours=36)\u000aprint(delta.days)\u000a```\u000aWhat is the output, and why might it surprise you?'),'It prints `1`. `days` is the whole number of days, ignoring the remaining 12 hours. Use `.total_seconds()` for the full duration.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1209,1295,86,unistr('```python\u000ad1 = date(2017, 11, 5)\u000atd = timedelta(days=29)\u000aresult = d1 + td\u000aprint(result)\u000a```\u000aWhat concept is being demonstrated?'),'Adding a `timedelta` to a `date` to get a new date (2017-12-04).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1210,1335,86,unistr('```python\u000ax = 0\u000ax += 1\u000a```\u000aWhat is the final value of `x` and what does `+=` do?'),'`x` becomes 1. `+=` adds the right value to the left variable and assigns it back.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1211,1336,86,unistr('```python\u000afrom datetime import timedelta\u000adelta = timedelta(days=1, hours=12)\u000a```\u000aWhat is the internal representation in days and seconds?'),'`delta.days` = 1, `delta.seconds` = 43200 (12 hours in seconds).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1212,1312,86,'What is a naive datetime and why can''t it be reliably compared globally?','A naive datetime has `tzinfo=None`. Without timezone, you don''t know the actual UTC moment, so cross‑timezone comparisons are ambiguous.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1213,1313,86,'What defines an aware datetime?','An aware datetime has `tzinfo` set to a timezone object, e.g., `timezone.utc` or `tz.gettz(''America/New_York'')`. It unambiguously identifies a moment.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1214,1316,86,unistr('```python\u000afrom dateutil import tz\u000aeastern = tz.gettz(''America/New_York'')\u000a```\u000aWhat does this code return?'),'A DST‑aware timezone object for US Eastern Time, using the tz database.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1215,1337,86,'What is pandas and its typical import alias?','`import pandas as pd` — a Python data analysis library providing DataFrame and tools for datetime handling.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1216,1338,86,unistr('```python\u000arides[''Start date''] = pd.to_datetime(rides[''Start date''], format=''%Y-%m-%d %H:%M:%S'')\u000a```\u000aWhat is this doing?'),'Converting the ''Start date'' column from strings to datetime objects using a specified format.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1217,1339,86,'What is a pandas Timestamp?','Pandas'' equivalent of Python''s `datetime`, with nanosecond precision and extra methods.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1218,1340,86,unistr('```python\u000arides[''Duration''].mean()\u000a```\u000aGiven `Duration` is a timedelta Series, what does this return?'),'A `Timedelta` scalar, e.g., `Timedelta(''0 days 00:19:38.931034'')`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1219,1341,86,unistr('```python\u000arides[''Duration''].sum()\u000a```\u000aWhat is the type of the result?'),'A `Timedelta` scalar, e.g., `Timedelta(''3 days 22:58:10'')`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1220,1342,86,unistr('```python\u000arides[''Member type''].value_counts()\u000a```\u000aWhat does this return?'),'A Series with counts of unique values: `Member 236`, `Casual 54`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1221,1343,86,unistr('```python\u000arides.resample(''D'', on=''Start date'')[''Duration seconds''].mean().plot()\u000a```\u000aWhat does this produce?'),'A line plot of the daily average ride duration.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1222,1344,86,unistr('```python\u000arides[''Start date''].dt.tz_localize(''America/New_York'', ambiguous=''NaT'')\u000a```\u000aWhat does `ambiguous=''NaT''` do?'),'It sets ambiguous datetimes (caused by DST fall‑back) to NaT instead of raising an error.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1223,1345,86,unistr('```python\u000arides[''Start date''].dt.day_name()\u000a```\u000aWhat does this return?'),'A Series of weekday names: `''Sunday''`, `''Monday''`, etc.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1224,1346,86,'What module and class represents a calendar date (year, month, day)?','`datetime.date`, imported as `from datetime import date`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1225,1297,86,unistr('```python\u000ad = date(2016, 10, 7)\u000aprint(d.weekday)\u000a```\u000aWhat is wrong?'),'`d.weekday` without parentheses returns a method object, not the integer. Correct: `d.weekday()` returns 4 (Friday).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1226,1298,86,unistr('```python\u000ad1 = date(2017, 11, 5)\u000ad2 = date(2017, 12, 4)\u000adelta = d2 - d1\u000aprint(type(delta), delta.days)\u000a```\u000aWhat is printed?'),'`<class ''datetime.timedelta''> 29`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1227,1299,86,unistr('```python\u000ad = date(2017, 11, 5)\u000aprint(d.isoformat())\u000a```\u000aWhat is the output?'),'`''2017-11-05''`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1228,1300,86,'Why are ISO 8601 date strings (e.g., ''2017-11-05'') useful for sorting?','Because lexicographic order matches chronological order — ''2017-12-04'' > ''2017-11-05''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1229,1301,86,unistr('```python\u000adt = datetime(2017, 12, 30, 15, 19, 13)\u000aprint(dt.isoformat())\u000a```\u000aWhat is printed?'),'`''2017-12-30T15:19:13''`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1230,1302,86,unistr('```python\u000astart = datetime(2017, 10, 8, 23, 46, 47)\u000anew = start + timedelta(days=1)\u000a```\u000aWhat is `new`?'),'A datetime `2017-10-09 23:46:47`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1231,1314,86,'How do you create a timezone object for UTC+5:30?',unistr('```python\u000afrom datetime import timezone, timedelta\u000atz = timezone(timedelta(hours=5, minutes=30))\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1232,1347,86,unistr('```python\u000adt = datetime(2017, 12, 30, 15, 9, 3, tzinfo=timezone(timedelta(hours=-5)))\u000a```\u000aWhat could be wrong if the intended time was actually Eastern Daylight Time?'),'The offset is -5 (EST), but EDT is -4. The datetime now misrepresents the UTC moment.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1233,1348,86,unistr('```python\u000afrom dateutil import tz\u000aeastern = tz.gettz(''America/New_York'')\u000a```\u000aWhy use this instead of a fixed offset?'),'It automatically handles DST transitions by consulting the tz database.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1234,1317,86,'What is the UTC offset for EST vs EDT, and when is each used?','EST = UTC‑5 (winter), EDT = UTC‑4 (summer). DST determines the active offset.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1235,1319,86,unistr('```python\u000arides[''Member type''].dt.year\u000a```\u000aWhat error occurs?'),'`AttributeError`: the `.dt` accessor only works on datetime‑like Series, but `''Member type''` is a string column.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1236,1349,86,unistr('```python\u000arides.groupby(''Member type'')[''Duration seconds''].mean()\u000a```\u000aWhat does this compute?'),'The average `Duration seconds` for each `Member type` (Casual and Member).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1237,1327,86,unistr('```python\u000arides[''Start date''].dt.tz_convert(''UTC'')\u000a```\u000aWhat condition must `Start date` satisfy?'),'It must already be timezone‑aware (have a timezone set), otherwise a `TypeError` is raised.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1238,1328,86,unistr('```python\u000arides[''End date''].shift(1)\u000a```\u000aWhat is the first element of the result?'),'`NaT` (Not a Time), because there is no preceding row.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1239,1318,86,unistr('```python\u000arides = pd.read_csv(''capital-onebike.csv'', parse_dates=[''Start date'', ''End date''])\u000a```\u000aWhat does `parse_dates` do?'),'Converts the specified columns to datetime objects while reading the CSV.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1240,1308,86,unistr('```python\u000adt = datetime.strptime("12/30/2017 15:19:13", "%d/%m/%Y %H:%M:%S")\u000a```\u000aWhat is the error?'),'Day and month are swapped in the format string relative to the actual data (data is MM/DD, format expects DD/MM).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1241,1310,86,'What is the difference between `timedelta.seconds` and `timedelta.total_seconds()`?','`.seconds` returns only the seconds component (0‑86399). `.total_seconds()` returns the total duration in seconds, including days.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1242,1358,87,'What is a docstring in Python?','A string written as the first line of a function body, used to document its purpose, arguments, and return value. It is stored in the function''s __doc__ attribute.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1243,1359,87,unistr('What type of docstring does this function have?\u000a\u000a```python\u000adef load_csv(filepath, delimiter='',''):\u000a    """Load a CSV file.\u000a\u000a    Args:\u000a        filepath (str): Path to the file.\u000a        delimiter (str, optional): Field delimiter.\u000a\u000a    Returns:\u000a        list: Rows read.\u000a    """\u000a```'),'Google-style docstring, with Args/Returns sections.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1244,1360,87,unistr('Identify the docstring style:\u000a\u000a```python\u000adef compute(data):\u000a    """Compute the mean.\u000a\u000a    Parameters\u000a    ----------\u000a    data : ndarray\u000a        Input array.\u000a\u000a    Returns\u000a    -------\u000a    float\u000a        The mean.\u000a    """\u000a```'),'Numpydoc style, using underlined sections with dashes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1245,1361,87,unistr('What is printed by this code?\u000a\u000a```python\u000adef the_answer():\u000a    """Return the answer to life, the universe, and everything.\u000a\u000a    Returns:\u000a        int\u000a    """\u000a    return 42\u000aprint(the_answer.__doc__)\u000a```'),unistr('Return the answer to life, the universe, and everything.\u000a\u000aReturns:\u000a    int'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1246,1362,87,'What is the difference between func.__doc__ and inspect.getdoc(func)?','func.__doc__ returns the raw docstring; inspect.getdoc(func) strips leading whitespace for cleaner display.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1247,1363,87,'Define the DRY principle and give an example of violation.','Don''t Repeat Yourself: avoid duplicate code by abstracting repeated logic into functions. Example: copying identical data loading code for train, val, test.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1248,1364,87,'Compare the DRY principle with the ''Do One Thing'' principle.','DRY avoids repetition; ''Do One Thing'' says each function should have a single responsibility. They complement each other.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1249,1368,87,unistr('What does this print?\u000a\u000a```python\u000adef foo(x):\u000a    x[0] = 99\u000a\u000adef bar(x):\u000a    x = x + 90\u000a\u000amy_list = [1, 2, 3]\u000afoo(my_list)\u000aprint(my_list)\u000a\u000amy_var = 3\u000abar(my_var)\u000aprint(my_var)\u000a```'),unistr('[99, 2, 3]\u000a3'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1250,1388,87,unistr('What does this print?\u000a\u000a```python\u000adef foo(var=[1]):\u000a    var.append(1)\u000a    return var\u000aprint(foo())\u000aprint(foo())\u000a```'),unistr('[1, 1]\u000a[1, 1, 1]'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1251,1365,87,unistr('What concept is demonstrated?\u000a\u000a```python\u000awith open(''data.txt'') as f:\u000a    text = f.read()\u000a```'),'Context manager, using the with statement to automatically close the file.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1252,1357,87,'Write the Python code to open a file ''my_file.txt'' using a context manager and read its contents into a variable text.',unistr('with open(''my_file.txt'') as my_file:\u000a    text = my_file.read()'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1253,1389,87,unistr('Why does this code raise a NameError?\u000a\u000a```python\u000a@contextlib.contextmanager\u000adef my_context():\u000a    print(''hello'')\u000a    yield\u000a    print(''goodbye'')\u000a```'),'The contextlib module is not imported.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1254,1390,87,unistr('What is the output?\u000a\u000a```python\u000aimport contextlib\u000a@contextlib.contextmanager\u000adef my_context():\u000a    print(''hello'')\u000a    yield 42\u000a    print(''goodbye'')\u000awith my_context() as foo:\u000a    print(''foo is {}''.format(foo))\u000a```'),unistr('hello\u000afoo is 42\u000agoodbye'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1255,1369,87,unistr('What pattern is shown?\u000a\u000a```python\u000awith open(src) as f_src:\u000a    with open(dst, ''w'') as f_dst:\u000a        for line in f_src:\u000a            f_dst.write(line)\u000a```'),'Nested context managers, managing two files at once.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1256,1370,87,unistr('What is the purpose of try/finally in this generator-based context manager?\u000a\u000a```python\u000a@contextlib.contextmanager\u000adef get_printer(ip):\u000a    p = connect_to_printer(ip)\u000a    try:\u000a        yield p\u000a    finally:\u000a        p.disconnect()\u000a```'),'It ensures p.disconnect() is called even if an exception occurs in the with block.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1257,1371,87,'Write a context manager using @contextmanager that acquires a printer and ensures it is disconnected, using try/finally.',unistr('import contextlib\u000a@contextlib.contextmanager\u000adef get_printer(ip):\u000a    p = connect_to_printer(ip)\u000a    try:\u000a        yield p\u000a    finally:\u000a        p.disconnect()'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1258,1366,87,'What does it mean that functions are first-class objects in Python?','Functions can be assigned to variables, passed as arguments, stored in data structures, and returned from other functions.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1259,1356,87,unistr('What is the difference between these two lines?\u000a\u000a```python\u000ax = my_function\u000ax = my_function()\u000a```'),'The first references the function object; the second calls it and assigns the return value.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1260,1372,87,unistr('What concept does this function use?\u000a\u000a```python\u000adef has_docstring(func):\u000a    return func.__doc__ is not None\u000a\u000adef no(): pass\u000adef yes(): """doc"""\u000aprint(has_docstring(no))\u000aprint(has_docstring(yes))\u000a```'),'Functions as arguments: has_docstring accepts a function as a parameter.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1261,1373,87,unistr('What is this an example of?\u000a\u000a```python\u000adef foo(x, y):\u000a    def in_range(v):\u000a        return v > 4 and v < 10\u000a    if in_range(x) and in_range(y):\u000a        print(x * y)\u000a```'),'A nested function: in_range is defined inside foo.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1262,1374,87,unistr('What is printed?\u000a\u000a```python\u000adef get_function():\u000a    def print_me(s):\u000a        print(s)\u000a    return print_me\u000anew_func = get_function()\u000anew_func(''Hello'')\u000a```'),'Hello','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1263,1375,87,unistr('What error does this produce?\u000a\u000a```python\u000adef foo():\u000a    x = 42\u000afoo()\u000aprint(x)\u000a```'),'NameError: name ''x'' is not defined, because x is local to foo.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1264,1376,87,'What is the difference between local and global scope?','Local scope exists within a function; global scope is the top-level of the module. Variables in global scope can be read inside functions, but assignment creates a local unless declared global.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1265,1367,87,'What is Python''s built-in scope?','The outermost scope containing built-in functions and exceptions like print, len, ValueError. It is searched last when resolving a name.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1266,1377,87,'Define nonlocal scope.','In nested functions, the scope of the enclosing (outer) function. Variables there are nonlocal to the inner function.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1267,1378,87,unistr('What does this code do?\u000a\u000a```python\u000ax = 7\u000adef foo():\u000a    global x\u000a    x = 42\u000afoo()\u000aprint(x)\u000a```'),'It modifies the global variable x using the global keyword, so the output is 42.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1268,1391,87,unistr('What is missing from this code to make it print 200, 200?\u000a\u000a```python\u000adef outer():\u000a    x = 10\u000a    def inner():\u000a        x = 200\u000a        print(x)\u000a    inner()\u000a    print(x)\u000a```'),'The nonlocal keyword: inner should have ''nonlocal x'' before the assignment to modify the enclosing x.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1269,1392,87,unistr('What concept is demonstrated?\u000a\u000a```python\u000adef foo():\u000a    a = 5\u000a    def bar():\u000a        print(a)\u000a    return bar\u000afunc = foo()\u000afunc()\u000a```'),'A closure: bar captures the variable a from foo''s scope, even after foo returns.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1270,1393,87,unistr('What does this code inspect?\u000a\u000a```python\u000afunc = foo()\u000aprint(func.__closure__[0].cell_contents)\u000a```'),'It accesses the value of the first nonlocal variable captured in the closure, via the __closure__ attribute and cell_contents.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1271,1379,87,unistr('What is a decorator in Python?\u000a\u000a```python\u000a@double_args\u000adef multiply(a, b):\u000a    return a * b\u000a```'),'A function that takes another function and returns a modified version, often adding behavior. The @ syntax applies the decorator.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1272,1380,87,'Write the line that applies a decorator named ''timer'' to a function ''sleep_n_seconds''.',unistr('@timer\u000adef sleep_n_seconds(n=10):\u000a    time.sleep(n)'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1273,1381,87,unistr('What is the inner function called in this decorator?\u000a\u000a```python\u000adef double_args(func):\u000a    def wrapper(a, b):\u000a        return func(a * 2, b * 2)\u000a    return wrapper\u000a```'),'wrapper (conventionally named), which replaces the original function.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1274,1382,87,'Write the wrapper function signature that can accept any positional and keyword arguments to make a decorator generic.','def wrapper(*args, **kwargs):','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1275,1394,87,unistr('What is wrong with this decorator factory?\u000a\u000a```python\u000adef run_n_times(n):\u000a    def wrapper(*args, **kwargs):\u000a        for i in range(n):\u000a            func(*args, **kwargs)\u000a    return wrapper\u000a```'),'It is missing the middle decorator layer that receives func. A factory must return a decorator, which then takes func.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1276,1383,87,unistr('What does @wraps(func) do in this decorator?\u000a\u000a```python\u000afrom functools import wraps\u000adef timer(func):\u000a    @wraps(func)\u000a    def wrapper(*args, **kwargs):\u000a        ...\u000a    return wrapper\u000a```'),'It copies metadata (name, docstring) from func to wrapper so the decorated function looks like the original.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1277,1385,87,unistr('What does this timer decorator print when the decorated function is called?\u000a\u000a```python\u000aimport time\u000afrom functools import wraps\u000a\u000adef timer(func):\u000a    @wraps(func)\u000a    def wrapper(*args, **kwargs):\u000a        t_start = time.time()\u000a        result = func(*args, **kwargs)\u000a        t_total = time.time() - t_start\u000a        print(''{} took {:.2f} seconds''.format(func.__name__, t_total))\u000a        return result\u000a    return wrapper\u000a\u000a@timer\u000adef wait(n):\u000a    time.sleep(n)\u000a\u000await(0.5)\u000a```'),'wait took 0.50 seconds (approximately)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1278,1386,87,unistr('What potential issue does this memoize decorator have?\u000a\u000a```python\u000adef memoize(func):\u000a    cache = {}\u000a    def wrapper(*args, **kwargs):\u000a        key = (args, tuple(sorted(kwargs.items())))\u000a        if key not in cache:\u000a            cache[key] = func(*args, **kwargs)\u000a        return cache[key]\u000a    return wrapper\u000a```'),'Unhashable arguments (like a list) will cause a TypeError when creating the key; also the cache never clears, leading to memory growth.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1279,1387,87,'What is the purpose of the signal module in Python?','It provides mechanisms to handle asynchronous signals, like setting an alarm to interrupt execution after a timeout.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1280,1395,87,unistr('What does this decorator do?\u000a\u000a```python\u000adef timeout(n_seconds):\u000a    def decorator(func):\u000a        @wraps(func)\u000a        def wrapper(*args, **kwargs):\u000a            signal.alarm(n_seconds)\u000a            try:\u000a                return func(*args, **kwargs)\u000a            finally:\u000a                signal.alarm(0)\u000a        return wrapper\u000a    return decorator\u000a```'),'It raises a TimeoutError if the decorated function runs longer than n_seconds, using signal.alarm to schedule an interrupt.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1281,1396,87,'What is a ''code smell''?','An indicator in code that suggests a deeper problem, such as repeated code or functions doing too much. It suggests refactoring may be needed.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1282,1407,95,'What is cloud computing?','Delivery of technology services (compute, storage, databases, networking) over the internet with pay-as-you-go pricing.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1283,1398,95,'Describe the pay-as-you-go pricing model.','Customers pay only for the cloud resources they actually consume, similar to an electricity bill.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1284,1408,95,'What does on‑premises computing mean?','Hosting and managing servers and IT infrastructure locally within an organisation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1285,1403,95,'Define virtualization.','Technology that splits one physical server into multiple virtual servers, each acting like an independent machine.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1286,1409,95,'What is scalability in cloud computing?','The ability to handle increasing workloads by adding resources (vertical) or distributing workloads (horizontal).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1287,1410,95,'What is vertical scaling?','Upgrading an existing machine''s power—adding more RAM or CPU (scale up).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1288,1399,95,'What is horizontal scaling?','Adding more machines to share the workload (scale out).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1289,1411,95,'Define High Availability.','Designing systems to ensure continuous operation with minimal downtime.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1290,1412,95,'Name the three main cloud service models and their key characteristic.','IaaS (infrastructure), PaaS (platform), SaaS (software). They differ by the level of control vs. provider management.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1291,1413,95,'What does IaaS provide?','Virtualized computing resources (servers, storage, networks). You manage the OS, middleware, and apps.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1292,1402,95,'Describe PaaS in one sentence.','A cloud environment providing tools and runtime for developing, testing, and deploying applications without managing the underlying OS.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1293,1414,95,'Give an example of SaaS and explain its typical characteristics.','Gmail is SaaS—a cloud‑delivered application managed entirely by the provider, accessible via a browser.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1294,1415,95,unistr('Which cloud service category does this represent?\u000a\u000a```\u000aAmazon EC2\u000a```'),'Compute. EC2 provides resizable virtual servers for running applications.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1295,1397,95,unistr('Which cloud service category does this belong to?\u000a\u000a```\u000aAmazon S3\u000a```'),'Storage. S3 is an object storage service for saving files and data.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1296,1401,95,unistr('Identify the service category:\u000a\u000a```\u000aAmazon RDS\u000a```'),'Database. RDS is a managed relational database service.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1297,1416,95,'What is redundancy in cloud architecture?','Duplication of critical systems or data to improve reliability and availability.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1298,1417,95,'What does ''serverless'' actually mean?','Servers still exist but are fully managed by the cloud provider; developers focus only on code execution.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1299,1404,95,'How do cloud providers achieve high reliability?','By replicating data across multiple, geographically distributed data centers.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1300,1418,95,'What is a public cloud deployment model?','Infrastructure shared across multiple organisations and accessed over the public internet, managed by a provider like AWS, Azure, or GCP.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1301,1419,95,'Define a private cloud.','A cloud environment dedicated to a single organisation, either on‑premises or hosted by a third party, using virtualization.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1302,1420,95,'What is a community cloud?','Infrastructure shared by several organisations with common concerns (e.g., security requirements, compliance).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1303,1421,95,'Under GDPR, what qualifies as personal data?','Any information that relates to an identified or identifiable living individual, including name, email, IP address, and location data.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1304,1422,95,'Name three data protection laws other than GDPR.','Brazil''s LGPD, California''s CCPA, and HIPAA (US health data).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1305,1423,95,'What does a cloud architect do?','Designs cloud solutions based on business requirements, ensuring scalability, cost optimisation, and security.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1306,1424,95,'Describe the role of a cloud engineer.','Builds, maintains, and monitors cloud services, often migrating on‑premise solutions and using infrastructure as code.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1307,1405,95,'What is the core principle of a DevOps engineer''s work?','Combining software development and IT operations to automate infrastructure and accelerate delivery.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1308,1425,95,'What is the primary responsibility of a cloud security engineer?','Specifying technical security requirements, testing data protection, and safeguarding cloud infrastructure.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1309,1426,95,'What distinguishes AWS in the cloud market?','Launched in 2006, it''s the market leader (31%) with over 175 services, including EC2, S3, and SageMaker.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1310,1427,95,'What is a key strength of Microsoft Azure?','Tight integration with Microsoft products and a large enterprise customer base, holding 24% market share.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1311,1428,95,'What is Google Cloud''s unique offering for multi‑cloud environments?','Anthos, which allows consistent application deployment across on‑premises and other clouds.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1312,1429,95,'How does cloud disaster recovery differ from simple backup?','DR includes failover procedures and tools to restore entire business operations; backup is just a copy of data.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1313,1430,95,'What is cloud governance?','Policies and frameworks ensuring secure, compliant, and efficient use of cloud services.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1314,1431,95,'Define SecOps.','Security‑focused operations that integrate security practices into daily cloud operations and compliance monitoring.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1315,1432,95,'What is the difference between elasticity and scalability?','Scalability is the capacity to grow; elasticity automatically scales resources up or down based on demand.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1316,1433,95,'A developer plans to use a FaaS service for a task that may run for 30 minutes. What is the potential issue?','FaaS functions have timeout limits (e.g., AWS Lambda maxes at 15 minutes). Long‑running tasks may fail.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1317,1400,95,'A manager says, ''Moving to the cloud means the provider handles all security.'' What is wrong with this statement?','Cloud security follows a shared responsibility model. The provider secures the infrastructure, but the customer must secure their data, apps, and configurations.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1318,1434,95,'A US‑based e‑commerce site processes orders from EU residents but does not apply GDPR safeguards, claiming it''s not an EU company. Is this correct?','No. GDPR applies to any organisation processing personal data of individuals in the EU, regardless of where the company is based.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1319,1435,95,'What is a hybrid cloud?','A mix of public and private cloud environments that communicate via a network link, allowing data and services to move between them.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1320,1436,95,'Define multicloud.','Using multiple cloud providers (e.g., AWS for hosting, Azure for backups, Google Cloud for analytics) to optimise performance, cost, or reliability.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1321,1437,95,'What is cloud bursting?','A hybrid cloud scenario where a private cloud hits capacity and overflow traffic is temporarily moved to a public cloud.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1322,1482,96,'What is Python?','A popular, general-purpose programming language known for its clear syntax and large developer community. It is free and open-source.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1323,1483,96,'What is a Python script?','A file with a .py extension where Python code is written, which the computer executes when run.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1324,1484,96,'What are good development practices when building software?','Start small, iterate, test, and document your code along the way.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1325,1444,96,unistr('Identify the error in this code:\u000a\u000a```python\u000aprint("Hello, world!"\u000a```'),'Missing closing parenthesis. The correct line is print("Hello, world!").','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1326,1454,96,unistr('What is wrong with this comment?\u000a\u000a```python\u000a// This is a comment\u000aprint("Hi")\u000a```'),'In Python, comments start with #, not //. The code will raise a SyntaxError.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1327,1455,96,'What is a variable in Python?','A named container that stores a value, allowing reuse with descriptive names.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1328,1442,96,'Write a line of code that creates a variable named `ingredient_name` with the string value ''pasta''.',unistr('```python\u000aingredient_name = "pasta"\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1329,1443,96,'Write a line of code that creates a variable `ingredient_quantity` with the integer value 2.',unistr('```python\u000aingredient_quantity = 2\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1330,1474,96,'Write the line of code to assign the value 10 to a variable named `count`.',unistr('```python\u000acount = 10\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1331,1456,96,unistr('What does the following code output?\u000a\u000a```python\u000aingredient_name = "tomatoes"\u000aprint(ingredient_name)\u000a```'),'tomatoes','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1332,1457,96,unistr('What concept does this code demonstrate?\u000a\u000a```python\u000aingredient_quantity = 1\u000aingredient_quantity = 3\u000aprint(ingredient_quantity)\u000a```'),'Updating variables (reassignment).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1333,1485,96,unistr('What is wrong with this variable name?\u000a\u000a```python\u000aingredient Name = "pasta"\u000a```'),'Spaces are not allowed in variable names. Use underscore: `ingredient_name`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1334,1486,96,unistr('Find the mistake:\u000a\u000a```python\u000anew_ingredient_quantity = 1,5\u000a```'),'The comma is not valid for decimals in Python. Use a dot: `1.5`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1335,1458,96,unistr('What is wrong with this code?\u000a\u000a```python\u000ais_in_stock = true\u000a```'),'Boolean values in Python are capitalized: `True`, not `true`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1336,1445,96,unistr('What is the output of this code?\u000a\u000a```python\u000aingredient_name = "tomatoes"\u000aprint(type(ingredient_name))\u000a```'),'<class ''str''>','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1337,1475,96,unistr('What does this code do?\u000a\u000a```python\u000aresult = 2 + 1.5\u000aprint(result)\u000a```'),'It adds an integer and a float and prints the result 3.5.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1338,1476,96,unistr('What concept is shown here?\u000a\u000a```python\u000aprint("Hi" * 3)\u000a```'),'String repetition using the * operator.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1339,1459,96,'How would you write a string containing the word `Chef''s` using double quotes?',unistr('```python\u000aingredient_name = "Chef''s special seasoning"\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1340,1460,96,unistr('What is this code doing?\u000a\u000a```python\u000ainstructions = """Step 1\u000aStep 2"""\u000aprint(instructions)\u000a```'),'It creates a multi-line string using triple quotes and prints it over two lines.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1341,1487,96,'What is a method in Python?','A function that belongs to a specific data type, called using dot notation (e.g., `variable.method()`).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1342,1446,96,unistr('What does this print?\u000a\u000a```python\u000awelcome_message = "Welcome to the recipe scaler, George"\u000awelcome_message.replace("George", "John")\u000aprint(welcome_message)\u000a```'),'Welcome to the recipe scaler, George','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1343,1447,96,unistr('What is the output?\u000a\u000a```python\u000aingredient_name = "Basil Leaves"\u000aingredient_name.lower()\u000aprint(ingredient_name)\u000a```'),'Basil Leaves','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1344,1448,96,unistr('What will be printed?\u000a\u000a```python\u000aingredient_name = "Basil Leaves"\u000aingredient_name = ingredient_name.upper()\u000aprint(ingredient_name)\u000a```'),'BASIL LEAVES','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1345,1461,96,'What is a list in Python?','An ordered collection of items, created with square brackets, that can hold multiple values of any data type.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1346,1462,96,unistr('What is wrong with this code?\u000a\u000a```python\u000aingredients = ["pasta", "tomatoes"]\u000aprint(ingredients[2])\u000a```'),'Index 2 is out of range; the list has only indices 0 and 1.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1347,1463,96,unistr('What concept is used here?\u000a\u000a```python\u000aingredients = ["pasta", "tomatoes"]\u000aprint(ingredients[-1])\u000a```'),'Negative indexing to access the last element.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1348,1464,96,unistr('What does this code do?\u000a\u000a```python\u000aingredients = ["pasta", "tomatoes", "garlic"]\u000aprint(ingredients[1:3])\u000a```'),'It prints a slice from index 1 up to (but not including) index 3: [''tomatoes'', ''garlic''].','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1349,1477,96,unistr('What is the result of this code?\u000a\u000a```python\u000anumbers = [0,1,2,3,4,5]\u000aprint(numbers[1:5:2])\u000a```'),'[1, 3]','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1350,1465,96,unistr('What data structure is created here?\u000a\u000a```python\u000arecipe = {"pasta": 500, "tomatoes": 400}\u000a```'),'A dictionary with keys ''pasta'' and ''tomatoes'' mapping to values 500 and 400.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1351,1466,96,unistr('What does this code retrieve?\u000a\u000a```python\u000arecipe = {"pasta": 500}\u000aprint(recipe["pasta"])\u000a```'),'It accesses the value associated with key ''pasta'', printing 500.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1352,1449,96,unistr('What does `recipe.values()` do?\u000a\u000a```python\u000arecipe = {"pasta": 500, "tomatoes": 400}\u000aprint(recipe.values())\u000a```'),'It returns a view object of all values: dict_values([500, 400]).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1353,1450,96,unistr('What concept is shown?\u000a\u000a```python\u000arecipe = {"pasta": 500, "tomatoes": 400}\u000aprint(recipe.keys())\u000a```'),'Using .keys() to retrieve all dictionary keys: dict_keys([''pasta'', ''tomatoes'']).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1354,1451,96,unistr('What does this code do?\u000a\u000a```python\u000arecipe = {"pasta": 500}\u000afor item, qty in recipe.items():\u000a    print(item, qty)\u000a```'),'It iterates over key-value pairs using .items(), printing ''pasta 500''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1355,1467,96,unistr('What does this code accomplish?\u000a\u000a```python\u000arecipe = {"pasta": 500}\u000arecipe["parmesan"] = 50\u000a```'),'It adds a new key ''parmesan'' with value 50 to the dictionary.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1356,1468,96,unistr('What is happening here?\u000a\u000a```python\u000arecipe = {"pasta": 500}\u000arecipe["pasta"] = 1000\u000a```'),'The value for key ''pasta'' is updated from 500 to 1000.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1357,1469,96,unistr('What is the value of recipe["garlic"] after this?\u000a\u000a```python\u000arecipe = {"pasta": 500, "garlic": 5, "garlic": 15}\u000aprint(recipe["garlic"])\u000a```'),'15','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1358,1470,96,unistr('What does this code create?\u000a\u000a```python\u000aunique_items = {"pasta", "tomatoes", "pasta"}\u000aprint(unique_items)\u000a```'),'A set containing unique items: {''pasta'', ''tomatoes''} (duplicate removed).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1359,1452,96,unistr('What does this code do?\u000a\u000a```python\u000aingredients_list = ["pasta", "tomatoes", "pasta"]\u000aunique_ingredients = set(ingredients_list)\u000a```'),'It converts the list to a set, removing duplicate ''pasta''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1360,1488,96,unistr('What is the error?\u000a\u000a```python\u000aingredients = {"pasta", "tomatoes"}\u000aprint(ingredients[0])\u000a```'),'TypeError: ''set'' object is not subscriptable. Sets do not support indexing because they are unordered.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1361,1453,96,unistr('What does this output?\u000a\u000a```python\u000aingredients = {"pasta", "tomatoes", "garlic"}\u000aprint(sorted(ingredients))\u000a```'),'[''garlic'', ''pasta'', ''tomatoes'']','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1362,1524,97,'What is Python?','Python is a high-level, interpreted programming language known for its readability, simplicity, and versatility. It is widely used for data science, web development, automation, and more.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1363,1525,97,'What is a Python script?','A Python script is a file containing Python code, typically saved with a `.py` extension. It can be executed by the Python interpreter.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1364,1526,97,'How does "starting small and iterating" differ from "trying to write all code at once without testing intermediate steps"?','Starting small means building a minimal working version, then adding features incrementally, testing each step. The anti-pattern is attempting to write the entire program at once, which leads to bugs that are hard to isolate and fix.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1365,1527,97,'Write a line of Python code that creates a variable named `ingredient_name` and assigns it the string value `"tomatoes"`.','`ingredient_name = "tomatoes"`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1366,1528,97,'Write code that creates a string variable `recipe_title` with the value `"Pasta Primavera"`.','`recipe_title = "Pasta Primavera"`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1367,1529,97,'What is the data type of the value `42` in Python?','`int` (integer)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1368,1491,97,'Write code that creates a variable `servings` and assigns it the integer value `4`.','`servings = 4`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1369,1492,97,unistr('What is the output of this code?\u000a\u000a```python\u000aingredient = "basil"\u000aprint(ingredient)\u000a```'),'`basil`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1370,1530,97,unistr('What does this print?\u000a\u000a```python\u000acount = 5\u000acount = count + 2\u000aprint(count)\u000a```'),'`7`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1371,1531,97,'What is the difference between `snake_case` and `camelCase` in Python variable naming?','`snake_case` uses underscores between words (e.g., `recipe_name`); `camelCase` capitalizes each word after the first (e.g., `recipeName`). Python''s official style guide (PEP 8) recommends `snake_case` for variable names.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1372,1493,97,unistr('What does this code print?\u000a\u000a```python\u000avalue = 3.14\u000aprint(type(value))\u000a```'),'`<class ''float''>`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1373,1495,97,unistr('What does this code output?\u000a\u000a```python\u000aprint("Hi" * 3)\u000a```'),'`HiHiHi`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1374,1496,97,'Why would you use double quotes (`"..."`) instead of single quotes (`''...''`) for a string in Python?','Use double quotes when the string contains an apostrophe (single quote) to avoid escaping. For example, `"Chef''s special"` is valid, while `''Chef''s special''` causes a syntax error.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1375,1497,97,'What is the difference between a method and a function in Python?','A method is a function that belongs to a specific data type (object) and is called using dot notation (`object.method()`). A function is independent and called by its name (`function()`).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1376,1498,97,unistr('What does this code print?\u000a\u000a```python\u000amessage = "Hello George"\u000amessage.replace("George", "John")\u000aprint(message)\u000a```'),'`Hello George`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1377,1499,97,unistr('What data structure is created by the following code?\u000a\u000a```python\u000a["pasta", "tomatoes", "garlic"]\u000a```'),'A list','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1378,1500,97,unistr('What error will occur when running this code?\u000a\u000a```python\u000aingredients = ["pasta", "tomatoes", "garlic"]\u000aprint(ingredients[3])\u000a```'),'`IndexError: list index out of range`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1379,1501,97,unistr('What is printed?\u000a\u000a```python\u000aitems = ["a", "b", "c", "d"]\u000aprint(items[-1])\u000a```'),'`d`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1380,1502,97,unistr('What does this output?\u000a\u000a```python\u000aletters = ["a", "b", "c", "d", "e"]\u000aprint(letters[1:4])\u000a```'),'`[''b'', ''c'', ''d'']`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1381,1503,97,unistr('What error occurs with this code?\u000a\u000a```python\u000anums = [0,1,2,3,4,5]\u000aprint(nums[::0])\u000a```'),'`ValueError: slice step cannot be zero`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1382,1504,97,unistr('What data structure is created by this code?\u000a\u000a```python\u000a{"pasta": 500, "tomatoes": 400}\u000a```'),'A dictionary','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1383,1505,97,unistr('What exception is raised by this code?\u000a\u000a```python\u000arecipe = {"pasta": 500}\u000aprint(recipe["tomatoes"])\u000a```'),'`KeyError: ''tomatoes''`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1384,1506,97,'How does `dict.values()` differ from returning a list of values?','`dict.values()` returns a **view** object, not a list. The view reflects any changes to the dictionary and is not directly indexable (though you can iterate over it).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1385,1507,97,'What is the difference between `dict.keys()` and `list(dict.keys())`?','`dict.keys()` returns a view object that reflects the dictionary''s current keys and updates when the dict changes. `list(dict.keys())` creates a static list copy that does not update automatically.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1386,1508,97,unistr('What is printed?\u000a\u000a```python\u000arecipe = {"a": 1, "b": 2}\u000afor key, value in recipe.items():\u000a    print(key, value)\u000a```'),'`a 1` then `b 2` (each on separate lines)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1387,1509,97,unistr('What is the value of `recipe` after this code?\u000a\u000a```python\u000arecipe = {"pasta": 500}\u000arecipe["garlic"] = 15\u000a```'),'`{''pasta'': 500, ''garlic'': 15}`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1388,1510,97,unistr('What does `recipe` contain after this?\u000a\u000a```python\u000arecipe = {"pasta": 500, "garlic": 15}\u000arecipe["pasta"] = 1000\u000a```'),'`{''pasta'': 1000, ''garlic'': 15}`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1389,1532,97,unistr('What is the value of `recipe["garlic"]` after this code?\u000a\u000a```python\u000arecipe = {"garlic": 5, "garlic": 15}\u000a```'),'`15` (no error; the second assignment overwrites the first)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1390,1533,97,unistr('Why does this code raise an error?\u000a\u000a```python\u000as = {1, 2, 3}\u000aprint(s[0])\u000a```'),'Sets are unordered and do not support indexing. Accessing by index (`[0]`) raises a `TypeError: ''set'' object is not subscriptable`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1391,1517,97,unistr('What is printed?\u000a\u000a```python\u000afor x in [10, 5, 1]:\u000a    if x > 8:\u000a        print("big")\u000a    elif x > 3:\u000a        print("medium")\u000a    else:\u000a        print("small")\u000a```'),'big\nmedium\nsmall','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1392,1519,97,'Compare using a `for` loop with `if ingredient not in pantry` versus using a set intersection to build a shopping list from a recipe.','The loop with `not in` is clear and works well for small data. Set intersection (`set(recipe) - pantry`) is more concise and faster for large datasets but only if you only need missing keys and not quantities.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1393,1520,97,'What does `*args` in a function definition represent? Give an example.','`*args` collects any number of extra positional arguments into a tuple. Example: `def sum_all(*args): return sum(args)` can be called as `sum_all(1,2,3)`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1394,1521,97,'What does `**kwargs` in a function definition represent? Provide code that uses it.','`**kwargs` collects any number of extra keyword arguments into a dictionary. Example: `def print_info(**kwargs): for k,v in kwargs.items(): print(k,v)` called as `print_info(name=''Alice'', age=30)`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1395,1523,97,unistr('What is wrong with this code?\u000a\u000a```python\u000atry:\u000a    value = int("hello")\u000aexcept:\u000a    value = 0\u000a```'),'It uses a bare `except:` which catches all exceptions, including `KeyboardInterrupt` and `SystemExit`. This can mask critical errors. Better: `except ValueError:`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1396,1534,97,'Write code that raises a `ValueError` with the message `"Number must be positive"` if a variable `n` is less than or equal to zero.',unistr('```python\u000aif n <= 0:\u000a    raise ValueError("Number must be positive")\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1397,1586,104,'What is version control?',unistr('A system to manage changes to documents, programs, and directories over time.\u000aIt allows tracking files in different states, comparing versions, and reverting changes.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1398,1586,104,'How does version control differ from keeping regular backups?','Backups are coarse snapshots; version control tracks every change, provides a detailed history, and enables comparison and selective reversion.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1399,1587,104,'Define Git.','A distributed, open‑source version control system that records snapshots of a project, supports collaboration, and uses hashes to identify content.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1400,1587,104,'What is the key difference between Git and GitHub?','Git is the version control system; GitHub is a cloud platform that hosts Git repositories and adds collaboration features.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1401,1588,104,'What is the shell (terminal) used for in the context of Git?','It is the program where you type and execute Git commands, and where output is displayed.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1402,1564,104,unistr('```shell\u000apwd\u000a```\u000aWhat does this command do?'),'Prints the full path of the current working directory.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1403,1565,104,unistr('```shell\u000als\u000a```\u000aWhat does this command show?'),'A list of files and directories in the current directory (hidden files not included by default).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1404,1566,104,unistr('```shell\u000acd archive\u000a```\u000aWhat does this command do?'),'Changes the current working directory to the folder named `archive`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1405,1567,104,unistr('```shell\u000agit --version\u000a```\u000aWhat does this output?'),'The installed Git version, e.g., `git version 2.46.0`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1406,1589,104,'What two parts make up a Git repository?',unistr('1) The working directory containing your project files.\u000a2) The hidden `.git` directory that stores all version control metadata.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1407,1589,104,'A user deletes the `.git` folder from their repository by mistake. What consequence does this have?','All version history, branches, and configuration are lost; only the current working files remain.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1408,1590,104,'What is the `.git` directory?','A hidden folder inside a repository that stores all of Git’s metadata, object database, and configuration.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1409,1568,104,unistr('```shell\u000agit init mental-health-workspace\u000a```\u000aWhat does this command achieve?'),'Creates a new directory `mental-health-workspace` and initializes a Git repository inside it.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1410,1569,104,unistr('What command produces the following output?\u000a\u000a```\u000aOn branch main\u000aNo commits yet\u000aUntracked files:\u000a  (use "git add <file>...")\u000a    report.md\u000a```'),'`git status`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1411,1569,104,'A repository has no changes since the last commit. What message does `git status` display?','`nothing to commit, working tree clean`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1412,1591,104,'You run `git init` inside a subfolder of an existing Git repo. Later, `git status` shows the subfolder as a weird entry. What mistake was made?','A nested repository was created. Git now sees two `.git` directories and becomes confused about which to track.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1413,1592,104,'What is the staging area (index) in Git?','An intermediate area where changes are placed via `git add` before they become part of a commit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1414,1592,104,'How does the staging area differ from the working directory?','The working directory contains the files you edit; the staging area holds the changes you have selected for the next commit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1415,1570,104,'You have modified `report.md` and created a new file `data.csv`. Write the command that stages both files for commit.','`git add report.md data.csv`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1416,1570,104,'A user runs `git add *` expecting to stage all changes. Why might this be problematic?','The shell expands `*` before Git sees it, potentially missing dotfiles (hidden files) and causing unintended staging.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1417,1571,104,'You have staged changes and want to create a commit with the message "Add survey data". Write the command.','`git commit -m "Add survey data"`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1418,1593,104,'What is a Git commit?','A recorded snapshot of a repository at a point in time, including metadata like author, timestamp, and a message.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1419,1593,104,'What is the difference between a commit and the staging area?','The staging area holds proposed changes for the next commit. A commit is a permanent snapshot created from those staged changes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1420,1572,104,'What is the 40‑character string `ad8acfef94cb...` associated with each commit?','A commit hash, a unique identifier generated by a hash function from the commit’s content.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1421,1594,104,'In Git’s object model, what is a tree object?','A Git object that records the names and locations of files and directories in a commit, linking to blobs and other trees.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1422,1595,104,'What is a Git blob?','A binary large object that stores the compressed contents of a file as it existed in a particular commit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1423,1596,104,'What property of Git’s hash function makes it suitable for version control?','It is deterministic—the same input always produces the same hash, allowing efficient sharing and integrity checks.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1424,1573,104,unistr('```shell\u000agit log\u000a```\u000aWhat information does this display?'),'The commit history in reverse chronological order, showing hashes, authors, dates, and messages.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1425,1574,104,unistr('```shell\u000agit log -3\u000a```\u000aWhat does the `-3` flag do?'),'Limits the output to the 3 most recent commits.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1426,1575,104,unistr('```shell\u000agit log --since=''Apr 2 2024''\u000a```\u000aWhat does this command show?'),'Commits made on or after April 2, 2024.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1427,1576,104,unistr('```shell\u000agit log --since=''Apr 2 2024'' --until=''Apr 11 2024''\u000a```\u000aWhat range of commits does this display?'),'Commits between April 2, 2024 and April 11, 2024 (inclusive).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1428,1580,104,unistr('```shell\u000agit show c27fa856\u000a```\u000aWhat does this command display?'),'Detailed information about the commit with hash `c27fa856`, including its metadata and the diff it introduced.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1429,1577,104,unistr('Given `git diff report.md` shows:\u000a\u000a```\u000a-TODO: write executive summary.\u000a+TODO: cite funding sources.\u000a```\u000aWhat does this mean?'),'The line ''TODO: write executive summary.'' was removed, and ''TODO: cite funding sources.'' was added in the unstaged changes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1430,1578,104,'You have staged changes and want to see what will be committed. What command do you run?','`git diff --staged`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1431,1597,104,'What does `HEAD` refer to in Git?','A symbolic pointer to the current commit (usually the latest commit on the checked‑out branch).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1432,1597,104,'What is the difference between `HEAD` and `HEAD~1`?','`HEAD` is the current commit; `HEAD~1` is the commit immediately before it (its parent).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1433,1579,104,unistr('```shell\u000agit diff HEAD~2 HEAD\u000a```\u000aWhat does `HEAD~2` represent?'),'The commit two steps before the current one (grandparent).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1434,1581,104,'You need to undo the changes of the most recent commit without rewriting history. What command do you use?','`git revert HEAD`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1435,1582,104,unistr('```shell\u000agit revert --no-edit HEAD\u000a```\u000aWhat does the `--no-edit` flag accomplish?'),'It skips the text editor and uses the default revert message.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1436,1583,104,unistr('```shell\u000agit revert -n HEAD\u000a```\u000aWhat is the effect of the `-n` flag?'),'It applies the inverse changes to the working directory and staging area but does not create a new commit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1437,1584,104,unistr('```shell\u000agit checkout HEAD~1 -- report.md\u000a```\u000aWhat does this command do?'),'Restores the file `report.md` to its state from the previous commit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1438,1585,104,unistr('```shell\u000agit restore --staged summary_statistics.csv\u000a```\u000aWhat is the result of this command?'),'The file `summary_statistics.csv` is removed from the staging area, but its working directory changes are kept.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1439,1616,122,'What are the recommended conventions for naming tables in SQL?',unistr('Table names should be clear, refer to the data they contain (plural), lowercase, and use underscores instead of spaces.\u000aExample: ''patrons'', ''books'', ''checkouts''.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1440,1617,122,'What are the recommended conventions for naming fields (columns) in SQL?',unistr('Field names should be lowercase, use underscores instead of spaces, be singular, and different from the table name.\u000aExample: ''card_num'', ''name'', ''member_year'', ''total_fine''.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1441,1618,122,'Define the term ''server'' in the context of databases.','A server is a centralized computer that stores database files on its hard disk and provides data access services to clients.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1442,1619,122,'What is a relational database, and what makes it different from a simple data store?','A relational database organizes data into tables and defines relationships between those tables, enabling complex data linking and integrity.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1443,1620,122,'What is a table in a database?','A table is a database object that stores data in a structured format of rows and columns.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1444,1621,122,'Define a record (or row) in a database table.','A record is a single row in a table, containing data for one specific observation or entity.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1445,1622,122,'Define a field (or column) in a database table.','A field is a column in a table, representing a single attribute that applies to all records.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1446,1623,122,'What is a unique identifier (key) in a table, and why is it important?','A unique identifier is a column (or combination) that uniquely identifies each record, such as ''card_num'' in patrons. It ensures no duplicate rows.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1447,1624,122,'What is a table relationship in a relational database?','A connection between tables via shared columns (foreign keys), allowing data to be linked across tables. For example, ''checkouts'' relates to ''patrons'' via ''card_num''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1448,1625,122,'What is SQL, and what is its primary purpose?','SQL stands for Structured Query Language. It is the standard language for creating, querying, and updating relational databases.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1449,1598,122,unistr('What database concept does this code represent?\u000a\u000a```sql\u000aSELECT name FROM patrons;\u000a```'),'Query. A query is a request for data or an operation, expressed in SQL. This one retrieves the ''name'' column from the ''patrons'' table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1450,1599,122,'What are SQL keywords, and which one begins every query?','Keywords are reserved words like SELECT, FROM, WHERE that indicate the operation to perform. Every query starts with SELECT.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1451,1600,122,'Write a SQL query to retrieve the ''card_num'' and ''name'' columns from the ''patrons'' table.',unistr('```sql\u000aSELECT card_num, name\u000aFROM patrons;\u000a```\u000aThis selects two specific columns in the specified order.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1452,1601,122,unistr('Complete the query to select all columns from a table named ''books'':\u000a```sql\u000aSELECT * _____ books;\u000a```'),unistr('```sql\u000aSELECT * FROM books;\u000a```\u000aThe FROM keyword specifies the source table.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1453,1626,122,'What is a result set in SQL?','The result set is the output of a SELECT query: a collection of rows and columns returned by the database.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1454,1602,122,'Write a query that selects every column from the ''employees'' table.',unistr('```sql\u000aSELECT * FROM employees;\u000a```\u000aThe asterisk wildcard selects all fields.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1455,1603,122,'Write a query that renames the ''name'' column to ''first_name'' in the result set from the ''employees'' table.',unistr('```sql\u000aSELECT name AS first_name\u000aFROM employees;\u000a```\u000aThe AS keyword creates an alias for the column.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1456,1604,122,unistr('What does this query do?\u000a\u000a```sql\u000aSELECT DISTINCT year_hired\u000aFROM employees;\u000a```'),'It returns a list of unique hiring years, eliminating duplicates.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1457,1627,122,'What is a view in SQL?','A view is a virtual table defined by a saved SELECT query. It does not store data; it dynamically retrieves data from underlying tables when accessed.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1458,1605,122,unistr('Identify the purpose of this SQL statement:\u000a\u000a```sql\u000aCREATE VIEW employee_hire_years AS\u000aSELECT dept_id, year_hired\u000aFROM employees;\u000a```'),'It creates a view named ''employee_hire_years'' that shows selected columns from the employees table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1459,1628,122,'What is a data type in the context of creating a table?','A data type defines the kind of data a column can hold, such as numbers, text, or dates. Examples: INT, VARCHAR, NUMERIC.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1460,1629,122,'What kind of data does the string type store, and how are string values represented in SQL queries?','String data types store text (sequence of characters). In queries, string values are enclosed in single quotes, e.g., ''Hello''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1461,1606,122,'How would you define a column for a patron''s name that can hold up to 250 characters?',unistr('```sql\u000aname VARCHAR(250)\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1462,1630,122,'What does the integer data type store, and what is its approximate numeric range in SQL?','Integer stores whole numbers (no decimal). The INT type covers roughly -2 billion to +2 billion.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1463,1607,122,'Write the SQL to define a column named ''card_num'' that stores integer values.',unistr('```sql\u000acard_num INT\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1464,1631,122,'What does the float data type store, and what is its main drawback for exact calculations?','Float stores numbers with a fractional part using approximate representation. It''s not ideal for precise monetary values due to rounding errors.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1465,1608,122,'Define a column named ''total_fine'' that can hold monetary values up to 999.99 with two decimal places.',unistr('```sql\u000atotal_fine NUMERIC(5,2)\u000a```\u000aNUMERIC(5,2) allows 5 total digits, 2 after the decimal.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1466,1632,122,'What is a database schema?','A schema is a blueprint of the database design, showing its tables, fields, data types, and relationships.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1467,1609,122,'Write a PostgreSQL query to retrieve only the first 3 rows from the ''books'' table.',unistr('```sql\u000aSELECT * FROM books LIMIT 3;\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1468,1610,122,'Write a SQL Server query to retrieve only the top 2 rows from the ''employees'' table.',unistr('```sql\u000aSELECT TOP(2) * FROM employees;\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1469,1673,123,'What does SQL stand for and what is its primary purpose?','Structured Query Language. It is used to query, manage, and manipulate data in relational databases.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1470,1674,123,'What is PostgreSQL?','A free, open‑source relational database system often used for SQL learning and practice.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1471,1675,123,'What dataset is used throughout this Intermediate SQL course to practice queries?','The Films Database, containing tables such as films, people, reviews, and roles.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1472,1676,123,'What is Holywell''s style guide in the context of SQL?','A set of conventions for writing SQL code, including indentation, aliasing, and capitalization, to improve readability and maintainability.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1473,1677,123,'A student sees an error message with a caret pointing to a line after a misspelled keyword. Why might the error line not indicate the actual mistake?','Because the error message often shows where the parser detected an unexpected token, not the original cause. The real error (e.g., misspelling) may be earlier, causing the parser to fail downstream.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1474,1678,123,unistr('Compare these two queries. Which one follows Holywell''s style guide and why?\u000a\u000aQuery A:\u000aSELECT title,release_year FROM films WHERE release_year>2000\u000a\u000aQuery B:\u000aSELECT title, release_year\u000aFROM films\u000aWHERE release_year > 2000;'),'Query B follows Holywell''s style guide. It uses line breaks, spaces around operators, and a semicolon for clarity.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1475,1679,123,'How do you terminate a SQL statement to ensure it is portable and clearly ended?',unistr('Place a semicolon (;) at the end of the statement.\u000aExample: SELECT title FROM films LIMIT 3;'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1476,1671,123,'State the logical processing order of SQL clauses. Start with FROM.','FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY → LIMIT','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1477,1638,123,unistr('The people table has 8397 rows. Some birthdates are NULL. What does the following return?\u000a\u000aSELECT COUNT(birthdate) AS count_birthdates FROM people;'),unistr('6152\u000aThis is the number of rows where birthdate is not NULL.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1478,1636,123,unistr('What concept does this query illustrate?\u000a\u000aSELECT COUNT(*) AS total_records FROM people;'),'COUNT(*) — counts all rows in the table, including those with NULL values.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1479,1639,123,unistr('What does this query achieve?\u000a\u000aSELECT DISTINCT language FROM films;'),'Returns all unique languages present in the films table, removing duplicates.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1480,1640,123,unistr('What is counted by this query?\u000a\u000aSELECT COUNT(DISTINCT birthdate) AS count_distinct_birthdates FROM people;'),'The number of unique, non‑null birthdates in the people table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1481,1637,123,'Write a query that retrieves only the first 10 names from the people table.','SELECT name FROM people LIMIT 10;','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1482,1641,123,'Write a query that selects all films released after the year 2010.','SELECT title FROM films WHERE release_year > 2010;','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1483,1642,123,'List the standard SQL comparison operators and explain what <> means.',unistr('>, <, =, >=, <=, <>.\u000a<> means ''not equal to''.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1484,1643,123,unistr('What is wrong with this query?\u000a\u000aSELECT title FROM films WHERE country = "Japan";'),'String literals must be enclosed in single quotes, not double quotes. "Japan" is interpreted as an identifier.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1485,1644,123,unistr('What does the following query return?\u000a\u000aSELECT title FROM films WHERE release_year = 1994 OR release_year = 2000;'),'Films released in either 1994 or 2000.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1486,1645,123,unistr('What does this query select?\u000a\u000aSELECT title FROM films WHERE release_year > 1994 AND release_year < 2000;'),'Films released in 1995, 1996, 1997, 1998, or 1999 (strictly between 1994 and 2000).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1487,1646,123,unistr('A student wants films from 1994 or 1995 that are rated ''PG''. They wrote:\u000a\u000aSELECT title FROM films WHERE release_year = 1994 OR release_year = 1995 AND certification = ''PG'';\u000a\u000aWhat is wrong with this query?'),'AND has higher precedence than OR. The query returns films from 1994 regardless of certification, plus only PG films from 1995. The intended logic requires parentheses: (release_year = 1994 OR release_year = 1995) AND certification = ''PG''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1488,1647,123,unistr('What does this query return?\u000a\u000aSELECT title FROM films WHERE release_year BETWEEN 1994 AND 2000;'),'All films with a release year from 1994 through 2000, inclusive.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1489,1648,123,unistr('What does the following query do?\u000a\u000aSELECT title FROM films WHERE release_year IN (1920, 1930, 1940);'),'Returns films whose release year is 1920, 1930, or 1940.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1490,1649,123,unistr('What pattern does this search for?\u000a\u000aSELECT name FROM people WHERE name LIKE ''Ade%'';'),'Names that start with ''Ade''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1491,1650,123,unistr('What does this query exclude?\u000a\u000aSELECT name FROM people WHERE name NOT LIKE ''A.%'';'),'Names that start with ''A.'' (e.g., ''A. Michael Baldwin'').','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1492,1672,123,'What is NULL in SQL, and why does `column = NULL` not work?','NULL represents missing or unknown data. Because NULL is unknown, any comparison with = results in unknown, which is not TRUE. Use IS NULL instead.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1493,1651,123,unistr('What does this query find?\u000a\u000aSELECT name FROM people WHERE birthdate IS NULL;'),'People whose birthdate is missing (NULL).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1494,1652,123,unistr('What does the following query count?\u000a\u000aSELECT COUNT(name) FROM people WHERE birthdate IS NOT NULL;'),'The number of non‑null names among people who have a known birthdate (6152 in the course).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1495,1653,123,'What are aggregate functions? Name at least four common ones.','Functions that summarize multiple rows into a single value. Common ones: COUNT, SUM, AVG, MIN, MAX.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1496,1654,123,unistr('What does AVG(budget) compute?\u000a\u000aSELECT AVG(budget) FROM films;'),'The average budget of all films, ignoring NULL values.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1497,1655,123,unistr('What does SUM(budget) do?\u000a\u000aSELECT SUM(budget) FROM films;'),'Returns the total sum of all non‑null budget values.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1498,1656,123,unistr('What does MIN(country) return?\u000a\u000aSELECT MIN(country) FROM films;'),'The alphabetically first country name according to the database''s collation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1499,1657,123,unistr('What does MAX(release_year) return?\u000a\u000aSELECT MAX(release_year) FROM films;'),'The most recent release year present in the films table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1500,1658,123,unistr('What does ROUND(AVG(budget), -2) do?\u000a\u000aSELECT ROUND(AVG(budget), -2) AS rounded_avg FROM films;'),'Rounds the average budget to the nearest hundred (10^2).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1501,1659,123,'What are the four arithmetic operators in SQL, and what is a common pitfall with division?',unistr('+, -, *, /\u000aDivision of two integers performs integer division and truncates the result (e.g., 4 / 3 = 1).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1502,1660,123,unistr('What is the result of this expression?\u000a\u000aSELECT 4 / 3;'),'1','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1503,1661,123,'How do you rename the output column of MAX(budget) to ''max_budget''?','SELECT MAX(budget) AS max_budget FROM films;','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1504,1680,124,'Define INNER JOIN and state what happens to rows without a match in either table.','INNER JOIN returns only rows where the join condition matches in both tables. Unmatched rows are omitted entirely.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1505,1681,124,unistr('What is the role of the following highlighted part in a join?\u000a\u000a```sql\u000aSELECT *\u000aFROM presidents\u000aINNER JOIN prime_ministers\u000aON presidents.country = prime_ministers.country;\u000a```'),'It is the ON clause, which specifies the condition used to match rows between the two tables.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1506,1682,124,unistr('What does the `USING` clause do in this query?\u000a\u000a```sql\u000aSELECT *\u000aFROM presidents\u000aINNER JOIN prime_ministers USING (country);\u000a```'),'It joins the tables on the column that has the same name in both tables, and that column appears only once in the output.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1507,1683,124,'Give the syntax to assign the alias `p1` to the `presidents` table in a join, and then use that alias to qualify the `country` column.',unistr('```sql\u000aSELECT p1.country\u000aFROM presidents AS p1\u000aINNER JOIN ...\u000a```\u000aThe `AS` keyword is optional.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1508,1708,124,'What is a primary key, and why is it important for joins?','A column (or set of columns) that uniquely identifies each row. It ensures that join matches are reliable and avoids unintended duplicate rows.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1509,1709,124,'Define a one‑to‑many relationship and give an example using `countries` and `cities`.','One record in table A relates to many records in table B. Example: one country (in `countries`) can have many cities (in `cities`).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1510,1710,124,'How does a one‑to‑one relationship differ from a one‑to‑many in terms of join row duplication?','In a one‑to‑one, each row from either table matches at most one row in the other, so the join produces the same number of rows as the smaller table (if fully matched). In one‑to‑many, the ''one'' side is duplicated for each matching row on the ''many'' side.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1511,1711,124,'Describe a many‑to‑many relationship and how it is implemented in SQL using the example of `countries` and `languages`.','Multiple rows in table A relate to multiple rows in table B. It’s implemented with a junction table (like `languages`) that holds foreign keys to both tables.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1512,1684,124,unistr('Predict the output of:\u000a\u000a```sql\u000aSELECT p1.country, prime_minister, president\u000aFROM prime_ministers AS p1\u000aLEFT JOIN presidents AS p2 USING(country);\u000a```\u000a(Assume `prime_ministers` has 10 rows, `presidents` 7 rows, and not all countries match.)'),'All 10 rows from `prime_ministers` appear. For countries without a president, the `president` column shows NULL.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1513,1685,124,unistr('Identify the join type in the following and explain what it guarantees:\u000a\u000a```sql\u000aSELECT p1.country, prime_minister, president\u000aFROM prime_ministers AS p1\u000aRIGHT JOIN presidents AS p2 USING(country);\u000a```'),'RIGHT JOIN. It guarantees that all rows from the right table (`presidents`) appear; left‑table columns are NULL for non‑matching right rows.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1514,1686,124,unistr('What does this query return?\u000a\u000a```sql\u000aSELECT p1.country AS country, prime_minister, president\u000aFROM prime_ministers AS p1\u000aFULL JOIN presidents AS p2 ON p1.country = p2.country;\u000a```\u000a(There are countries that only have a prime minister and others only a president.)'),'All distinct countries from both tables. Countries with both roles show both columns filled; otherwise the missing role’s column is NULL.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1515,1687,124,unistr('Find the error in this query that is supposed to list prime ministers and their presidents:\u000a\u000a```sql\u000aSELECT prime_minister, president\u000aFROM prime_ministers\u000aINNER JOIN presidents;\u000a```'),'Missing ON clause. Without an ON or USING, the INNER JOIN behaves like a CROSS JOIN, producing a Cartesian product of all rows.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1516,1688,124,unistr('What does the following query represent?\u000a\u000a```sql\u000aSELECT p1.country AS country1, p2.country AS country2, p1.continent\u000aFROM prime_ministers AS p1\u000aINNER JOIN prime_ministers AS p2\u000a    ON p1.continent = p2.continent\u000a    AND p1.country <> p2.country;\u000a```'),'A SELF JOIN. It joins the `prime_ministers` table to itself to pair countries from the same continent, excluding self‑pairings.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1517,1689,124,'Compare `UNION` and `UNION ALL` in terms of duplicate handling and performance.','`UNION` removes duplicate rows after combining; `UNION ALL` keeps all rows including duplicates. `UNION ALL` is faster because it doesn’t need to sort and deduplicate.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1518,1690,124,unistr('What will this query return?\u000a\u000a```sql\u000aSELECT monarch AS leader, country FROM monarchs\u000aUNION ALL\u000aSELECT prime_minister, country FROM prime_ministers;\u000a```\u000a(Assume Hassanal Bolkiah appears in both tables.)'),'It returns all rows from both tables, so Hassanal Bolkiah will appear twice (once as monarch, once as prime minister).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1519,1691,124,'How does `INTERSECT` differ from an `INNER JOIN` on all columns?','`INTERSECT` compares complete rows from two queries and removes duplicates. `INNER JOIN` can produce multiple matching rows and keeps all combinations.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1520,1692,124,unistr('What does the following query achieve?\u000a\u000a```sql\u000aSELECT monarch, country FROM monarchs\u000aEXCEPT\u000aSELECT prime_minister, country FROM prime_ministers;\u000a```'),'It returns monarchs who are not also prime ministers in the same country.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1521,1693,124,unistr('Why might this semi join return an empty result, even though there are European monarchs?\u000a\u000a```sql\u000aSELECT country_name\u000aFROM countries\u000aWHERE country_name IN (SELECT country FROM monarchs WHERE continent = ''Europe'');\u000a```'),'If the `country` column in `monarchs` contains NULL, the `IN` condition can evaluate to UNKNOWN for all rows, returning nothing.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1522,1694,124,unistr('What is the purpose of this query?\u000a\u000a```sql\u000aSELECT country\u000aFROM presidents\u000aWHERE country NOT IN (SELECT country FROM prime_ministers);\u000a```\u000a(Assume no NULLs in the subquery.)'),'It performs an anti join: returns countries that have a president but no prime minister.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1523,1695,124,'Define a subquery and list the three common clauses where it can appear.','A subquery is a query nested inside another SQL statement. It can appear in SELECT, FROM, or WHERE clauses.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1524,1696,124,unistr('Identify the pattern used below:\u000a\u000a```sql\u000aSELECT *\u000aFROM presidents\u000aWHERE country IN (SELECT country FROM states WHERE indep_year < 1800);\u000a```'),'Semi join implemented with WHERE IN subquery. It returns presidents from countries that gained independence before 1800.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1525,1697,124,unistr('What does the subquery compute in the following?\u000a\u000a```sql\u000aSELECT DISTINCT continent,\u000a       (SELECT COUNT(*) FROM monarchs\u000a        WHERE monarchs.continent = states.continent) AS monarch_count\u000aFROM states;\u000a```'),'It computes the number of monarchs per continent using a correlated scalar subquery in the SELECT list.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1526,1698,124,unistr('What must be added for this query to be valid?\u000a\u000a```sql\u000aSELECT continent, most_recent\u000aFROM (SELECT continent, MAX(indep_year) AS most_recent\u000a      FROM states\u000a      GROUP BY continent)\u000aORDER BY continent;\u000a```'),'The subquery in FROM must have an alias, e.g., `AS sub` after the closing parenthesis.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1527,1712,124,'Define a correlated subquery and explain how its execution differs from an uncorrelated one.','A correlated subquery references columns from the outer query. It is evaluated once for each row of the outer query, unlike an uncorrelated subquery that runs once.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1528,1699,124,unistr('What does this query do?\u000a\u000a```sql\u000aSELECT p1.country, p1.continent, president, prime_minister, pm_start\u000aFROM prime_ministers AS p1\u000aINNER JOIN presidents AS p2 USING(country)\u000aINNER JOIN prime_minister_terms AS p3 USING(prime_minister);\u000a```'),'It chains two INNER JOINs to combine country data, presidents, and prime minister start years into one result.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1529,1700,124,unistr('What does the AND do in this join condition?\u000a\u000a```sql\u000aSELECT *\u000aFROM left_table\u000aINNER JOIN right_table\u000a    ON left_table.id = right_table.id\u000a    AND left_table.date = right_table.date;\u000a```'),'It joins on a composite key: rows must match on both `id` and `date` to appear in the result.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1530,1701,124,'What is the effect of `SELECT DISTINCT continent FROM states;`?','It returns each unique continent name exactly once, removing duplicate rows.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1531,1702,124,unistr('What does this query return?\u000a\u000a```sql\u000aSELECT p1.country, prime_minister\u000aFROM prime_ministers p1\u000aLEFT JOIN presidents p2 ON p1.country = p2.country\u000aWHERE president IS NULL;\u000a```'),'All prime ministers whose country does not have a president; the `president` column is NULL for those rows after the LEFT JOIN, and the WHERE clause keeps only those.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1532,1703,124,unistr('Why does this UNION fail?\u000a\u000a```sql\u000aSELECT name, city_proper_pop FROM cities\u000aUNION\u000aSELECT country_name, continent FROM countries;\u000a```'),'The data types don’t match: the second column in the first query is numeric (`city_proper_pop`), while the second column in the second query is string (`continent`).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1533,1704,124,'What is a Cartesian product and when does it occur in SQL?','A Cartesian product is every possible combination of rows from two tables (N × M rows). It occurs with CROSS JOIN or when a join is missing an ON condition.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1534,1705,124,'Write a SELECT statement that renames the `country` column to `nation` in the output.',unistr('```sql\u000aSELECT country AS nation\u000aFROM presidents;\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1535,1713,124,'What is a ''Data leader'' according to the course glossary?','Any individual who champions data use, models data‑first behaviors, and helps others learn to use data effectively, regardless of their formal title.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1536,1714,124,'Define LOWESS as used in statistical contexts.','A locally weighted scatterplot smoothing technique that fits a smooth curve through points to reveal nonlinear trends.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1537,1706,124,'Define a SQL JOIN in general terms.','A SQL operation that combines columns from two or more tables by matching rows according to a specified condition.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1538,1707,124,unistr('What does the FROM clause specify in this query?\u000a\u000a```sql\u000aSELECT *\u000aFROM presidents\u000aINNER JOIN prime_ministers ON presidents.country = prime_ministers.country;\u000a```'),'It lists the tables (`presidents` and `prime_ministers`) that are the source of the data and defines the left/right context for the join.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1539,1715,124,'What is a table in a relational database?','A database object that stores data in rows and columns, where each row is a record and each column is a field with a specific data type.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1540,1716,124,'Define a column in the context of a SQL table.','A named field within a table that holds values of a specific data type for every record, used for conditions, selection, and aggregation.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1541,1747,125,'What is a relational database?','A structured collection of data organized into tables that model real-world entities and their relationships.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1542,1748,125,'Define a table in a relational database.','A database object that stores rows of data about a single entity type, with columns defining attributes and constraints.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1543,1749,125,'What is a column (attribute) in a table?','A named vertical field that defines a data element for every row, specifying a data type and constraints.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1544,1750,125,'What is a row (record) in a table?','A single horizontal entry representing one instance of the entity type, containing values for each column.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1545,1751,125,'What is redundancy in a database?','Duplication of data, often caused by storing multiple entity types in one table, leading to update anomalies.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1546,1752,125,'What is an entity type?','A category of real‑world objects (e.g., professors, universities) that becomes a table in a relational database.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1547,1753,125,'What does an Entity‑Relationship Diagram (ERD) represent and which shapes correspond to what?','Graphical representation of entity types, attributes, and relationships. Squares = entities, circles = attributes, rhombuses = relationships.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1548,1717,125,unistr('What does this SQL statement do?\u000a\u000a```sql\u000aCREATE TABLE weather (\u000a  clouds text,\u000a  temperature numeric,\u000a  weather_station char(5)\u000a);\u000a```'),'Creates a table named `weather` with three columns: `clouds` (text), `temperature` (numeric), and `weather_station` (char(5)).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1549,1718,125,'What is the `information_schema` and what does it store?','A built‑in, read‑only schema that contains metadata about all database objects: tables, columns, constraints, etc.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1550,1719,125,unistr('What does this query return?\u000a\u000a```sql\u000aSELECT table_name, column_name, data_type\u000aFROM information_schema.columns\u000aWHERE table_name = ''pg_config'';\u000a```'),'The names and data types of all columns in the table named `pg_config`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1551,1720,125,'Write the SQL pattern that inserts distinct rows from one table into another, avoiding duplicates.',unistr('```sql\u000aINSERT INTO organizations\u000aSELECT DISTINCT organization, organization_sector\u000aFROM university_professors;\u000a```'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1552,1754,125,'What is a data type in the context of a database column?','The definition of the kind of values a column can hold (e.g., integer, text, date), constraining storage and allowed operations.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1553,1743,125,'What is the `text` data type in PostgreSQL?','A character string type that can hold strings of any length without a predefined limit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1554,1721,125,'Define the `varchar(n)` data type.','Variable‑length character string with a maximum of `n` characters; no space padding is added.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1555,1722,125,'A column is defined as `weather_station char(5)`. Later, `''KNYC''` is inserted. What is a common pitfall with this type?','The value is space‑padded to exactly 5 characters (`''KNYC ''`). Comparisons ignore trailing spaces, but storage is wasted.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1556,1744,125,'What are the possible values of a `boolean` column in PostgreSQL?','TRUE, FALSE, and NULL (representing unknown).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1557,1723,125,'Explain `numeric(4,2)`. What values can it store?','Precision 4 (total digits), scale 2 (digits after decimal). Maximum value is 99.99. `123.456` would be rejected.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1558,1745,125,'What is the range of the `integer` data type in PostgreSQL?','-2,147,483,648 to +2,147,483,647 (a 4‑byte signed integer).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1559,1746,125,'Compare `date`, `time`, and `timestamp` data types in PostgreSQL.','`date` – stores only the date (no time). `time` – stores only the time of day. `timestamp` – stores date and time, without time zone.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1560,1724,125,'What is `serial` in PostgreSQL and what is an important caveat?','Auto‑incrementing integer type. It uses a sequence; gaps can occur after rollbacks or manual sequence changes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1561,1725,125,unistr('What is the purpose of `CAST` in this expression?\u000a\u000a```sql\u000aSELECT temperature * CAST(wind_speed AS integer) AS wind_chill\u000aFROM weather;\u000a```'),'It converts `wind_speed` to an integer on the fly so the multiplication can be performed.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1562,1726,125,'What does the `DISTINCT` keyword do in a `SELECT` statement?','Removes duplicate rows from the result set, considering all selected columns together.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1563,1727,125,unistr('What does this statement do?\u000a\u000a```sql\u000aINSERT INTO table_name (column_a, column_b)\u000aVALUES (''value_a'', ''value_b'');\u000a```'),'Inserts a single new row into `table_name` with the given values for `column_a` and `column_b`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1564,1728,125,unistr('What is the effect of this command?\u000a\u000a```sql\u000aALTER TABLE table_name\u000aRENAME COLUMN old_name TO new_name;\u000a```'),'Renames the column `old_name` to `new_name` in the specified table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1565,1729,125,unistr('What happens when you run this?\u000a\u000a```sql\u000aALTER TABLE table_name\u000aDROP COLUMN column_name;\u000a```'),'Permanently removes the column `column_name` from `table_name`. If the column is referenced elsewhere, the command fails unless `CASCADE` is used.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1566,1730,125,'What does a `NOT NULL` constraint enforce?','Every row must have a concrete value for that column; NULLs are disallowed.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1567,1755,125,'What does `NULL` represent in SQL?','A special marker meaning missing, unknown, or inapplicable data. It is not equal to any value, not even another NULL.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1568,1755,125,unistr('Identify the error in this query:\u000a\u000a```sql\u000aSELECT * FROM products\u000aWHERE price = NULL;\u000a```'),'`= NULL` never matches NULL. Use `WHERE price IS NULL` instead. The condition evaluates to UNKNOWN, so no rows are returned.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1569,1731,125,'What is a key behavior of the `UNIQUE` constraint regarding NULLs in PostgreSQL?','All non‑null values must be distinct, but multiple rows can contain NULL because NULL is never equal to any other value.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1570,1756,125,'Define a superkey.','Any set of columns that uniquely identifies each row. It may include extra columns that are not needed for uniqueness.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1571,1757,125,'What is a key (minimal superkey)?','A minimal set of columns that uniquely identifies each row – removing any column from the set destroys uniqueness.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1572,1758,125,'Define a candidate key.','A minimal set of columns that uniquely identifies rows. A table can have several; one is chosen as the primary key.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1573,1732,125,'What is a primary key and what constraints does it combine?','The chosen candidate key that uniquely identifies each row. It implicitly enforces `NOT NULL` and `UNIQUE`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1574,1733,125,'What is a composite key?','A primary (or candidate) key made up of two or more columns. The combination of values must be unique.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1575,1734,125,'What is a surrogate key?','An artificial column (often a `serial` integer) used as the primary key, with no business meaning.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1576,1735,125,unistr('What does this statement do and how does it handle NULL?\u000a\u000a```sql\u000aUPDATE table_name\u000aSET column_c = CONCAT(column_a, column_b);\u000a```'),'Sets `column_c` to the concatenation of `column_a` and `column_b`. In PostgreSQL, `CONCAT` ignores NULL arguments.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1577,1736,125,'Define a foreign key.','A column (or set of columns) that references the primary key of another table, enforcing referential integrity.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1578,1759,125,'What does cardinality describe in database relationships?','How many instances of one entity can relate to instances of another: 1:1, 1:N, or N:M.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1579,1760,125,'Where should the foreign key be placed in a one‑to‑many (1:N) relationship?','On the ''many'' side table, referencing the primary key of the ''one'' side table.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1580,1737,125,'How is a many‑to‑many (N:M) relationship implemented?','With a junction table that contains foreign keys referencing both related tables, plus optional relationship attributes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1581,1767,137,unistr('What data type is `cookies`?\u000a\u000a```python\u000acookies = [''chocolate chip'', ''peanut butter'', ''sugar'']\u000a```'),'list','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1582,1802,137,'What are the two boolean literals in Python?','True and False (capitalised).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1583,1803,137,'What is the key difference between a mutable and an immutable container sequence?','Mutable containers (e.g., list) can be changed after creation; immutable ones (e.g., tuple) cannot.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1584,1768,137,'Define a tuple in Python.','An ordered, immutable sequence type. Created with parentheses or by separating items with commas.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1585,1786,137,'What is a dictionary?','A mutable collection of unique key‑value pairs. Keys must be hashable (e.g., strings, numbers).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1586,1804,137,'Write the code to convert the string ''123'' to an integer.','`int(''123'')`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1587,1805,137,'What is the output of `float(123456789123456789)`?','`1.2345678912345678e+17`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1588,1806,137,'What is a set?','An unordered, mutable collection that stores only unique elements. Based on mathematical set theory.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1589,1807,137,unistr('What does this code do?\u000a\u000a```python\u000afrom collections import Counter\u000ac = Counter([''a'', ''b'', ''a''])\u000a```'),'Creates a Counter object: Counter({''a'': 2, ''b'': 1}), a dict subclass that counts occurrences.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1590,1808,137,'What is a defaultdict?','A dictionary subclass that automatically assigns a default value to missing keys using a factory function (e.g., list, int).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1591,1809,137,'What is a namedtuple?','A factory function that creates a tuple subclass with named fields, allowing attribute‑style access (e.g., point.x).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1592,1810,137,'What is a dataclass?','A decorator that automatically adds __init__, __repr__, __eq__, and other methods to a class based on its type annotations.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1593,1769,137,unistr('What is wrong with this code?\u000a\u000a```python\u000acookies = [''chocolate chip'']\u000anew_list = cookies.append(''Tirggel'')\u000aprint(new_list)\u000a```'),'It prints None because append modifies the list in place and returns None.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1594,1811,137,unistr('What exception does this code raise?\u000a\u000a```python\u000ad = {''a'': 1}\u000aprint(d[''b''])\u000a```'),'KeyError: ''b''','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1595,1781,137,unistr('What is the output?\u000a\u000a```python\u000acookies = [''chocolate chip'', ''peanut butter'']\u000aprint([cookie.title() for cookie in cookies if cookie.startswith(''c'')])\u000a```'),'[''Chocolate Chip'']','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1596,1783,137,'What does `list(zip([1, 2, 3], [''a'', ''b'']))` return?','[(1, ''a''), (2, ''b'')]','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1597,1794,137,'What does `type({})` return?','<class ''dict''>','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1598,1812,137,'What is the purpose of `defaultdict(list)`?','To automatically create an empty list for missing keys, allowing direct appending without checking for key existence.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1599,1813,137,'Given `a = {1, 2}` and `b = {2, 3}`, what does `a.intersection(b)` return?','{2}','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1600,1814,137,unistr('What does this print?\u000a\u000a```python\u000afrom collections import namedtuple\u000aEatery = namedtuple(''Eatery'', [''name'', ''park_id''])\u000ae = Eatery(''Mapes'', ''M010'')\u000aprint(e.name)\u000a```'),'''Mapes''','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1601,1815,137,'Write the code to convert a dataclass instance `c` to a dictionary.',unistr('`from dataclasses import asdict`\u000a`asdict(c)`'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1602,1782,137,'What does `sorted([3, 1, 2], reverse=True)` return?','[3, 2, 1]','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1603,1775,137,'What is the result of `''life'' in ''Life is a long lesson in humility.''`?','False','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1604,1776,137,'What does `''Hello''.lower()` return?','''hello''','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1605,1789,137,'How do you loop through keys and values of a dictionary `d`?','`for key, value in d.items():`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1606,1790,137,unistr('What is wrong with this code?\u000a\u000a```python\u000ad = {''a'': 1}\u000aif 1 in d:\u000a    print(''found'')\u000a```'),'''found'' is not printed because `in` checks keys, not values. 1 is a value.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1607,1816,137,'What is the difference between False and None in a boolean context?','Both are falsey, but False is the boolean false, while None is a special object meaning ''no value''.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1608,1817,137,'What does `s.discard(5)` do if 5 is not in set s?','Nothing – no error is raised.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1609,1818,137,'What is `{1, 2, 3}.difference({2, 4})`?','{1, 3}','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1610,1819,137,'What is `defaultdict(int)` commonly used for?','Counting occurrences, because missing keys automatically start at 0.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1611,1820,137,unistr('What type is `item`?\u000a\u000a```python\u000aitem = ''butter'',\u000a```'),'tuple: (''butter'',)','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1612,1772,137,unistr('What is the output?\u000a\u000a```python\u000aname = ''cookie''\u000aprint(f"{{name}}")\u000a```'),'{name}','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1613,1795,137,'Why use Decimal instead of float for currency?','Decimal provides exact decimal arithmetic, avoiding the rounding errors that float introduces.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1614,1796,137,'What is printed by `print(f"{0.00001:f}")`?','0.000010','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1615,1797,137,'What is `-7 // 3`?','-3','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1616,1821,137,'Why does `0.1 + 0.2 == 0.3` return False?','Because 0.1 + 0.2 is stored as something like 0.30000000000000004, not exactly 0.3.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1617,1822,137,'What is the difference between `s.update(other)` and `s.union(other)`?','update() modifies s in place; union() returns a new set, leaving s unchanged.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1618,1823,137,'What does `Counter(''aab'').most_common(1)` return?','[(''a'', 2)]','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1619,1824,137,'What does the @property decorator do inside a dataclass?','It allows a method to be accessed like an attribute, without calling it with parentheses. Often used for computed properties.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1620,1825,137,'What does `frozen=True` do in a dataclass?','It makes instances immutable; any attempt to assign to a field after creation raises FrozenInstanceError.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1621,1866,140,'What does the built-in function `str()` do?',unistr('Returns the string representation of an object.\u000a\u000aFor example, `str(123)` gives `''123''`. It is essential for converting non-string objects into strings before concatenation.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1622,1838,140,unistr('What string method is used in this snippet?\u000a\u000a```python\u000amy_string = "This is a nice string"\u000aprint(my_string.upper())\u000a```'),unistr('`.upper()` method.\u000a\u000aIt returns a new string with all alphabetic characters converted to uppercase, leaving the original unchanged.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1623,1867,140,unistr('What is printed by this code?\u000a\u000a```python\u000amy_string = "tHis Is a niCe StriNg"\u000aprint(my_string.capitalize())\u000a```'),unistr('`This is a nice string`\u000a\u000aThe first character is capitalized, and all other characters are lowercased.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1624,1868,140,'How does `.rsplit()` differ from `.split()` when `maxsplit=2`?',unistr('`.split(sep, maxsplit=2)` splits from the left, leaving the rightmost parts together.\u000a`.rsplit(sep, maxsplit=2)` splits from the right, leaving the leftmost parts together.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1625,1869,140,unistr('What method is used here?\u000a\u000a```python\u000amy_string = "line1\\nline2\\r\\nline3"\u000aprint(my_string.splitlines())\u000a```'),unistr('`.splitlines()`\u000a\u000aIt splits a string at line boundaries (newline, carriage return, etc.) and returns a list of lines.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1626,1870,140,unistr('What is the result of this expression?\u000a\u000a```python\u000a"   hello \\n".strip()\u000a```'),unistr('`''hello''`\u000a\u000aLeading and trailing whitespace are removed.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1627,1871,140,'What is the difference between `.strip()` and `.rstrip()`?',unistr('`.strip()` removes whitespace from **both** ends.\u000a`.rstrip()` removes whitespace only from the **right** end.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1628,1872,140,'How does `.lstrip()` differ from `.rstrip()`?','`.lstrip()` removes characters from the **left** (beginning), while `.rstrip()` removes from the **right** (end).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1629,1873,140,unistr('What is wrong with this code?\u000a\u000a```python\u000amy_string = "Where''s Waldo?"\u000aprint(my_string.index("Wenda"))\u000a```'),unistr('`.index()` raises a `ValueError` if the substring is not found.\u000a\u000aTo avoid the error, either catch it with `try/except` or use `.find()` (which returns -1).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1630,1842,140,'What does `"aaa".count("aa")` return?',unistr('`1`\u000a\u000aCounts **non‑overlapping** occurrences.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1631,1843,140,unistr('What method is used in this snippet?\u000a\u000a```python\u000amy_string = "The red house is between the blue house and the old house"\u000aprint(my_string.replace("house", "car", 2))\u000a```'),unistr('`.replace()`\u000a\u000aIt returns a new string with all occurrences of `"house"` replaced by `"car"`, limited to the first 2 occurrences.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1632,1874,140,unistr('What kind of placeholders are used here?\u000a\u000a```python\u000aprint("{1} {0}".format("world", "Hello"))\u000a```'),unistr('Indexed placeholders.\u000a\u000aThe numbers inside `{}` specify which positional argument to use.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1633,1875,140,'What are positional placeholders in `.format()`?','Empty `{}` braces that are filled by the arguments of `.format()` in the order they appear.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1634,1876,140,unistr('What does this print?\u000a\u000a```python\u000aprint("Only {0:.2f}%".format(0.5155675))\u000a```'),unistr('`Only 0.52%`\u000a\u000a`:.2f` formats the float to 2 decimal places.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1635,1877,140,unistr('What is the `!r` doing in this f-string?\u000a\u000a```python\u000aname = "Python"\u000aprint(f"Python is called {name!r}")\u000a```'),'`!r` calls `repr()` on `name`, producing a string that includes quotes.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1636,1846,140,unistr('What does this print?\u000a\u000a```python\u000anumber = 90.4189\u000aprint(f"{number:.2f}")\u000a```'),unistr('`90.42`\u000a\u000aThe float is rounded to two decimal places.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1637,1878,140,'Write an f-string that prints today''s date in the format ''April 14, 2019'' using `datetime.now()`.',unistr('```python\u000afrom datetime import datetime\u000aprint(f"{datetime.now():%B %d, %Y}")\u000a```\u000a\u000a`%B` = full month name, `%d` = day, `%Y` = full year.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1638,1879,140,unistr('What feature of f-strings does this snippet demonstrate?\u000a\u000a```python\u000aprint(f"4 multiplied by 7 is {4 * 7}")\u000a```'),unistr('Inline operations.\u000a\u000aYou can evaluate expressions directly inside the curly braces.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1639,1880,140,unistr('What does this print?\u000a\u000a```python\u000adef add(a, b):\u000a    return a + b\u000aprint(f"{add(10, 20)}")\u000a```'),unistr('`30`\u000a\u000aThe function `add` is called and its return value is inserted.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1640,1881,140,unistr('What class is used in this snippet?\u000a\u000a```python\u000afrom string import Template\u000amy_string = Template(''$title has been called $description'')\u000aprint(my_string.substitute(title=''Data science'', description=''sexiest job''))\u000a```'),unistr('`Template`\u000a\u000aIt is a simpler, safer formatting tool from the `string` module that uses `$` placeholders.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1641,1882,140,unistr('Why does this code crash?\u000a\u000a```python\u000afrom string import Template\u000afavorite = {''flavor'': ''chocolate''}\u000at = Template(''I love $flavor $cake'')\u000aprint(t.substitute(favorite))\u000a```'),unistr('`substitute()` raises a `KeyError` because `$cake` has no matching value.\u000a\u000aIt is strict: every placeholder must be filled.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1642,1883,140,'How does `safe_substitute()` differ from `substitute()` in `Template`?',unistr('`substitute()` raises `KeyError` for missing placeholders.\u000a`safe_substitute()` leaves missing placeholders unchanged (`$name` stays as `$name`).'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1643,1884,140,unistr('What standard library module does this code import?\u000a\u000a```python\u000aimport re\u000are.findall(r"#movies", "Love #movies!")\u000a```'),unistr('`re`\u000a\u000aIt provides regular expression operations in Python.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1644,1885,140,'What is the difference between `\d` and `\D` in regex?',unistr('`\\d` matches any digit (0‑9).\u000a`\\D` matches any character that is **not** a digit.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1645,1886,140,'How does `\W` differ from `\w`?',unistr('`\\w` matches word characters (letters, digits, underscore).\u000a`\\W` matches everything **except** word characters.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1646,1887,140,'What does `re.sub(r"ice\Scream", "ice cream", "I really like ice- cream")` return?',unistr('`''I really like ice cream''`\u000a\u000a`\\S` matches any non‑whitespace character.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1647,1860,140,unistr('What does the `^` mean in this regex?\u000a\u000a```python\u000are.findall(r"^the\\s\\d+s", "the 80s music was much better that the 90s")\u000a```'),unistr('Anchors the match to the **start** of the string.\u000a\u000aIt ensures the pattern is only matched at the very beginning.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1648,1861,140,unistr('What does `$` do in this pattern?\u000a\u000a```python\u000are.findall(r"the\\s\\d+s$", "the 80s music was much better that the 90s")\u000a```'),unistr('Anchors the match to the **end** of the string.\u000a\u000aThe pattern will only match if it appears just before the string''s end.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1649,1888,140,unistr('```python\u000amatch = re.search(r"(\\d{2})-(\\d{2})-(\\d{4})", "12-03-2008")\u000aprint(match.group(3))\u000a```\u000aWhat is printed?'),unistr('`''2008''`\u000a\u000a`group(3)` returns the third capturing group.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1650,1889,140,'What does `re.search(r"(\d[A-Za-z])+", "My user name is 3e4r5fg")` match?',unistr('`<re.Match object; span=(16, 22), match=''3e4r5f''>`\u000a\u000aThe `+` repeats the whole group, matching alternating digit‑letter pairs.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1651,1864,140,unistr('What is the `(?:...)` in this regex?\u000a\u000a```python\u000are.findall(r"(?:\\d{2}-){3}\\d{3}-\\d{3}", "John Smith: 34-34-34-042-980")\u000a```'),unistr('A **non‑capturing group**.\u000a\u000aIt groups without saving the matched text, keeping the group count unchanged.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1652,1890,140,'What does `re.findall(r"(\d+)\s(cat|dog)", "I want 2 cats, 1 dog or a bird.")` return?',unistr('`[(''2'', ''cat''), (''1'', ''dog'')]`\u000a\u000aThe parentheses scope the alternation, and capturing groups return tuples.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1653,1891,140,unistr('What is `(?P<city>...)` in this regex?\u000a\u000a```python\u000amatch = re.search(r"(?P<city>[A-Za-z]+),\\s*(?P<zipcode>\\d{5})", "Austin, 78701")\u000aprint(match.group("city"))\u000a```'),unistr('A **named capturing group**.\u000a\u000aIt captures a match and gives it a readable name for later reference.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1654,1892,140,unistr('What is wrong with this backreference attempt?\u000a\u000a```python\u000are.sub(r"(?P<word>\\w+)\\s(?P=word)", r"\\1", "This app is repeating the last word word.")\u000a```'),unistr('Using `(?P=word)` is correct inside the pattern, but the replacement uses `\\1` instead of the named reference `\\g<word>`.\u000a\u000aIt still works because `\\1` refers to the first numbered group, but mixing styles is inconsistent.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1655,1893,140,'How does `(?!...)` differ from `(?=...)`?',unistr('`(?=...)` is a **positive** lookahead – asserts that the following text matches.\u000a`(?!...)` is a **negative** lookahead – asserts that the following text does **not** match.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1656,1894,140,'What is the difference between `(?<=...)` and `(?<!...)`?',unistr('`(?<=...)` is **positive lookbehind** – asserts the preceding text matches.\u000a`(?<!...)` is **negative lookbehind** – asserts the preceding text does **not** match.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1657,1895,140,unistr('What happens when you run this?\u000a\u000a```python\u000aname = ''Alice''\u000aprint(f"Hello {name!r}")\u000a```'),unistr('`Hello ''Alice''`\u000a\u000a`!r` is allowed, but the point is that backslashes are **not** allowed inside the braces.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1658,1895,140,unistr('What causes the error here?\u000a\u000a```python\u000aname = ''Bob''\u000aprint(f"Hello {name\\t}")\u000a```'),unistr('`\\t` is a backslash escape inside the braces, which is not allowed in f‑strings.\u000a\u000aBackslashes are forbidden inside the expression part.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1659,1896,140,'What does `re.findall(r"(\d)+", "8755")` return?',unistr('`[''5'']`\u000a\u000aOnly the **last** repetition is captured by the group.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1660,1897,140,unistr('Why does this code fail?\u000a\u000a```python\u000ainfo = {"tool": "Unsupervised algorithms", "goal": "patterns"}\u000aprint(''{data[tool]} finds {data[goal]}''.format(data=info))\u000a```'),unistr('The correct syntax is `{data[tool]}` – without quotes around the key.\u000a\u000a`''{data[''tool'']}''` would cause a `KeyError` or syntax issue because the quotes are misinterpreted.'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1701,1976,142,'Define a shell in the context of Unix-like operating systems.','A command-line interface that interprets typed commands and sends them to the operating system.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1702,1977,142,'What is the purpose of the command prompt in a shell session?','It indicates that the shell is ready to accept the next command, usually ending with a $ or # symbol.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1703,1978,142,'How does the Linux filesystem hierarchy differ from Windows in terms of its root and drive letters?','Linux has a single root /, with all drives and partitions mounted under it. Windows uses separate drive letters (C:, D:, etc.).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1704,1979,142,unistr('What concept does this path represent?\u000a\u000a```Shell\u000a/home/repl/seasonal/winter.csv\u000a```'),'Absolute path – a full path starting from the root /.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1705,1980,142,unistr('What kind of path is this?\u000a\u000a```Shell\u000aseasonal/winter.csv\u000a```'),'Relative path – it starts from the current directory, not from root.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1706,1981,142,'Which symbol can you use to refer to your home directory in a path?','~ (tilde), e.g., `cd ~` or `ls ~/seasonal`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1707,1982,142,'What is the current working directory and which command reveals it?','It''s the directory the shell currently operates in. `pwd` prints its absolute path.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1708,1941,142,unistr('What is the output of this command if you are in /home/repl/seasonal?\u000a\u000a```Shell\u000apwd\u000a```'),'/home/repl/seasonal','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1709,1942,142,'A directory contains files `data.txt`, `script.sh`, and `.config`. Why does `ls` only show `data.txt` and `script.sh`?','`ls` hides files starting with a dot (.) by default. Use `ls -a` to show all.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1710,1943,142,unistr('What is wrong with this command?\u000a\u000a```Shell\u000acd..\u000a```'),'Missing space: it should be `cd ..` (space between cd and the directory).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1711,1983,142,'What does `..` represent in a file path?','The parent directory – the directory one level above the current one.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1712,1944,142,'How do you copy the entire directory `reports/` and its contents into a new directory `archive/`?','Use `cp -r reports archive` (or `cp -R`). Without -r, cp refuses to copy directories.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1713,1945,142,'You run `mv important.txt archive/` but archive/ already contains a file named important.txt. What happens?','The existing file is silently overwritten.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1714,1946,142,unistr('What is the dangerous mistake in this command if `temp` is a directory?\u000a\u000a```Shell\u000arm temp\u000a```'),'rm without -r cannot delete directories and will show an error, but a beginner might think it succeeded because some files are deleted if they mistakenly typed * instead.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1715,1947,142,'When should you use `less` instead of `cat` to view a file?','Use `less` for large files because it shows one screen at a time. `cat` dumps the entire file to the terminal.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1716,1948,142,unistr('What does this command print?\u000a\u000a```Shell\u000ahead -n 3 seasonal/summer.csv\u000a```'),'The first three lines of the file (including the header and the next two data lines).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1717,1949,142,unistr('What is the output if you run `tail -n 2` on a file with these lines?\u000aApple\u000aBanana\u000aCherry\u000aDate'),unistr('Cherry\u000aDate'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1718,1984,142,'What shell feature allows you to press the Tab key to complete a partially typed filename?','Tab completion – it auto‑completes commands or file paths.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1719,1985,142,'What are command‑line flags and how are they typically written?','Flags (or options) modify a command''s behavior, usually starting with a single dash (e.g., `-l`, `-n 5`).','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1720,1951,142,'Which command extracts the second column from a comma‑separated file `data.csv`?','cut -d , -f 2 data.csv','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1721,1952,142,'How do you search for the word ''error'' case‑insensitively in all .log files?','grep -i error *.log','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1722,1986,142,'What does `history` output look like?',unistr('A numbered list of previously executed commands, e.g.:\u000a1  pwd\u000a2  ls\u000a3  cd seasonal'),'2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1723,1953,142,'What is the difference between `>` and `>>` when saving command output to a file?','`>` overwrites the file if it exists. `>>` appends the output to the end of the file.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1724,1954,142,'Which symbol chains two commands so that the first command''s output becomes the second''s input?','| (pipe), e.g., `head -n 5 file.txt | tail -n 3`','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1725,1987,142,'Why does `ls ''*.csv''` produce an error even though .csv files exist?','Quotes prevent wildcard expansion. The shell looks for a file literally named ''*.csv'', not all .csv files.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1726,1956,142,'What does `*.txt` match?','All files (and directories) whose names end with ''.txt'', regardless of length before the extension.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1727,1957,142,'What is the difference between `?` and `*` in wildcard patterns?','`?` matches exactly one character. `*` matches zero or more characters.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1728,1958,142,'What pattern would match `photo1.jpg` and `photo2.jpg` but not `photo10.jpg`?','photo[0-9].jpg – the brackets match a single digit.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1729,1959,142,'Why does `ls {*.txt, *.csv}` fail with a syntax error?','There must be no space after the comma inside the braces.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1730,1988,142,'What is the difference between an environment variable and a shell variable?','Environment variables are passed to child processes (exported), while shell variables exist only in the current shell.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1731,1989,142,unistr('What is wrong with this assignment?\u000a\u000a```Shell\u000aname = John\u000a```'),'Spaces around the equals sign are not allowed. It should be `name=John`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1732,1962,142,unistr('What does this command print?\u000a\u000a```Shell\u000aname=Alice\u000aecho "Hello $name"\u000a```'),'Hello Alice','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1733,1964,142,unistr('What is wrong with this command?\u000a\u000a```Shell\u000a$file=data.csv\u000a```'),'The `$` prefix on the left side is used for reading a variable, not assigning one. Use `file=data.csv`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1734,1965,142,'How do you print the value stored in the shell variable `user`?','echo $user  (or echo "$user")','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1735,1966,142,unistr('What is the syntax error in this loop?\u000a\u000a```Shell\u000afor file in *.txt\u000ado echo $file; done\u000a```'),'Missing semicolon or newline before `do`. It should be `for file in *.txt; do echo $file; done`.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1736,1969,142,'What is nano and how do you save a file and exit?','nano is a simple command-line text editor. Save with Ctrl+O, then exit with Ctrl+X.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1737,1970,142,unistr('What is the purpose of this line at the top of a script?\u000a\u000a```Shell\u000a#!/bin/bash\u000a```'),'It''s the shebang, specifying that the script should be run with the Bash interpreter.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1738,1973,142,unistr('What does a `#` at the beginning of a line do in a shell script?\u000a\u000a```Shell\u000a# This line is ignored\u000a```'),'It makes the rest of the line a comment; the shell ignores it.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1739,1990,142,'What does pressing Ctrl+C do in a running terminal program?','It sends an interrupt signal (SIGINT) to the foreground process, typically causing it to terminate.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1740,1975,142,unistr('What does this command achieve?\u000a\u000a```Shell\u000ahistory | tail -n 5 > recent.txt\u000a```'),'It saves the last 5 commands from your history into the file recent.txt.','2026-06-18',1,2.5,0);
INSERT INTO flashcards VALUES(1741,1995,141,'What is the purpose of the `pass` statement in Python, especially within a class body?',unistr('It is a placeholder that does nothing. It satisfies the syntax requirement for an indented block when no code is needed yet.\u000a\u000aIt is used to create an empty class or method stub without causing an IndentationError.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1742,2024,141,'What is the `self` parameter in a Python instance method, and why is it conventionally named `self`?',unistr('`self` refers to the current instance of the class. It must be the first parameter of every instance method.\u000a\u000aBy convention, it is named `self` to make code readable, though any name could be used.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1743,2025,141,'Define procedural programming and give a typical scenario where it is used.',unistr('A paradigm where code is written as a sequence of steps to be carried out. It is common for simple, non‑repetitive tasks and data analysis scripts.\u000a\u000aExample: reading a CSV file and computing summary statistics without creating custom classes.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1744,2026,141,'Describe object‑oriented programming and its primary benefits.',unistr('OOP organises code as interactions of objects that bundle data (attributes) and functionality (methods). It helps build maintainable, reusable software.\u000a\u000aBenefits: modularity, code reuse through inheritance, and easier modelling of real‑world problems.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1745,2027,141,'What is an object in OOP?',unistr('An object is a combination of data (state) and functionality (behaviour). It is an instance of a class.\u000a\u000aExample: `cust = Customer()` creates an object with attributes like `name` and methods like `set_name()`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1746,2028,141,'What does the term ''state'' refer to in an object?',unistr('State is the data associated with an object, represented by its attributes. It reflects the current values of the object''s data.\u000a\u000aFor example, `self.balance = 1000` defines the financial state of a bank account object.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1747,2029,141,'What is meant by the ''behavior'' of an object?',unistr('Behavior is the functionality of an object, defined by its methods. It describes what an object can do.\u000a\u000aExample: `cust.identify()` prints the customer''s name – that''s a behaviour.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1748,2030,141,'Define a class in Python, and contrast it with an object.',unistr('A class is a blueprint or template for creating objects. It defines the possible attributes and methods that its instances will have.\u000a\u000aAn object is a specific instance created from that class.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1749,2031,141,'What is an instance?',unistr('An instance is an object created from a class. It is a specific realisation of the class blueprint.\u000a\u000a`cust = Customer()` creates an instance of `Customer`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1750,2032,141,'What is an attribute, and how is it accessed in Python?',unistr('An attribute is a variable bound to an object (or class) that stores its state. It is accessed using dot notation: `obj.attribute`.\u000a\u000aExample: `cust.name` retrieves the customer''s name.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1751,2033,141,'What is a method in Python, and how does it differ from a regular function?',unistr('A method is a function defined inside a class. It defines the behaviour of objects.\u000a\u000aIt is called on an instance: `obj.method()`. The first parameter is always `self`, which refers to the instance.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1752,2002,141,unistr('What concept does the following code illustrate?\u000a\u000a```python\u000aclass Customer:\u000a    def set_name(self, new_name):\u000a        self.name = new_name\u000a    def identify(self):\u000a        print(''I am Customer '' + self.name)\u000a```'),unistr('Using instance attributes inside methods.\u000a\u000a`self.name` is accessed inside `identify()` to retrieve the attribute set earlier.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1753,2004,141,unistr('What special method is demonstrated below, and what is its purpose?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, name, balance):\u000a        self.name = name\u000a        self.balance = balance\u000a```'),unistr('`__init__` – the constructor.\u000a\u000aIt is automatically called when a new object is created (`Customer(...)`) to initialise the instance''s attributes.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1754,2005,141,unistr('Identify the problem in this `__init__` method:\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, name, balance=0):\u000a        self.name = name\u000a        self.balance = balance\u000a```\u000aNo bug? Or hidden danger?'),unistr('It is syntactically correct, but a common mistake would be using a mutable default like `balance=[]`. That would be shared across all instances.\u000a\u000aHere `balance=0` is immutable, so it''s safe.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1755,2006,141,'What is a class attribute, and how is it defined?',unistr('A class attribute is a variable defined directly in the class body (outside any method). It is shared by all instances of that class.\u000a\u000a`class Employee:\u000a    MIN_SALARY = 30000`'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1756,2034,141,'Explain inheritance as a core OOP principle.',unistr('Inheritance allows a new class (child) to acquire attributes and methods from an existing class (parent). It represents an ''is‑a'' relationship.\u000a\u000a`class SavingsAccount(BankAccount):` makes `SavingsAccount` a specialised form of `BankAccount`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1757,2035,141,'What is polymorphism in OOP?',unistr('Polymorphism means that objects of different classes can be treated uniformly through a common interface. The same method call can behave differently depending on the object''s class.\u000a\u000aExample: calling `withdraw()` on different account types works correctly for each.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1758,2007,141,unistr('Predict the output of this code:\u000a\u000a```python\u000aclass Employee:\u000a    MIN_SALARY = 30000\u000a\u000aemp1 = Employee()\u000aemp2 = Employee()\u000aemp1.MIN_SALARY = 50000\u000aprint(emp2.MIN_SALARY)\u000a```'),unistr('`30000`\u000a\u000a`emp1.MIN_SALARY = 50000` created a new instance attribute on `emp1`, leaving the class attribute unchanged. `emp2` still sees the class value.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1759,2008,141,'Write the decorator and first parameter used to define a class method.',unistr('```python\u000a@classmethod\u000adef my_method(cls, args):\u000a    ...\u000a```\u000aThe decorator is `@classmethod` and the first parameter is `cls`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1760,2036,141,'What does the `cls` parameter represent inside a class method?','It is a reference to the class itself (the class object where the method is defined). It is used to access class attributes, call other class methods, or create instances via `cls(...)`.','2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1761,2009,141,unistr('What pattern is shown below?\u000a\u000a```python\u000a@classmethod\u000adef from_file(cls, filename):\u000a    with open(filename) as f:\u000a        name = f.readline().strip()\u000a        salary = int(f.readline().strip())\u000a    return cls(name, salary)\u000a```'),unistr('Alternative constructor.\u000a\u000aIt is a class method that provides a different way to instantiate the class – here by reading data from a file.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1762,2037,141,'When should you use a class method instead of an instance method?',unistr('Use a class method when the logic does not need access to instance‑specific data (i.e., it works with the class itself). Typical use cases: alternative constructors, factory methods, or class‑level utilities.\u000a\u000aInstance methods require an instance and are for operations on that specific object.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1763,2012,141,unistr('What is the purpose of `BankAccount.__init__(self, balance)` inside a child''s `__init__`?\u000a\u000a```python\u000aclass SavingsAccount(BankAccount):\u000a    def __init__(self, balance, interest_rate):\u000a        BankAccount.__init__(self, balance)\u000a        self.interest_rate = interest_rate\u000a```'),'To call the parent''s constructor, ensuring that the parent’s initialisation runs and its attributes are properly set on the child instance.','2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1764,2013,141,unistr('Identify what the following method does:\u000a\u000a```python\u000aclass SavingsAccount(BankAccount):\u000a    def compute_interest(self, n_periods=1):\u000a        return self.balance * ((1 + self.interest_rate) ** n_periods - 1)\u000a```'),'This is a new method added in the child class that calculates compound interest using the inherited `balance` attribute and the child‑specific `interest_rate`.','2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1765,2014,141,unistr('What will be printed by this code?\u000a\u000a```python\u000aclass BankAccount:\u000a    def withdraw(self, amount):\u000a        print(''Parent withdraw'')\u000a        self.balance -= amount\u000a\u000aclass CheckingAccount(BankAccount):\u000a    def withdraw(self, amount, fee=0):\u000a        print(''Child withdraw'')\u000a        BankAccount.withdraw(self, amount + fee)\u000a\u000aacct = CheckingAccount()\u000aacct.balance = 100\u000aacct.withdraw(30)\u000a```'),unistr('```\u000aChild withdraw\u000aParent withdraw\u000a```\u000aThe overridden method in `CheckingAccount` is called first, which prints its message, then delegates to the parent''s `withdraw`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1766,2038,141,'Without a custom `__eq__`, what does the comparison `c1 == c2` return when `c1` and `c2` are two distinct objects with identical attribute values?',unistr('`False`.\u000a\u000aPython compares object identities (memory addresses), not attribute values.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1767,2010,141,unistr('What is wrong with this line?\u000a\u000a```python\u000aclass SavingsAccount(BankAccount)\u000a    pass\u000a```'),'Missing colon after the parent class name. It should be `class SavingsAccount(BankAccount):`.','2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1768,2039,141,'Why does adding a required parameter to an overridden method break polymorphism?',unistr('Because code written to use the parent''s interface (e.g., `acct.withdraw(50)`) will fail when passed a child instance that expects extra arguments.\u000a\u000aThis violates the principle that objects of different classes should be interchangeable via a common interface.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1769,2015,141,unistr('What does this code print?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, id, name):\u000a        self.id = id\u000a        self.name = name\u000a    def __eq__(self, other):\u000a        return (self.id == other.id and\u000a                self.name == other.name)\u000a\u000ac1 = Customer(1, ''Alice'')\u000ac2 = Customer(1, ''Alice'')\u000aprint(c1 == c2)\u000a```'),unistr('`True`\u000a\u000aThe custom `__eq__` compares `id` and `name`. Both match, so equality returns `True`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1770,2016,141,unistr('Consider this `__eq__` implementation. What potential problem does it have?\u000a\u000a```python\u000adef __eq__(self, other):\u000a    return (self.id == other.id and\u000a            self.name == other.name)\u000a```'),unistr('It does not check the type of `other`. If `other` is a different type with the same attributes, it might incorrectly return `True`.\u000a\u000aA safer version adds: `and type(self) == type(other)`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1771,2040,141,'If you define only `__eq__` in a class, what does Python automatically do for `!=`?',unistr('Python automatically generates a `__ne__` method that returns the negation of `__eq__`.\u000a\u000aThus `obj1 != obj2` will be `True` unless `__eq__` returns `True`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1772,2017,141,'Given both parent and child define `__eq__`, which `__eq__` is called first when comparing `child_obj == parent_obj`?',unistr('The child''s `__eq__` is called first.\u000a\u000aPython always starts method lookup from the class of the left operand (here the child).'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1773,2018,141,unistr('What does `print(cust)` output when the class defines:\u000a\u000a```python\u000adef __str__(self):\u000a    return f"Customer: {self.name}"\u000a```'),unistr('```\u000aCustomer: Maryam Azar\u000a```\u000a(assuming `self.name = ''Maryam Azar''`)\u000a\u000a`print()` calls `__str__`, which returns a user‑friendly string.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1774,2019,141,unistr('Predict the output when `__repr__` is defined as below and `__str__` is absent:\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, name, bal):\u000a        self.name = name; self.balance = bal\u000a    def __repr__(self):\u000a        return f"Customer(''{self.name}'', {self.balance})"\u000a\u000acust = Customer(''Maryam Azar'', 3000)\u000aprint(cust)\u000a```'),unistr('```\u000aCustomer(''Maryam Azar'', 3000)\u000a```\u000aBecause `__str__` is missing, Python falls back to `__repr__`.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1775,2041,141,'What is the fundamental difference between `__str__` and `__repr__`?',unistr('`__str__` is for end‑users, aiming for readability. `__repr__` is for developers, aiming for unambiguity and often the ability to recreate the object.\u000a\u000aIf `__str__` is missing, `__repr__` serves as a fallback.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1776,2020,141,unistr('What does the following block do?\u000a\u000a```python\u000atry:\u000a    risky_code()\u000aexcept TypeError:\u000a    print(''Type mismatch'')\u000a```'),'It attempts to execute `risky_code()`. If a `TypeError` occurs, the error is caught and ''Type mismatch'' is printed instead of crashing.','2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1777,2042,141,unistr('What output does this code produce?\u000a\u000a```python\u000atry:\u000a    print(5 / 0)\u000aexcept ZeroDivisionError:\u000a    print(''Oops'')\u000afinally:\u000a    print(''Done'')\u000a```'),unistr('```\u000aOops\u000aDone\u000a```\u000aThe `finally` block runs regardless of whether an exception occurred.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1778,2021,141,'What does `raise ValueError(''Invalid length!'')` do?',unistr('It manually triggers a `ValueError` exception with the message ''Invalid length!''.\u000a\u000aThis stops normal execution and allows the exception to be caught by an appropriate `except` block.'),'2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1779,2022,141,unistr('What is created by the following code?\u000a\u000a```python\u000aclass BalanceError(Exception):\u000a    pass\u000a```'),'A custom exception class named `BalanceError` that inherits from `Exception`. It can be raised with `raise BalanceError(...)`.','2026-06-19',1,2.5,0);
INSERT INTO flashcards VALUES(1780,2023,141,unistr('What happens when this code runs?\u000a\u000a```python\u000aclass BalanceError(Exception): pass\u000a\u000aclass Customer:\u000a    def __init__(self, name, balance):\u000a        if balance < 0:\u000a            raise BalanceError(''Negative balance'')\u000a        self.name = name\u000a        self.balance = balance\u000a\u000atry:\u000a    cust = Customer(''Alice'', -50)\u000aexcept BalanceError:\u000a    cust = Customer(''Alice'', 0)\u000aprint(cust.name)\u000a```'),unistr('```\u000aAlice\u000a```\u000aThe `BalanceError` is caught, and a new `Customer` is created with a valid balance, printing ''Alice''.'),'2026-06-19',1,2.5,0);
INSERT INTO quiz_questions VALUES(1,141,2043,'Which of the following class names follows the CamelCase convention used for Python classes?','customer_account','CustomerAccount','customerAccount','Customer_Account','b','The recommended style for Python class names is CamelCase (also called PascalCase), e.g. `CustomerAccount`. The course uses `class Customer:`, `class BankAccount:`, etc.','application',1);
INSERT INTO quiz_questions VALUES(2,141,2044,'Which of the following method names follows the snake_case convention recommended for methods and attributes?','CalculateInterest','calculate_interest','calculateInterest','Calculate_Interest','b','Method and attribute names should be in snake_case: all lowercase with underscores. For example, the course uses `set_name`, `balance`, `compute_interest`.','application',1);
INSERT INTO quiz_questions VALUES(3,141,1997,unistr('What does the following code print?\u000a\u000a```python\u000atype([1, 2, 3, 4, 5])\u000a```'),'<class ''list''>','''list''','list','<class ''int''>','a','`type()` returns the class of the object. When printed, it shows `<class ''list''>`. The course example exactly demonstrates this.','output',2);
INSERT INTO quiz_questions VALUES(4,141,1998,'Which of the following strings is **guaranteed** to appear in the list returned by `dir([1, 2, 3, 4])`?','__add__','Customer','type','1','a','`dir()` returns all attributes and methods, including dunder (double underscore) methods. The course explicitly shows `''__add__''` in the sample output.','output',2);
INSERT INTO quiz_questions VALUES(5,141,1999,unistr('Consider the following code:\u000a\u000a```python\u000aclass Customer:\u000a    pass\u000a\u000ac_one = Customer\u000a```\u000aWhat is `c_one`?'),'An instance of `Customer`','A reference to the class `Customer`','`None`','A `TypeError` occurs','b','`c_one = Customer` assigns the class itself to `c_one`. To create an instance you must call the class: `Customer()`. The course warns that forgetting parentheses gives a reference to the class, not an instance.','error',2);
INSERT INTO quiz_questions VALUES(6,141,2045,unistr('What is wrong with the following method definition?\u000a\u000a```python\u000aclass Customer:\u000a    def identify(name):\u000a        print(''I am Customer '' + name)\u000a```'),'The method is missing the `self` parameter.','The method must be decorated with `@classmethod`.','`print` cannot be used inside a class method.','The method name `identify` is reserved.','a','Every instance method must include `self` as the first parameter. Here, `def identify(name):` is missing `self`, so Python will pass the instance as `name` and you cannot access the instance properly.','error',2);
INSERT INTO quiz_questions VALUES(7,141,2046,unistr('What does the following code print?\u000a\u000a```python\u000aclass Customer:\u000a    def set_name(self, new_name):\u000a        self.name = new_name\u000a\u000acust1 = Customer()\u000acust1.set_name(''Lara de Silva'')\u000acust2 = Customer()\u000acust2.set_name(''Rashid Volkov'')\u000aprint(cust1.name)\u000a```'),'Rashid Volkov','Lara de Silva','None','An AttributeError occurs','b','Attributes created via `self.name = …` are stored on the individual instance. `cust1` and `cust2` have their own separate copies, so `cust1.name` remains ''Lara de Silva''.','output',2);
INSERT INTO quiz_questions VALUES(8,141,2047,'Which statement best describes encapsulation in object‑oriented programming?','Bundling data (attributes) and behaviour (methods) together inside a class.','A child class inheriting all attributes and methods from a parent class.','The ability to use the same method name across different classes.','Using double underscores to make attributes private.','a','Encapsulation means bundling state and behaviour inside a class and hiding the internal details. The course defines it as ''bundling data (attributes) and methods (behavior) within a class''.','definition',2);
INSERT INTO quiz_questions VALUES(9,141,2048,'In the statement `class SavingsAccount(BankAccount):`, what is `BankAccount` called?','superclass','subclass','instance','object','a','The class whose name appears in parentheses is the parent (superclass). In `class SavingsAccount(BankAccount):`, `BankAccount` is the superclass.','comparison',2);
INSERT INTO quiz_questions VALUES(10,141,2049,'Given `class SavingsAccount(BankAccount):`, what is `SavingsAccount`?','A superclass','A subclass','A class attribute','An instance','b','`SavingsAccount` is the child class (subclass) because it inherits from `BankAccount`. The child can extend or override the parent’s functionality.','comparison',2);
INSERT INTO quiz_questions VALUES(11,141,2011,unistr('Given the following code, what does the last `print` statement output?\u000a\u000a```python\u000aclass BankAccount: pass\u000aclass SavingsAccount(BankAccount): pass\u000asavings_acct = SavingsAccount()\u000aacct = BankAccount()\u000aprint(isinstance(savings_acct, BankAccount))\u000a```'),'False','None','True','A TypeError','c','Because `SavingsAccount` inherits from `BankAccount`, an instance of the subclass is also an instance of the superclass. This is the ''is‑a'' relationship demonstrated in the course.','output',2);
INSERT INTO quiz_questions VALUES(12,141,2041,'What is the main difference between the `__str__` and `__repr__` methods?','`__str__` is for user‑friendly output, while `__repr__` is for an unambiguous developer representation.','`__repr__` is called by `print()`, while `__str__` is used by the REPL.','They are identical; Python uses them interchangeably.','`__str__` must return a string, but `__repr__` can return any type.','a','`__str__` provides an informal, user‑friendly string representation; `__repr__` is intended for developers and should be as unambiguous as possible. If `__str__` is missing, `__repr__` is used as a fallback.','comparison',2);
INSERT INTO quiz_questions VALUES(13,141,2003,unistr('What is wrong with the following code?\u000a\u000a```python\u000aclass Customer\u000a    pass\u000a```'),'`class` must be lowercase.','A colon is missing after the class name.','The class body must contain a `__init__` method.','`pass` cannot be used as a placeholder.','b','Every class definition must have a colon at the end of the header line. The course example is `class Customer:`. Without the colon, Python raises a `SyntaxError`.','error',3);
INSERT INTO quiz_questions VALUES(14,141,2000,unistr('Consider the following class and call:\u000a\u000a```python\u000aclass Customer:\u000a    def identify(name):\u000a        print(''I am Customer '' + name)\u000a\u000acust = Customer()\u000acust.identify(''Laura'')\u000a```\u000aWhat happens when the code runs?'),'`TypeError: identify() takes 1 positional argument but 2 were given`','Prints `I am Customer Laura`','`NameError: name ''self'' is not defined`','`AttributeError: ''Customer'' object has no attribute ''identify''`','a','When `cust.identify(''Laura'')` is called, Python sends two arguments: the instance `cust` (as `self`) and the string `''Laura''`. But the method is defined with only one parameter `name`, so a `TypeError` is raised because it received two arguments.','error',3);
INSERT INTO quiz_questions VALUES(15,141,2001,unistr('What happens when you run this code?\u000a\u000a```python\u000aclass Customer:\u000a    def set_name(self, new_name):\u000a        name = new_name\u000a\u000acust = Customer()\u000acust.set_name(''Lara de Silva'')\u000aprint(cust.name)\u000a```'),'Prints `Lara de Silva`','`NameError: name ''self'' is not defined`','`AttributeError: ''Customer'' object has no attribute ''name''`','Prints `None`','c','Inside a method, assigning to a bare name (`name = ...`) creates a local variable. To create an instance attribute you must use `self.name = ...`. Because no attribute is actually created, accessing `cust.name` raises an `AttributeError`.','output',3);
INSERT INTO quiz_questions VALUES(16,141,2004,unistr('What is the value of `cust.name` after executing the following code?\u000a\u000a```python\u000aclass Customer:\u000a    def __int__(self, name):\u000a        self.name = name\u000a\u000acust = Customer(''Lara de Silva'')\u000aprint(cust.name)\u000a```'),'Lara de Silva','None','An AttributeError occurs','A TypeError occurs','c','The special method must be named `__init__` (double underscore, i‑n‑i‑t, double underscore). Misspelling it as `__int__` means Python never calls it. The default `__init__` does nothing, so the `name` attribute is never created, causing an `AttributeError`.','output',3);
INSERT INTO quiz_questions VALUES(17,141,2005,unistr('What does the following code print?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, name, items=[]):\u000a        self.name = name\u000a        self.items = items\u000a\u000ac1 = Customer(''Alice'')\u000ac2 = Customer(''Bob'')\u000ac1.items.append(''book'')\u000aprint(c2.items)\u000a```'),'[''book'']','[]','An error occurs','None','a','Default arguments are evaluated only once, at function definition time. When a mutable default (like an empty list) is used, all instances share the same list object. Thus `c1.items.append(...)` also changes `c2.items`.','output',3);
INSERT INTO quiz_questions VALUES(18,141,2006,unistr('Given the following code, what is printed on the last line?\u000a\u000a```python\u000aclass Employee:\u000a    MIN_SALARY = 30000\u000a    def __init__(self, name, salary):\u000a        self.name = name\u000a        self.salary = salary\u000a\u000aemp = Employee(''John'', 40000)\u000aEmployee.MIN_SALARY = 35000\u000aprint(emp.MIN_SALARY)\u000a```'),'30000','35000','40000','An AttributeError occurs','b','Class attributes can be accessed via an instance. When `Employee.MIN_SALARY` is changed, all future lookups (including through instances) see the new value. So `emp.MIN_SALARY` prints 35000.','output',3);
INSERT INTO quiz_questions VALUES(19,141,2034,unistr('Consider the following two classes:\u000a\u000a```python\u000aclass BankAccount:\u000a    pass\u000a\u000aclass SavingsAccount(BankAccount):\u000a    pass\u000a```\u000aWhich of the following statements is true?'),'`BankAccount` is a `SavingsAccount`.','Neither is a subclass of the other.','A `SavingsAccount` instance is also an instance of `BankAccount`.','Both classes are completely unrelated.','c','Inheritance creates an ''is‑a'' relationship. Because `SavingsAccount` inherits from `BankAccount`, an instance of the child is also considered an instance of the parent. Therefore, a `SavingsAccount` is a `BankAccount`.','comparison',3);
INSERT INTO quiz_questions VALUES(20,141,2035,'A function `process_account(acct)` calls `acct.withdraw(100)`. If you can pass both `BankAccount` objects and `CheckingAccount` objects to this function and it works correctly, what principle does this illustrate?','Encapsulation','Inheritance','Abstract base classes','Polymorphism','d','Polymorphism means that objects of different classes can be used through a common interface. Here, `acct.withdraw(100)` works regardless of the specific type, as long as the object has a compatible `withdraw` method.','scenario',3);
INSERT INTO quiz_questions VALUES(21,141,2007,unistr('Using the following code, what does the last line print?\u000a\u000a```python\u000aclass Employee:\u000a    MIN_SALARY = 30000\u000a    def __init__(self, name, salary):\u000a        self.name = name\u000a        self.salary = salary\u000a\u000aemp1 = Employee(''John'', 40000)\u000aemp2 = Employee(''Jane'', 60000)\u000aemp1.MIN_SALARY = 50000\u000aprint(emp2.MIN_SALARY)\u000a```'),'30000','50000','An AttributeError occurs','None','a','Assigning `emp1.MIN_SALARY = 50000` does not change the class attribute; it creates a new instance attribute named `MIN_SALARY` on `emp1`. Other instances still see the original class value, 30000.','output',3);
INSERT INTO quiz_questions VALUES(22,141,2008,unistr('What happens when you run the following code?\u000a\u000a```python\u000aclass Employee:\u000a    def __init__(self, name, salary):\u000a        self.name = name\u000a        self.salary = salary\u000a    \u000a    def from_file(filename):\u000a        with open(filename, ''r'') as f:\u000a            name = f.readline().strip()\u000a            salary = int(f.readline().strip())\u000a        return Employee(name, salary)\u000a\u000aemp = Employee.from_file(''employee_data.txt'')\u000a```\u000a(Assume the file exists and contains valid data.)'),'`emp` becomes a valid `Employee` instance.','`TypeError: from_file() takes 1 positional argument but 2 were given`','`NameError: name ''cls'' is not defined`','`AttributeError: type object ''Employee'' has no attribute ''from_file''`','b','Without the `@classmethod` decorator, `from_file` is a regular instance method. Calling it on the class (`Employee.from_file(...)`) passes the class as the first argument implicitly, but the method only accepts `filename`. This results in a `TypeError` because it receives two arguments.','error',3);
INSERT INTO quiz_questions VALUES(23,141,2009,unistr('Examine the following alternative constructor:\u000a\u000a```python\u000aclass Employee:\u000a    def __init__(self, name, salary):\u000a        self.name = name\u000a        self.salary = salary\u000a    \u000a    @classmethod\u000a    def from_file(cls, filename):\u000a        with open(filename, ''r'') as f:\u000a            name = f.readline().strip()\u000a            salary = int(f.readline().strip())\u000a        cls(name, salary)\u000a\u000aemp = Employee.from_file(''employee_data.txt'')\u000aprint(emp)\u000a```\u000aWhat will `print(emp)` output?'),'A string representation of the new Employee','An error','None','The filename as a string','c','The alternative constructor must `return` the new instance. Here, `cls(name, salary)` creates an instance but the result is discarded because there is no `return` statement. Hence the method returns `None`, which is assigned to `emp`.','output',3);
INSERT INTO quiz_questions VALUES(24,141,2010,unistr('Which error will the following code produce?\u000a\u000a```python\u000aclass BankAccount:\u000a    pass\u000a\u000aclass SavingsAccount(BankAccount)\u000a    pass\u000a```'),'`NameError`: `BankAccount` is not defined','`TypeError`: `SavingsAccount` is not a class','No error; it defines a subclass correctly','`SyntaxError`: invalid syntax','d','The second class definition is missing the colon after the parentheses. The correct syntax is `class SavingsAccount(BankAccount):`. Without the colon, Python raises a `SyntaxError`.','error',3);
INSERT INTO quiz_questions VALUES(25,141,2012,unistr('What happens when the following code is executed?\u000a\u000a```python\u000aclass BankAccount:\u000a    def __init__(self, balance):\u000a        self.balance = balance\u000a\u000aclass SavingsAccount(BankAccount):\u000a    def __init__(self, balance, interest_rate):\u000a        self.interest_rate = interest_rate\u000a\u000aacct = SavingsAccount(1000, 0.05)\u000aprint(acct.balance)\u000a```'),'`AttributeError: ''SavingsAccount'' object has no attribute ''balance''`','Prints `1000`','`TypeError: __init__() takes 2 positional arguments but 3 were given`','Prints `None`','a','When overriding `__init__` in a child class, you must explicitly call the parent’s `__init__` if you want the parent’s initialisation to run. Here, that call is missing, so `self.balance` is never created, resulting in an `AttributeError`.','output',3);
INSERT INTO quiz_questions VALUES(26,141,2014,unistr('What will be the balance after executing the following?\u000a\u000a```python\u000aclass BankAccount:\u000a    def __init__(self, balance):\u000a        self.balance = balance\u000a    def withdraw(self, amount):\u000a        self.balance -= amount\u000a\u000aclass SavingsAccount(BankAccount):\u000a    def withdraw(self, amount):\u000a        print("Logging withdrawal")\u000a        # forgot to call parent''s withdraw\u000a\u000aacct = SavingsAccount(500)\u000aacct.withdraw(100)\u000aprint(acct.balance)\u000a```'),'400','500','An error occurs','300','b','When you override a method, the parent’s version is completely replaced unless you explicitly call it. Here, `SavingsAccount.withdraw` does not call `BankAccount.withdraw`, so `self.balance` remains 500.','output',3);
INSERT INTO quiz_questions VALUES(27,141,2038,unistr('Given the following class, what does the comparison print?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, id, name):\u000a        self.id = id\u000a        self.name = name\u000a\u000ac1 = Customer(1, ''Alice'')\u000ac2 = Customer(1, ''Alice'')\u000aprint(c1 == c2)\u000a```'),'True','False','A TypeError','None','b','By default, the `==` operator compares object identity (memory address), not the values of attributes. Since `c1` and `c2` are two distinct objects, the comparison returns `False`.','output',3);
INSERT INTO quiz_questions VALUES(28,141,2039,unistr('Consider the following classes and a function that expects a `BankAccount`:\u000a\u000a```python\u000aclass BankAccount:\u000a    def withdraw(self, amount):\u000a        self.balance -= amount\u000a\u000aclass CheckingAccount(BankAccount):\u000a    def withdraw(self, amount, fee):\u000a        if amount + fee <= self.limit:\u000a            BankAccount.withdraw(self, amount + fee)\u000a\u000adef process(acct):\u000a    acct.withdraw(50)\u000a\u000achk = CheckingAccount()\u000achk.balance = 200\u000achk.limit = 100\u000aprocess(chk)\u000a```\u000aWhat happens when `process(chk)` is called?'),'50 is withdrawn from `chk` with no fee.','The withdrawal is processed with a default fee of 0.','`chk.balance` becomes 150.','A `TypeError` is raised because `withdraw()` is missing the `fee` argument.','d','The function `process` calls `acct.withdraw(50)`, passing only the `amount`. However, `CheckingAccount.withdraw` has an additional required parameter `fee`. Since it is not provided, Python raises a `TypeError`. This violates polymorphism.','error',1);
INSERT INTO quiz_questions VALUES(29,141,2015,unistr('What is the immediate result of defining the following `__eq__` method?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, id, name):\u000a        self.id = id\u000a        self.name = name\u000a    def __eq__(self, other):\u000a        return (self.id = other.id)\u000a```'),'A `SyntaxError` is raised when the class is defined.','A `TypeError` is raised when comparing two `Customer` objects.','The method works, but comparisons always return `True`.','A `NameError` occurs because `other` is not defined.','a','The expression `(self.id = other.id)` uses assignment (`=`), which is not allowed in an expression context. This causes a `SyntaxError` immediately when the class is defined.','error',1);
INSERT INTO quiz_questions VALUES(30,141,2016,unistr('Given the following class definitions:\u000a\u000a```python\u000aclass BankAccount:\u000a    def __init__(self, number):\u000a        self.number = number\u000a    def __eq__(self, other):\u000a        return (self.number == other.number and \u000a                type(self) == type(other))\u000a\u000aclass SavingsAccount(BankAccount):\u000a    pass\u000a\u000aacct = BankAccount(123)\u000asav = SavingsAccount(123)\u000aprint(acct == sav)\u000a```\u000aWhat does the `print` statement output?'),'True','False','An AttributeError','A TypeError','b','The `__eq__` method includes a strict type check `type(self) == type(other)`. Even though a `SavingsAccount` inherits from `BankAccount`, their types are not identical, so the equality returns `False`.','output',1);
INSERT INTO quiz_questions VALUES(31,141,2040,'A class defines `__eq__` so that two objects are equal when their `id` attributes match. The class does **not** define `__ne__`. What does `obj1 != obj2` return?','An error because `__ne__` is not defined.','Always `True`.','The opposite of `obj1 == obj2`.','`None`.','c','If `__ne__` is not defined, Python’s default implementation returns `not (self == other)`. So `obj1 != obj2` will be the logical opposite of the custom `__eq__`.','output',1);
INSERT INTO quiz_questions VALUES(32,141,2017,unistr('Consider the following code:\u000a\u000a```python\u000aclass BankAccount:\u000a    def __init__(self, number):\u000a        self.number = number\u000a    def __eq__(self, other):\u000a        print(''BankAccount __eq__() called'')\u000a        return self.number == other.number\u000a\u000aclass SavingsAccount(BankAccount):\u000a    def __init__(self, number, interest_rate):\u000a        BankAccount.__init__(self, number)\u000a        self.interest_rate = interest_rate\u000a    def __eq__(self, other):\u000a        print(''SavingsAccount __eq__() called'')\u000a        return self.number == other.number\u000a\u000asa = SavingsAccount(1, 0.05)\u000aba = BankAccount(1)\u000aprint(sa == ba)\u000a```\u000aWhat is printed first?'),'BankAccount __eq__() called','SavingsAccount __eq__() called','Both are called','An error occurs','b','Python always starts method lookup from the class of the left operand. Here `sa` is a `SavingsAccount`, so `SavingsAccount.__eq__` is called first (printing its message), regardless of the right operand’s type.','output',1);
INSERT INTO quiz_questions VALUES(33,141,2018,unistr('What is the output of the following code?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, name, balance):\u000a        self.name = name\u000a        self.balance = balance\u000a    def __str__(self):\u000a        return f"Customer:\\nname: {self.name}\\nbalance: {self.balance}"\u000a\u000acust = Customer(''Maryam Azar'', 3000)\u000aprint(cust)\u000a```'),unistr('Customer:\u000aname: Maryam Azar\u000abalance: 3000'),'Customer(''Maryam Azar'', 3000)','Customer: name: Maryam Azar balance: 3000','<__main__.Customer object at 0x...>','a','`print(cust)` invokes `cust.__str__()`. The method returns a string containing newline characters, producing three lines of output as shown.','output',1);
INSERT INTO quiz_questions VALUES(34,141,2019,unistr('What does the following code print?\u000a\u000a```python\u000aclass Customer:\u000a    def __init__(self, name, balance):\u000a        self.name = name\u000a        self.balance = balance\u000a    def __repr__(self):\u000a        return f"Customer(''{self.name}'', {self.balance})"\u000a\u000acust = Customer(''Maryam Azar'', 3000)\u000aprint(cust)\u000a```'),'Customer: name: Maryam Azar balance: 3000','Customer(''Maryam Azar'', 3000)','Customer: Maryam Azar, 3000','An error because __str__ is not defined','b','When `__str__` is not defined, `print()` and `str()` fall back to the `__repr__` method. Thus the output is the formal representation `Customer(''Maryam Azar'', 3000)`.','output',1);
INSERT INTO quiz_questions VALUES(35,141,2020,unistr('What is wrong with the following error‑handling code?\u000a\u000a```python\u000atry:\u000a    risky_operation()\u000aexcept Exception:\u000a    print(''Something went wrong'')\u000aexcept ValueError:\u000a    print(''Invalid value'')\u000a```'),'`except ValueError` will never be reached because `Exception` catches all exceptions first.','You cannot have two `except` blocks.','`Exception` must be the last except block.','The code is correct; both exceptions will be caught as needed.','c','Python checks except blocks in order. Because `ValueError` is a subclass of `Exception`, the first `except Exception` will catch it as well, making the second block unreachable. More specific exceptions must come first.','error',1);
INSERT INTO quiz_questions VALUES(36,141,2042,unistr('What will be printed by the following code before it crashes?\u000a\u000a```python\u000atry:\u000a    print(5 / 0)\u000aexcept TypeError:\u000a    print(''Type error'')\u000afinally:\u000a    print(''Cleanup'')\u000a```'),unistr('Type error\u000aCleanup'),'Cleanup','Type error','5 / 0','d','The division by zero raises a `ZeroDivisionError`, which is not a `TypeError`. The `except` clause is skipped. However, the `finally` block always runs, so ''Cleanup'' is printed. Afterwards, the program crashes with the unhandled exception.','output',1);
INSERT INTO quiz_questions VALUES(37,141,2021,unistr('Consider the following code:\u000a\u000a```python\u000aclass BalanceError(Exception):\u000a    pass\u000a\u000aclass Customer:\u000a    def __init__(self, name, balance):\u000a        if balance < 0:\u000a            raise ValueError(''Balance must be non-negative'')\u000a        self.name = name\u000a        self.balance = balance\u000a\u000atry:\u000a    cust = Customer(''Larry Torres'', -100)\u000aexcept BalanceError:\u000a    print(''Balance error caught'')\u000a```\u000aWhat is the result?'),'A `ValueError` is raised and the program crashes.','The string ''Balance error caught'' is printed.','`cust` is created with balance -100.','A `TypeError` is raised.','a','The `__init__` raises a `ValueError`, but the `try` block only catches `BalanceError`. Since `ValueError` is not a subclass of `BalanceError`, it goes uncaught and the program terminates with a `ValueError`.','output',1);
INSERT INTO quiz_questions VALUES(38,141,2022,unistr('What happens when you try to raise the following custom exception?\u000a\u000a```python\u000aclass BalanceError:\u000a    pass\u000a\u000adef check_balance(balance):\u000a    if balance < 0:\u000a        raise BalanceError(''Negative balance'')\u000a\u000acheck_balance(-10)\u000a```'),'The exception is raised and caught as a normal exception.','`TypeError: exceptions must derive from BaseException`','`NameError: BalanceError not defined`','`SyntaxError: Invalid exception class`','b','In Python, exceptions must be subclasses of `BaseException`. The class `BalanceError` here does not inherit from `Exception` (or any base exception), so attempting to `raise` it results in `TypeError: exceptions must derive from BaseException`.','error',1);
INSERT INTO quiz_questions VALUES(39,141,2023,unistr('What does the following code print?\u000a\u000a```python\u000aclass BalanceError(Exception):\u000a    pass\u000a\u000aclass Customer:\u000a    def __init__(self, name, balance):\u000a        if balance < 0:\u000a            raise BalanceError(''Balance has to be non-negative!'')\u000a        self.name = name\u000a        self.balance = balance\u000a\u000atry:\u000a    cust = Customer(''Larry Torres'', -100)\u000aexcept BalanceError:\u000a    pass\u000a\u000aprint(cust.name)\u000a```'),'Larry Torres','An `AttributeError` is raised','A `NameError` is raised','None','c','When the constructor raises `BalanceError`, the assignment `cust = ...` is never completed. Thus `cust` is not defined, and attempting to access `cust.name` causes a `NameError`.','output',1);
INSERT INTO quiz_questions VALUES(40,141,2037,unistr('Consider the following class method:\u000a\u000a```python\u000aclass Employee:\u000a    MIN_SALARY = 30000\u000a\u000a    @classmethod\u000a    def print_min_salary(self):\u000a        print(self.name)\u000a\u000aEmployee.print_min_salary()\u000a```\u000aWhat happens when `print_min_salary()` is called?'),'Prints `Employee`','Prints `MIN_SALARY`','`TypeError` because `self` is not defined','`AttributeError` because `Employee` has no attribute `name`','d','Even though the parameter is named `self`, it behaves as `cls` because the method is decorated with `@classmethod`. Python passes the class `Employee` as the first argument. Since `Employee` has no `name` attribute, accessing `self.name` raises an `AttributeError`.','error',1);
INSERT INTO quiz_questions VALUES(42,137,1821,unistr('What does this code print?\u000a\u000a```python\u000ax = 0.1 + 0.2\u000aprint(x == 0.3)\u000a```'),'True','False','Error','0.3','b','Floating‑point arithmetic causes 0.1 + 0.2 to result in something like 0.30000000000000004, so the comparison with 0.3 is False.','output',1);
INSERT INTO quiz_questions VALUES(43,137,1821,unistr('What causes the following code to NOT print ''equal''?\u000a\u000a```python\u000aif 0.1 + 0.2 == 0.3:\u000a    print(''equal'')\u000a```'),'Syntax error in the condition','Floating‑point representation error','The if condition evaluates to False','Both b and c','d','Due to binary floating‑point representation, 0.1 + 0.2 != 0.3. Thus the condition is False, and ''equal'' is not printed.','error',1);
INSERT INTO quiz_questions VALUES(44,137,1821,unistr('Which of the following comparisons evaluates to True?\u000a\u000a```python\u000afrom decimal import Decimal\u000aa = Decimal(''0.1'') + Decimal(''0.2'')\u000a```'),'a == 0.3','a == Decimal(''0.3'')','float(a) == 0.3','None of the above','b','Decimal(''0.1'') + Decimal(''0.2'') yields an exact Decimal(''0.3''). Comparing it with Decimal(''0.3'') returns True, while comparing with float 0.3 fails.','output',1);
INSERT INTO quiz_questions VALUES(45,137,1824,unistr('What is the output of this code?\u000a\u000a```python\u000afrom dataclasses import dataclass\u000a\u000a@dataclass\u000aclass Cookie:\u000a    name: str\u000a    quantity: int = 0\u000a    cost: float = 1.0\u000a    \u000a    @property\u000a    def value_of_goods(self):\u000a        return int(self.quantity) * self.cost\u000a\u000ac = Cookie(''ginger'', 8, 2.5)\u000aprint(c.value_of_goods)\u000a```'),'<property object>','20.0','20','Error because value_of_goods is not callable','b','The @property decorator makes value_of_goods accessible like an attribute. Accessing it invokes the getter and returns the computed value 20.0.','output',1);
INSERT INTO quiz_questions VALUES(46,137,1824,unistr('What error is raised if you call `c.value_of_goods()` instead of `c.value_of_goods`?\u000a\u000a(Assuming c is an instance of the Cookie dataclass from the previous question.)'),'TypeError: ''float'' object is not callable','TypeError: ''property'' object is not callable','AttributeError','No error; it works','a','Accessing the property returns a float (20.0). Adding parentheses attempts to call that float, raising TypeError: ''float'' object is not callable.','error',1);
INSERT INTO quiz_questions VALUES(47,137,1825,unistr('What happens when you run this code?\u000a\u000a```python\u000afrom dataclasses import dataclass\u000a\u000a@dataclass(frozen=True)\u000aclass Cookie:\u000a    name: str\u000a    quantity: int = 0\u000a\u000ac = Cookie(''ginger'')\u000ac.quantity = 5\u000a```'),'It silently fails','Raises FrozenInstanceError','Updates quantity to 5','TypeError','b','Setting frozen=True makes the dataclass instance immutable. Any attempt to modify a field raises dataclasses.FrozenInstanceError.','output',1);
INSERT INTO quiz_questions VALUES(48,137,1825,'Which statement about `@dataclass(frozen=True)` is FALSE?','It makes instances hashable','It prevents any modification, even to mutable fields'' contents','You can modify the items of a list field if one exists','Assigning to a field raises FrozenInstanceError','b','frozen=True only prevents reassignment of fields. If a field is a mutable object (e.g., list), its internal state can still be modified, so statement b is false.','error',1);
INSERT INTO quiz_questions VALUES(49,125,1764,'The ''domain'' of a column refers to:','The set of permissible values defined by its data type and any additional constraints','The physical storage location of the column on disk','The table that contains the column','Only the data type of the column, not including constraints','a','The domain is the complete specification of what values a column may contain, encompassing both the data type and all column-level constraints.','comparison',2);
INSERT INTO quiz_questions VALUES(50,125,1741,unistr('In the statement:\u000a\u000a```sql\u000aALTER TABLE students\u000aALTER COLUMN average_grade TYPE integer\u000aUSING ROUND(average_grade);\u000a```\u000a\u000awhat is the purpose of the `USING` clause?'),'To specify how existing numeric values should be converted to integers','To permanently round the `average_grade` column for future inserts','To create a new column with the rounded values','To prevent data loss by skipping rows that cannot be converted','a','When changing a column''s type, the `USING` clause provides a transformation to be applied to each existing value, ensuring a proper conversion (e.g., rounding a numeric to integer).','application',3);
INSERT INTO quiz_questions VALUES(51,125,1742,unistr('In the command:\u000a\u000a```sql\u000aALTER TABLE table_name\u000aADD CONSTRAINT some_name UNIQUE(column_name);\u000a```\u000a\u000awhat is `some_name`?'),'The user-defined name given to the new constraint','The name of the column being constrained','The table that will receive the constraint','The type of constraint being added','a','When adding a constraint, you can provide a name so that the constraint can be easily referenced later (e.g., to drop it). The name follows the keyword `CONSTRAINT`.','application',2);
INSERT INTO quiz_questions VALUES(52,125,1765,'You try to delete a row from table `universities` while there are still rows in `professors` referencing it via a foreign key with default `ON DELETE NO ACTION`. What happens?','The DELETE fails and an error is raised','The university is deleted and the professors'' foreign key becomes NULL','The delete succeeds and the referencing rows are automatically removed','The university is deleted and the professors table is marked as invalid','a','With `ON DELETE NO ACTION` (the default), the database enforces referential integrity by rejecting the deletion if any child rows exist. This prevents orphaned references.','error',3);
INSERT INTO quiz_questions VALUES(53,125,1766,'Which of the following would be the best choice for a primary key based on the requirement that primary keys should be time-invariant (never change)?','A serial `id` column','An `email` column','A `lastname` column','A `phone_number` column','a','Primary keys must be immutable. Surrogate keys like `serial` are designed to be stable; natural keys such as emails or phone numbers risk becoming outdated, causing costly updates and integrity issues.','comparison',3);
INSERT INTO quiz_questions VALUES(54,72,1032,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000anp_height = np.array([1.73, 1.68, 1.71, 1.89, 1.79])\u000anp_weight = np.array([65.4, 59.2, 63.6, 88.4, 68.7])\u000abmi = np_weight / np_height ** 2\u000a```\u000aWhat type of operation is performed in the last line?'),'A loop over each element sequentially.','A Python list concatenation.','A broadcasting error because arrays are different sizes.','A vectorized element‑wise operation.','d','Vectorization allows operations on whole arrays at once, without writing Python loops. It''s faster and more concise. The expression computes BMI for each corresponding pair.','prediction',2);
INSERT INTO quiz_questions VALUES(55,72,1033,unistr('What does this code output?\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([1.0, "is", True])\u000aprint(arr)\u000a```'),'[1.0, nan, 1.0]','[1.0, ''is'', True]','An error because types are mixed.','[''1.0'', ''is'', ''True'']','d','NumPy arrays must be homogeneous. When given mixed types, it coerces all elements to the most general type, often string. This can lead to unexpected results when you try to do math.','output',3);
INSERT INTO quiz_questions VALUES(56,72,1033,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([1.73, 1.68, ''1.71''])\u000amean_val = np.mean(arr)\u000a```\u000aWhat happens?'),'mean_val will be the numeric mean of 1.73 and 1.68, ignoring the string.','The array becomes all strings; np.mean will raise a TypeError.','An error occurs because you cannot calculate mean of a string array.','The string is converted to float 1.71 and the mean is computed correctly.','b','Because one element is a string, the whole array is cast to string (dtype ''<U...''). Any arithmetic function like np.mean will fail with a TypeError. Always ensure numeric homogeneity.','prediction',3);
INSERT INTO quiz_questions VALUES(57,72,1033,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([10, 20.5, 30])\u000aprint(arr.dtype)\u000a```\u000aWhat is printed?'),'int64','float64','object','U3','b','NumPy arrays are homogeneous. If any element is a float, the entire array becomes float (float64) to avoid losing precision. This is different from Python lists, which can hold mixed types.','prediction',3);
INSERT INTO quiz_questions VALUES(58,72,1034,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000apython_list = [1, 2, 3]\u000anumpy_array = np.array([1, 2, 3])\u000aprint(python_list + python_list)\u000aprint(numpy_array + numpy_array)\u000a```\u000aWhat are the outputs, in order?'),'[2, 4, 6] and [2, 4, 6]','[1, 2, 3, 1, 2, 3] and [1, 2, 3, 1, 2, 3]','[2, 4, 6] and [1, 2, 3, 1, 2, 3]','[1, 2, 3, 1, 2, 3] and [2, 4, 6]','d','Python lists concatenate when added; NumPy arrays perform vectorized element‑wise addition. This is a crucial difference when working with data.','output',3);
INSERT INTO quiz_questions VALUES(59,72,1034,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000alst = [1, 2]\u000aarr = np.array([1, 2])\u000aresult1 = lst + lst\u000aresult2 = arr + arr\u000aprint(result1, result2)\u000a```\u000aWhat is printed?'),'[2, 4] [2, 4]','[1, 2, 1, 2] [1, 2, 1, 2]','[2, 4] [1, 2, 1, 2]','[1, 2, 1, 2] [2, 4]','d','This highlights a fundamental difference: lists concatenate, arrays add element‑wise. Confusing the two is a common bug when switching between Python lists and NumPy.','output',3);
INSERT INTO quiz_questions VALUES(60,72,1035,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000abmi = np.array([21.85, 20.98, 21.75, 24.75, 21.44])\u000aprint(bmi > 23)\u000a```\u000aWhat is printed?'),'24.75','[21.85, 20.98, 21.75, 24.75, 21.44]','True','[False, False, False, True, False]','d','Boolean indexing starts with a condition that returns a Boolean array of the same shape. That mask can then be used to select elements.','output',2);
INSERT INTO quiz_questions VALUES(61,72,1035,unistr('What is wrong with this code?\u000a\u000a```python\u000aimport numpy as np\u000abmi = np.array([21.85, 20.98, 21.75, 24.75, 21.44])\u000aprint(bmi[bmi > 23 and bmi < 25])\u000a```'),'Boolean indexing cannot use two conditions.','bmi[bmi > 23] returns a smaller array; you cannot use ''and'' on arrays.','The code is perfectly correct.','The condition uses ''and'' instead of ''&''; it will cause a ValueError about truth value of array.','d','For NumPy arrays, logical operations must use bitwise operators & (and) and | (or). Using ''and''/''or'' tries to evaluate the whole array as a single boolean, causing a ValueError.','error',3);
INSERT INTO quiz_questions VALUES(62,72,1035,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000abmi = np.array([21, 23, 25, 22, 30])\u000amask = (bmi > 22) & (bmi < 28)\u000aprint(bmi[mask])\u000a```\u000aWhat is output?'),'[25, 30]','[21, 23, 25, 22]','[23, 25]','[23, 25, 22]','c','Boolean indexing uses a boolean array of the same shape. The `&` operator performs element‑wise logical AND. Remember to use `&` (not `and`) and parentheses around each condition.','output',3);
INSERT INTO quiz_questions VALUES(63,72,1037,'Which code creates a 2D NumPy array with two rows and three columns?','np.array([[1,2,3], [4,5,6]])','np.array((1,2,3), (4,5,6))','np.array([1,2,3], [4,5,6])','np.array([1,2,3,4,5,6], shape=(2,3))','a','A 2D array is created by passing a nested sequence (list of lists) to np.array(). The inner lists become rows. Ensure all inner lists have the same length.','application',2);
INSERT INTO quiz_questions VALUES(64,72,1038,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000anp_2d = np.array([[1.73, 1.68, 1.71, 1.89, 1.79],\u000a                  [65.4, 59.2, 63.6, 88.4, 68.7]])\u000aprint(np_2d.shape)\u000a```\u000aWhat is printed?'),'2','5','(5, 2)','(2, 5)','d','The .shape attribute is a tuple indicating the size of each dimension. For a 2D array, it is (rows, columns). Common mistake: calling shape as a method with parentheses.','output',1);
INSERT INTO quiz_questions VALUES(65,72,1039,unistr('Given:\u000a\u000a```python\u000anp_2d = np.array([[1.73, 1.68, 1.71, 1.89, 1.79],\u000a                  [65.4, 59.2, 63.6, 88.4, 68.7]])\u000aprint(np_2d[0, 2])\u000a```\u000aWhat is output?'),'59.2','1.71','1.68','63.6','b','2D subsetting uses the syntax [row_index, column_index]. np_2d[0, 2] accesses the first row and third column. Avoid using [row][col] if you want cleaner code, though it also works.','output',2);
INSERT INTO quiz_questions VALUES(66,72,1039,'You try to subset a 2D array with np_2d[1, 5]. The array has shape (2, 5). What happens?','It raises an IndexError because column index 5 is out of range.','It returns 68.7.','It returns the last element of the second row.','It returns an empty array.','a','Indexing follows zero‑based numbering. For shape (2,5), columns go from 0 to 4. Accessing column 5 causes an IndexError. Off‑by‑one errors are common.','error',3);
INSERT INTO quiz_questions VALUES(67,72,1040,unistr('Given:\u000a\u000a```python\u000anp_2d = np.array([[1.73, 1.68, 1.71, 1.89, 1.79],\u000a                  [65.4, 59.2, 63.6, 88.4, 68.7]])\u000aprint(np_2d[:, 1:3])\u000a```\u000aWhat is output?'),'array([[1.73, 1.68, 1.71], [65.4, 59.2, 63.6]])','array([1.68, 1.71])','array([[1.68, 1.71], [59.2, 63.6]])','array([[1.68], [59.2]])','c','Slicing a 2D array uses [row_slice, column_slice]. : means ''all''. 1:3 selects columns 1 and 2. The result maintains 2D shape.','output',2);
INSERT INTO quiz_questions VALUES(68,72,1040,'What does np_2d[1, :] return? (np_2d has shape (2,5))','The element at row 1, column 0.','The second column as a 1D array.','A 2x5 array identical to np_2d.','The second row as a 1D array.','d','Using a single index for the row and : for the column selects all columns of that row, resulting in a 1D array. It’s a common way to extract a row.','prediction',3);
INSERT INTO quiz_questions VALUES(69,72,1041,'You have a 2D array np_city with shape (100, 2) where the first column is height and the second is weight. How do you compute the median height?','np.median(np_city[0, :])','np_city.median()','np.median(np_city[:, 0])','np.median(np_city[0])','c','To compute a statistic on one column, slice that column with [:, col_index]. np.median() returns the median of the selected column.','application',2);
INSERT INTO quiz_questions VALUES(70,72,1041,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([1, 2, 3, 100])\u000aprint(np.median(arr))\u000a```\u000aWhat is output?'),'26.5','2.5','2','100','b','np.median() sorts the array and returns the middle value. For even length, it returns the average of the two middle values.','output',2);
INSERT INTO quiz_questions VALUES(71,72,1042,'Your data contains an outlier that inflates the average. Which function provides a more robust measure of central tendency?','np.median()','np.sum()','np.sort()','np.mean()','a','Median is the middle value; it isn''t distorted by a few very large or small numbers. Mean can be pulled significantly by outliers. This is a key concept in data analysis.','scenario',2);
INSERT INTO quiz_questions VALUES(72,72,1043,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([1.73, 1.68, 1.71])\u000aprint(np.sum(arr))\u000a```\u000aWhat is printed?'),'3','5.12 (sum of elements)','5.12','[1.73, 1.68, 1.71]','c','np.sum() adds all elements in the array and returns a scalar. For multi‑dimensional arrays, you can specify an axis.','output',1);
INSERT INTO quiz_questions VALUES(73,72,1044,unistr('What happens after running this?\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([3, 1, 2])\u000asorted_arr = np.sort(arr)\u000aprint(arr)\u000a```'),'sorted_arr is None; np.sort sorts in place.','An error occurs because np.sort doesn''t exist.','arr is unchanged; np.sort returns a sorted copy.','arr becomes [1, 2, 3].','c','np.sort() is a function that returns a sorted copy of the input array. The list method .sort() behaves differently (sorts in place). This distinction can cause confusion.','prediction',2);
INSERT INTO quiz_questions VALUES(74,72,1044,'What is the difference between `np.sort(arr)` and `arr.sort()`?','Both are identical and return a sorted copy.','`np.sort(arr)` returns a sorted copy; `arr.sort()` sorts the array in place and returns `None`.','`np.sort(arr)` only works on 1D arrays; `arr.sort()` works on any array.','`np.sort(arr)` sorts in place; `arr.sort()` returns a copy.','b','`np.sort()` returns a sorted copy, leaving the original unchanged. The `ndarray.sort()` method sorts the array in place and returns `None`. This mirrors the difference between Python''s `sorted()` and `list.sort()`.','comparison',3);
INSERT INTO quiz_questions VALUES(75,72,1045,'Which code generates 5000 height samples with a mean of 1.75 and a standard deviation of 0.20?','np.random.normal(5000, 1.75, 0.20)','np.random.normal(1.75, 0.20, 5000)','np.random.normal(mean=1.75, std=0.20, size=5000)','np.random.normal(0.20, 1.75, 5000)','b','np.random.normal(loc, scale, size) draws samples from a normal distribution. loc is the mean, scale is the standard deviation. The course uses positional arguments.','application',3);
INSERT INTO quiz_questions VALUES(76,72,1045,'You run np.random.normal(1.75, 0.20) without a size argument. What happens?','It returns an array of 1.75 repeated.','It returns None.','It returns a single random float.','It raises an error because size is required.','c','Omitting size yields a single floating‑point sample from the distribution, not an array. This is a useful detail when you need just one random number.','error',3);
INSERT INTO quiz_questions VALUES(77,72,1045,'You run `np.random.normal(loc=0, scale=1, size=5)`. What is the shape of the returned object?','A 1D NumPy array of length 5.','A 5x5 2D array.','A Python list of 5 floats.','A single float.','a','`np.random.normal` with a scalar `size` returns a 1D NumPy array. If `size` is omitted, it returns a scalar. The return type is always a NumPy array for non‑scalar `size`.','prediction',3);
INSERT INTO quiz_questions VALUES(78,72,1046,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000aarr = np.array([1.678, 2.345, 3.123])\u000aprint(np.round(arr, 1))\u000a```\u000aWhat is printed?'),'[1.7, 2.3, 3.1]','[2, 2, 3]','[1.68, 2.35, 3.12]','[1.6, 2.3, 3.1]','a','np.round(array, decimals) rounds each element to the specified number of decimal places. It returns a new array; the original is unchanged.','output',2);
INSERT INTO quiz_questions VALUES(79,72,1046,'What is the key difference between the built‑in round() and np.round()?','round() returns an integer when ndigits omitted; np.round() always returns a float array even with decimals=0.','round() can handle arrays, while np.round() cannot.','np.round() is identical to round() but works on arrays.','np.round() modifies the array in place.','a','round() without ndigits returns an integer (e.g., round(1.68) → 2). np.round() with decimals=0 returns a float array (or float scalar), preserving the array type. This can be important when further array operations are expected.','comparison',3);
INSERT INTO quiz_questions VALUES(80,72,1047,'You have two 1D arrays: height and weight. How do you combine them into a 2D array where height is the first column and weight the second?','np.vstack((height, weight)).T','np.column_stack((height, weight))','np.array([height, weight])','np.column_stack(height, weight)','b','np.column_stack((arr1, arr2)) combines 1D arrays into a 2D array where each input becomes a column. The arrays must have the same length.','application',2);
INSERT INTO quiz_questions VALUES(81,72,1047,unistr('Given:\u000a\u000a```python\u000aimport numpy as np\u000aa = np.array([1, 2, 3])\u000ab = np.array([4, 5, 6])\u000aresult = np.column_stack((a, b))\u000aprint(result.shape)\u000a```\u000aWhat is printed?'),'(2, 3)','(3,)','(6,)','(3, 2)','d','`np.column_stack` takes 1D arrays and stacks them vertically as columns. So with two arrays of length 3, the output shape is (3, 2).','output',2);
INSERT INTO quiz_questions VALUES(82,72,1003,'What does int(5.7) return?','6','5.7','5','''5''','c','int() conversion truncates toward zero, discarding the fractional part. To round to the nearest integer, use round() first.','output',2);
INSERT INTO quiz_questions VALUES(83,72,1003,'You run `int(''3.14'')`. What happens?','It returns 3.','It returns ''3''.','It returns 3.14.','It raises a ValueError because the string ''3.14'' is not a valid integer literal.','d','`int()` can convert a string to an integer only if the string represents a whole number (e.g., ''3''). For a string with a decimal, you must first convert to float (float(''3.14'')) then to int, or use `int(float(''3.14''))`.','error',2);
INSERT INTO quiz_questions VALUES(84,72,1025,unistr('Given:\u000a\u000a```python\u000afam = [''liz'', 1.73, ''emma'', 1.68, ''mom'', 1.71, ''dad'', 1.89]\u000afam.remove(''emma'')\u000aprint(fam)\u000a```\u000aWhat is printed?'),'None','[''liz'', 1.73, ''mom'', 1.71, ''dad'', 1.89]','[''liz'', 1.73, 1.68, ''mom'', 1.71, ''dad'', 1.89]','[''liz'', 1.73, ''emma'', 1.68, ''mom'', 1.71, ''dad'', 1.89]','c','remove(value) deletes the first item matching value from the list. It modifies the list in place and returns None. A common mistake is to try to use the return value.','prediction',2);
INSERT INTO quiz_questions VALUES(85,72,1025,unistr('What does this code print?\u000a\u000a```python\u000aitems = [1, 2, 3, 2]\u000aresult = items.remove(2)\u000aprint(items, result)\u000a```'),'None None','[1, 3, 2] 2','[1, 3, 2] None','[1, 2, 3, 2] None','c','`remove()` modifies the list in place and returns `None`. It only removes the first matching value. To capture the removed value, use `pop(index)` instead.','output',3);
INSERT INTO quiz_questions VALUES(86,72,1026,unistr('Given:\u000a\u000a```python\u000anums = [3, 1, 2]\u000anums.reverse()\u000aprint(nums)\u000a```\u000aWhat is printed?'),'[2, 1, 3]','None','[3, 1, 2]','[1, 2, 3]','a','list.reverse() reverses the elements of the list in place. It returns None, so assigning its result would lose the list. A common mistake is to write `nums = nums.reverse()`.','output',1);
INSERT INTO quiz_questions VALUES(87,72,1048,'You compute np.corrcoef(height, weight) and get a 2x2 matrix. What does the off‑diagonal value represent?','The covariance between height and weight.','The correlation coefficient between height and weight.','The p‑value of the correlation.','The mean of height and weight.','b','np.corrcoef(x, y) returns a 2x2 matrix where the diagonal is 1 (self‑correlation) and the off‑diagonal is the Pearson correlation between x and y. Values range from -1 to 1.','scenario',3);
INSERT INTO quiz_questions VALUES(88,72,1048,'You try to compute correlation with np.corrcoef(height, weight) but get an error because height has NaN values. What should you do?','Correlation cannot be computed with missing values; you must remove or impute them first.','corrcoef automatically ignores NaNs.','Use np.corrcoef(height, weight, nan_policy=''omit'').','Use np.nanmean before corrcoef.','a','np.corrcoef doesn''t skip NaN values; they must be handled beforehand. Using boolean indexing to drop NaNs or filling with a suitable value are common strategies.','error',3);
INSERT INTO quiz_questions VALUES(89,72,1060,'Your dataset has an extremely high value that inflates the mean. What is the most appropriate measure to report?','Standard deviation','Median','Mean','Sum','b','When data contains outliers, the median provides a more reliable measure of central tendency. The mean can be dramatically skewed. Always visualize your data to check for outliers.','scenario',2);
INSERT INTO quiz_questions VALUES(90,72,1061,'You have a NumPy array height_in_inches and want to convert to meters using the factor 0.0254. Which line is correct?','height_m = height_in_inches + 0.0254','height_m = height_in_inches * 0.0254','height_m = height_in_inches / 0.0254','height_m = multiply(height_in_inches, 0.0254)','b','NumPy''s vectorization allows you to multiply the entire array by the conversion factor in one go: height_m = height_in_inches * 0.0254.','scenario',1);
